INSERT INTO module_catalog VALUES(1,'rough-nights-and-hard-days','Rough Nights and Hard Days','Five grim and perilous scenarios by Graeme Davis.','wfrp-4e-rough-nights-and-hard-days/images/page_0_img_1.jpeg');
INSERT INTO module_chapters VALUES(1,1,1,'A Rough Night at the Three Feathers','The Three Feathers Inn','A large coaching inn on the River Reik between Altdorf and Kemperbad, featuring a main bar, dormitory, private rooms, and a riverside dock.','');
INSERT INTO module_chapters VALUES(2,1,2,'A Day at the Trials','Kemperbad Courthouse','A grand courthouse and town square in the free town of Kemperbad, featuring a temporary arena for trial by combat and holding cells.','');
INSERT INTO module_chapters VALUES(3,1,3,'A Night at the Opera','Staatsoper Theatre','A lavish opera house in the wealthy Altestadt district of Nuln, featuring a grand lobby, upper gallery, and exclusive ducal boxes.','');
INSERT INTO module_chapters VALUES(4,1,4,'Nastassia''s Wedding','Schloss Grauenberg','An aging but well-fortified castle perched high above the River Bögen in central Reikland, featuring a formal garden, solar tower, and multiple wings.','');
INSERT INTO module_chapters VALUES(5,1,5,'Lord of Ubersreik','Niederstadt Haus','A modest 3-storey dressed stone mansion in the Morgenseite district of Ubersreik, serving as the venue for an opulent masquerade ball.','');
INSERT INTO module_plots VALUES(121,1,'Plot 1 – A Matter of Import',unistr('_Inside, servants are hurrying to and fro, and the innkeeper is engrossed_\u000a_in conversation with a scribe who carries a visibly bulging purse. It is_\u000a_a full ten minutes before you can attract his attention._\u000a_''Welcome,'' he says at last, ''I''m sorry to have kept you waiting. We_\u000a_have a distinguished guest tonight - the Gravin Maria-Ulrike von_\u000a_Liebwitz of Ambosstein, no less! I hardly know whether I''m coming_\u000a_or going. Now, then - you want a room? What am I saying, of course_\u000a_you do! Ah - excuse me again, I''ll only be a moment.''_\u000a_You wait for another few minutes as he directs a train of servants to_\u000a_the Gravin''s rooms.''So sorry,'' he says as he returns to you. ''It really is_\u000a_mad this evening.''_\u000a**The Other Guests**\u000aAs shown on the map, various rooms are occupied by specific\u000aNPCs. You should make sure the Characters are given rooms that\u000aare not already booked, or that they sleep in the dormitory.\u000aThe Three Feathers has ten single rooms and ten double rooms.\u000aRooms 1-5 on the plan are occupied by the gravin and her party.\u000aRoom 4 is kept empty at her orders. The whole corridor is sealed\u000aoff, with two guards posted at the point marked X on the map.\u000aIf the Characters book a double room, they will be given room 7 or 8 _._\u000aIf they book one or more single rooms, they will be accommodated\u000ain the other wing (rooms 11-20). Since they have arrived relatively\u000aearly in the evening and the inn has not yet started to fill, they may\u000aask for one of the rooms that are marked as being taken by another\u000agroup that has yet to arrive. This is not a problem: simply move the\u000aaffected NPC group to another free room, and make a note of the\u000achange to avoid confusion during play.\u000a**Plot Summaries Plot 1 - A Matter of Import**\u000aPart of the inn has been taken over by Gravin Maria-Ulrike\u000avon Liebwitz of Ambosstein, a niece of Countess Emmanuelle\u000aof Nuln. Her retinue consists of half-a-dozen guards, a lawyer,\u000aa judicial champion, and various servants. She is on her way\u000ato Kemperbad for a trial, having been accused of immoral\u000abehaviour and complicity in a death at one of her aunt''s\u000alegendary parties. The gravin intends to exercise her ancient\u000aright of trial by combat, but an agent working for her accuser,\u000aBaron Otto von Dammenblatz of Wissenberg, is out to disable\u000aBruno Franke, her champion.'));
INSERT INTO module_plots VALUES(122,1,'Plot 2 - Compromising Positions',unistr('The gravin is not the only noble in the inn tonight. Also staying\u000athere - incognito - is Baron Freidrich von Pfeifraucher, the heir\u000aof Count Bruno of Grissenwald. He is accompanied by Fraulein\u000aHanna Lastkahn, a daughter of a wealthy local boat-building\u000afamily. The two have been conducting an illicit affair for some\u000atime, and have taken a room in the inn under the name Herr and\u000aFrau Johann Schmidt. Unfortunately, they have been recognised\u000aby one of Gravin Maria-Ulrike''s servants, who was once employed\u000ain the Pfeifraucher household. A blackmail attempt will follow.'));
INSERT INTO module_plots VALUES(123,1,'Plot 3 - A Face from the Past',unistr('Gustaf Rechtshandler, the Gravin''s lawyer, is a graduate\u000aof the University of Nuln, where he was briefly a member\u000aof a secret society known as the _Ordo Ultima_ . The society was\u000aa front for a Chaos cult following Slaanesh. Rechtshandler left\u000awhen the cult made unwanted demands upon him - but he\u000anever progressed far enough within the society to discover its link\u000ato the Ruinous Powers.'));
INSERT INTO module_plots VALUES(124,1,'Plot 4 – Creating a Scene',unistr('Rechtshandler went on to great professional success, leading\u000ato his current position with the von Liebwitz family. However,\u000athe _Ordo Ultima_ now wants something from him, and one of its\u000aagents approaches him in the inn.'));
INSERT INTO module_plots VALUES(125,1,'Plot 4 - Creating a Scene',unistr('Fraulein Hanna Lastkahn (see _Plot 2_ above) is betrothed to\u000aHerr Thomas Prahmhandler, the heir to another wealthy, local,\u000aboat-building family. He has been informed of his fiancée''s\u000ainfidelity by a servant, and will burst into the inn, very drunk and\u000aaccompanied by three hired thugs.\u000aHe intends to catch the couple _in flagrante_ and horsewhip the\u000ayoung noble - regardless of the consequences.'));
INSERT INTO module_plots VALUES(126,1,'Plot 5 - Ashes to Ashes',unistr('Some smugglers were expecting to meet a boat, but it scraped a\u000alock in the Vorbergland canals and has lost half a day for repairs.\u000aSo, the smugglers must hide their cargo in the inn and wait for\u000athe boat to arrive in the morning.\u000aTo complicate matters, their contraband is Human: Josef\u000aAufwiegler, an agitator wanted for inciting rebellion in Nuln.\u000aHe was treated with a coma-inducing drug. The smugglers\u000aare disguised as a priest and two initiates of Morr, ostensibly\u000ataking him home for burial. The drug was timed to wear off once\u000aAufwiegler was safely aboard the boat, but because of the delay\u000ahe will wake up during the night.'));
INSERT INTO module_plots VALUES(127,1,'Plot 6 - A Fistful of Gold Crowns',unistr('Ursula Kopfgeld, a bounty hunter, is following the smugglers.\u000aShe was very close to catching Aufwiegler when he ''died,'''));
INSERT INTO module_plots VALUES(128,1,'Plot 7 - You''ve Got to Pick a Pocket or Two',unistr('To add to the confusion further, Glimbrin Oddsocks, a Gnome\u000athief (see **Appendix 1: Gnomes** page 86), will attempt to steal\u000aanything he can during the night. Some of his movements are set\u000adown in the _Events_ section, but any time you don''t know where\u000ahe is, he''s all yours to use...\u000a**Events**\u000aThese events can be affected by what the Characters do and\u000awhere they are at any particular time. You should also feel free to\u000achange events as desired.'));
INSERT INTO module_plots VALUES(129,2,'Plot 1 – Trial by Combat',unistr('For her part, Gravin Maria-Ulrike appealed successfully to\u000abe granted her ancient right of trial by combat, thwarting von\u000aDammenblatz who hoped to sway a jury with lurid tales and\u000alow gossip about the goings-on at the Countess Emmanuelle''s\u000ainfamous soirees in Nuln. Both nobles and their champions have\u000aarrived in Kemperbad, and preparations for the trial are under\u000away.\u000a**Plot Summaries Plot 1 - Trial by Combat**\u000aThe trial by combat will take place under the eyes of the town\u000amagistrates and a crowd of onlookers, but von Dammenblatz\u000ahas taken certain precautions to make certain of victory. The\u000aCharacters must thwart his plans or the gravin''s champion is\u000adoomed!'));
INSERT INTO module_plots VALUES(130,2,'Plot 2 - Breakout',unistr('Kemperbad''s court is a busy place, with a dozen or more cases\u000aheard in the course of a typical day, and the arrangements for a trial\u000aby combat between two nobles have disrupted the court''s regular\u000abusiness. The execution of Alfonzo Kappan, an infamous crime\u000alord, has been postponed until after the trial, and his confederates\u000aplan to break him out of the cells behind the courthouse while all\u000aeyes are on the two champions.'));
INSERT INTO module_plots VALUES(131,2,'Plot 3 - Youthful Indiscretions',unistr('As the adventurers may have learned in the Three Feathers, the\u000agravin''s lawyer Gustaf Rechtshandler is being blackmailed by\u000amembers of a Chaos cult.\u000aRechtshandler was once associated with a Slaanesh cult called\u000a_Ordo Ultima_ - unknowingly and very slightly - during his\u000astudent days at the University of Nuln. Three members of the\u000a_Ordo Ultima_ died trying to pressure him into doing the cult a\u000afavour. Now those who sent them are out for revenge. During\u000athe course of the day, two attempts will be made to kill the\u000alawyer.'));
INSERT INTO module_plots VALUES(132,2,'Plot 4 - Innocence Maintained',unistr('Among those attending the trial are a Witch Hunter named\u000aMatthias Hubkind, who has heard disturbing rumours about\u000athe gravin from various Dammenblatz agents. According to\u000athe baron, the gravin and her aunt - the Elector Countess,\u000aEmmanuelle von Liebwitz - caused his father''s death by\u000apoisoning or witchcraft, and one or both are certainly in league\u000awith the Ruinous Powers. Rumours of the Countess''s excesses\u000ahave long concerned Hubkind, so he has decided to observe the\u000atrial and make up his own mind on the matter - if he finds\u000aeither her or the gravin suspect, he will investigate both and their\u000aservants closely.'));
INSERT INTO module_plots VALUES(133,2,'Plot 5 – A Few Gold Crowns More',unistr('The last time Hubkind was in Kemperbad, he saw to the burning\u000aof an accused cultist, Samrich Weizen, in the very same square\u000awhere the trial by combat is to take place. The accusation was\u000afalse, and the tortured soul is bound to the place of its death -\u000auntil its accuser''s reappearance gives it an opportunity to find\u000ajustice...'));
INSERT INTO module_plots VALUES(134,2,'Plot 5 - A Few Gold Crowns More',unistr('Back at the Three Feathers, the bounty hunter Ursula Kopfgeld\u000atook the head of wanted agitator Josef Aufwiegler, killing\u000athe smugglers who had been hired to take him to safety. She\u000abrought the head to Kemperbad to claim her bounty, but was\u000acheated by a corrupt magistrate who claimed the reward for\u000ahimself. For the sake of her reputation, she cannot, and will not,\u000alet this stand.'));
INSERT INTO module_plots VALUES(135,2,'Plot 6 - Day of Blood',unistr('Like many town courthouses throughout the Empire,\u000aKemperbad''s has seen its share of witches and cultists burnt.\u000aUnlike Samrich Weizen in _Plot 4_, many of them were guilty -\u000aincluding the members of the Sanguine Brotherhood, followers\u000aof Khorne who had infiltrated the town Watch under the guise\u000aof an elite paramilitary society with a firm stance on punishment.\u000aJust a month ago, accusations of unlawful torture and mutilation\u000aled to a purge of the Watch, with several of the cult''s leaders\u000aburned in front of the courthouse. However, some members\u000amanaged to escape the net and now plan to use the distraction of\u000athe trial - and the blood shed by the two champions - to wreak\u000aa terrible revenge on Kemperad and its magistrates.'));
INSERT INTO module_plots VALUES(136,2,'Plot 7 - You''ve Got to Pick a Pocket, or Several',unistr('Ursula Kopfgeld is not the only Character the adventurers\u000amay recognise from the Three Feathers. Trials, fairs, and other\u000aspectacles attract crowds, and whenever a spectacle holds a\u000acrowd''s attention, it provides an opportunity for pickpockets.\u000aThe Gnome thief Glimbrin Oddsocks is working the crowd -\u000aand the stands, too, if he can get close enough - throughout\u000athe trial by combat, and he may turn up unexpectedly elsewhere,\u000aespecially if his presence complicates matters for the adventurers.\u000a**Events**\u000aThese events can be affected by what the Characters do and\u000awhere they are at any particular time. You should also feel free to\u000achange the events as desired.'));
INSERT INTO module_plots VALUES(137,3,'Plot 1 – Best Served Hot',unistr('**THE ADVENTURE**\u000aThe adventure starts in the early evening, when the Characters\u000aarrive at the opera house.\u000a**Players '' Introduction**\u000aOne way or another, Gravin Maria-Ulrike is free of all the charges\u000alaid at her feet. With a spring in her step, she leaves Kemperbad\u000afor Nuln, to give her aunt, the Elector Countess Emmanuelle\u000avon Liebwitz, the good news. The Countess was also named in\u000athe Dammenblatz indictment, and even though her rank made\u000aher immune from prosecution on the complaint of a lesser noble,\u000athe news is as welcome to her as to the gravin. To celebrate,\u000ashe decides to take her niece to the opera: a new production\u000aof the classic tragedy _Otenno_ is opening, with a revised libretto\u000aby renowned playwright Detlef Sierck, recently returned to his\u000ahome town of Nuln after many years in Altdorf.\u000a**Plot Summaries Plot 1 - Best Served Hot**\u000aAgents for Baron von Dammenblatz plan to blow up the Ducal\u000abox during the performance, killing Gravin Maria-Ulrike as\u000awell as Countess Emmanuelle, whom he blames equally for his\u000afather''s death. House Dammenblatz is also a close ally of House\u000aToppenheimer, and there are currently many tensions between\u000athe Toppemnheimers and the Liebwitzes (see _Plot 5_ ).'));
INSERT INTO module_plots VALUES(138,3,'Plot 2 - A Student Prank',unistr('Nuln is famous for its university''s engineers and for the Imperial\u000aGunnery School. A student prank involving a few firecrackers\u000amay turn deadly if not nipped in the bud. Meanwhile, Glimbrin\u000aOddsocks is following them closely - he has got it in his\u000ahead to burgle the Imperial Gunnery School - and will take\u000aany distractions he can use to steal the keys from one of the\u000auniversity''s professors in attendance.'));
INSERT INTO module_plots VALUES(139,3,'Plot 3 - Critics Rebutted',unistr('Detlef Sierck, the Empire''s foremost playwright and a son of Nuln,\u000ais among those attending the performance. His presence, after\u000amany years away, has drawn the attention of Edvard Lowenhertz,\u000aa vengeful lunatic who was once an aspiring actor himself -\u000auntil his debut performance was so savaged by the critics that\u000athe humiliation drove him into hiding. With the help of his\u000adaughter Edwina, Lowenhertz plots an appropriately theatrical\u000arevenge against Detlef Sierck, who, as a young student, penned a\u000aparticularly harsh review. Driven by revenge, Lowenhertz studied\u000adark magics in secret, and twisted his adoring young daughter\u000ainto a devoted accomplice.'));
INSERT INTO module_plots VALUES(140,3,'Plot 4 - College Ties',unistr('Assuming he is still alive, the gravin''s lawyer, Gustaf\u000aRechtshandler, returns to Nuln along with his mistress. The\u000aSlaanesh cultists of the _Ordo Ultima_ plan to punish him for\u000arefusing their orders in _A Rough Night at the Three Feathers_\u000aand for surviving their assassination attempts in _A Hard Day_\u000a_at the Trials_ .'));
INSERT INTO module_plots VALUES(141,3,'Plot 5 - Local Rivalries',unistr('Beneath the culture and glitter of Nuln lurk the same plots and\u000arivalries found in all the Empire''s cities. Recent months have\u000aseen rising tension between Countess Emmanuelle and the\u000aruling family of Wissenland, the Toppenheimers, who wish to\u000arule Nuln as they once did long ago. The Countess now openly\u000afavours the Pfiefrauchers - the Toppenheimers'' primary rivals\u000ain Wissenland. As members of both families are attending the\u000aperformance, their rivalry may spill over into pranks, brawls -\u000aand even murder.'));
INSERT INTO module_plots VALUES(142,3,'Plot 6 - Family Honour',unistr('Councillor Albrecht Oldenhaller, a senior merchant and\u000apolitician in Nuln, recently attempted to acquire a gem of dubious\u000aprovenance. This inserted his agents into an underworld war\u000awhere the Tilean Valentina family all but wiped out the Nulner\u000aSchatzenheimer gang, and nearly did the same to the Wastelander\u000aHuydermans gang. Like all of Nuln''s great and good, Oldenhaller\u000alikes to be seen at the opera - but the gangs haven''t forgotten\u000athe Councillor, nor about the gem. Each of the gangs has sent an\u000aassassin to kill Oldenhaller, but only the one who does the deed\u000awill receive the reward. The gem, which is unfortunately sacred to\u000athe Chaos God Nurgle, is also on the minds of a group of Nurgle\u000acultists, who want to take Oldenhaller alive and question him\u000aabout the gem''s current location. He was, after all, the last person\u000ato see it...'));
INSERT INTO module_plots VALUES(143,3,'Plot 7 - The Witch Hunter',unistr('Matthias Hubkind the witch hunter was prevented from\u000ainvestigating the gravin fully during the trial in Kemperbad\u000awhen the Ghost of one of his previous victims arose and\u000aattacked him. He has followed the gravin to Nuln and is\u000aobserving both her and her aunt very closely, to the extent\u000athat he will not hesitate to kidnap and question one of the\u000aservants of either lady, under torture if necessary, in order to'));
INSERT INTO module_plots VALUES(144,4,'Plot 1 – Old Scores',unistr('**Plot Summaries Plot 1 - Old Scores**\u000aAs far as the law is concerned, the von Dammenblatz case\u000aagainst Gravin Maria-Ulrike was settled in Kemperbad. Her\u000achampion prevailed, and under the laws of trial by combat she\u000aestablished her innocence. However, while Baron Eberhardt von\u000aDammenblatz is forced to accept the legal result, he is far from\u000atreating the matter as settled.\u000aWhile he was not invited to the wedding himself, his agents are\u000aat work to discredit the von Liebwitz family and sabotage the\u000awedding. If she still lives, it is Dominique Herveaux who is sent\u000ato deal with the situation.'));
INSERT INTO module_plots VALUES(145,4,'Plot 2 - Star-Crossed Lovers',unistr('Like many noble marriages, this match has more to do with\u000afamily position, land, and influence than with love. Nastassia\u000aand Karl-Heinz have met only a handful of times since they\u000awere betrothed as children. Unfortunately, Nastassia has met\u000asomeone else much more frequently. She is now madly in love\u000awith Joachim Bitterfeld, a jeweller''s apprentice from Altdorf. The\u000atwo have carried on an ardent, but unconsummated, affair for\u000asome time. Unable to persuade her father against the marriage,\u000aNastassia has decided to elope with her paramour on the night\u000abefore the wedding.'));
INSERT INTO module_plots VALUES(146,4,'Plot 3 - A Collector''s Item',unistr('Graf Wilhelm von Saponatheim is a veteran of several wars,\u000aand has become an avid collector of military curiosities.\u000aThrough a contact in the Border Princes, he recently acquired\u000aan ornate ancient sword from the desert Lands of the Dead,\u000awhich now sits in pride of place among his collection in the\u000amain hall. He intends to present the blade to his new son-inlaw as a wedding gift.\u000aWhat Graf Wilhelm does not know is that the weapon was\u000alooted from an ancient tomb. Its rightful owner wants it back,\u000aand will not let a trivial thing like death deter him from tracking\u000adown and recovering his prized possession. Furthermore, should\u000athe gift be delivered with the curse still intact, the Ambossteins\u000amay assume that Graf Wilhelm was attempting to assassinate\u000aKarl-Heinz, which isn''t the best way to start a marriage.'));
INSERT INTO module_plots VALUES(147,4,'Plot 4 - A Matter of Business',unistr('Graf Johann von Gient, a distant cousin of the von\u000aSaponatheims, has recently returned from Marienburg, where\u000ahe was conducting some family business. A compulsive gambler,\u000ahe lost heavily and ran out on gambling debts amounting to\u000aseveral thousand guilders - most of them to the dreaded crime\u000alord, Albrecht the Fish.\u000aFor the sake of his reputation, Albrecht cannot let this matter\u000arest. He has dispatched two of his most presentable-looking\u000athugs to have a quiet word with von Gient and offer him one last\u000achance to settle his debt.\u000aThe hedonism and degeneracy among some elements of the\u000aOld World''s nobility are legendary. Some - especially the\u000ayoung and foolish - seek to push their search for pleasure to\u000athe ultimate limits, and these are easy prey for the Chaos God\u000aSlaanesh and her followers.\u000aSome devoted followers of the Prince of Pleasure are among the\u000amany nobles at the wedding guests. The followers plan to break\u000aevery moral law and engage in an appalling act of worship. If\u000aeither Brecht Kavenner or the mutated Gustaf Rechtschandler\u000afrom _A Night at the Opera_ still live, they are drawn into whatever\u000ainfernal rites take place.'));
INSERT INTO module_plots VALUES(148,4,'Plot 6 - In the Best of Families',unistr('The von Saponatehims guard a terrible secret: unbeknownst to\u000aNastassia, she is not Graf Wilhelm''s only child. Her younger\u000abrother Manfred is feeble-minded, and despite his diminished\u000acondition is the sole legal heir to the Duchy of Saponatheim.\u000aPretending he died at birth, so far, the family has managed to\u000akeep him hidden in a filthy, basement cell. But if his existence\u000ashould become known, the wedding - and the alliance between\u000athe Ambossteins and the von Saponatheims - will be in serious\u000ajeopardy. If Nastassia is no longer Graf Wilhelm''s undisputed\u000aheir, she cannot bring the family''s lands to her marriage with\u000aKarl-Heinz: the Ambossteins will be outraged at the deception,\u000aand the von Saponatheims will be severely embarrassed.'));
INSERT INTO module_plots VALUES(149,4,'Plot 7 - The Rose Tiger',unistr('The Dowager-Duchess Clothilde of Telland has a fabulous ruby\u000a- slightly pink in color, with a flaw in the shape of a cat''s head -\u000awhich she wears to all-important occasions. An equally legendary\u000ajewel thief, known as the Wraith, has decided to steal the ruby\u000aand will make the attempt at the wedding celebrations.\u000aThe Wraith is not the only party interested in the ruby. The\u000aRose Tiger was stolen from Raja Shrimant Rao of Ind five years\u000aago, and a group of the _taggee_ agents has been sent to recover it.\u000aPosing as entertainers, they are waiting for the right moment to\u000astrike and reclaim the gem. And, of course, there is Glimbrin,\u000awho has never seen a gem he doesn''t like...'));
INSERT INTO module_plots VALUES(150,5,'Plot 2 - Vengeance Served Cold',unistr('Baron Eberhardt von Dammenblatz remains determined to\u000aavenge the death of his father. He has sent along an agent to\u000afinish Gravin Maria-Ulrike off. He has come to Ubersreik\u000aincognito to keep an eye on matters personally. If matters do not\u000aunfold as planned, he steps in to finish the job himself.'));
INSERT INTO module_plots VALUES(151,5,'Plot 3 - Repent or Die',unistr('A flagellant of Sigmar crashes the party intending to lecture\u000athe noble guests on their decadent ways, but his addled brain is\u000aconfused by the costumes and he becomes convinced that he has\u000astumbled upon a nest of Chaos worshippers and worse. Unless he\u000ais contained quickly, he can wreak untold havoc.'));
INSERT INTO module_plots VALUES(152,5,'Plot 4 - The Lady''s Test',unistr('Christoph Engel, a local Grey Wizard known for his secretive\u000aways, is also observing the party at the order of Lady Emmanuelle\u000aNacht ( _Plot 1_ ). Just as the masquerade hits a lull, he livens up the\u000aevening with a spell or two in order to see how the guests handle\u000adifficult circumstances...\u000aEngel attends the party with Lord Florian Pfeifraucher. Florian is\u000a''an affectionate drunk'' who seriously overestimates his appeal to the\u000aopposite sex. The more he drinks, and the more he is rebuffed, the\u000amore likely he is to forget that his uncle, Count Bruno Pfiefraucher\u000aof Grissenwald and Kreutzhofen, has sent him to support the\u000agravin and uphold the honour of his House, not to embarrass them.'));
INSERT INTO module_plots VALUES(153,5,'Plot 5 - Playing Doctor',unistr('Doktor Otto Krupp hopes to spend some time alone with his\u000amistress, Netta Volkmann, a barmaid from the town who has\u000abeen hired to help out at the ball. The couple doesn''t know that\u000aNetta''s husband, Volker, has recently learned of their affair, and\u000aintends to do something about it.'));
INSERT INTO module_plots VALUES(154,5,'Plot 6 - The Stars Are Right',unistr('A Skaven Grey Seer lurks beneath Ubersreik, spying out the\u000aman-things and their weaknesses. The concentration of so\u000amany nobles in a poorly guarded location, as well as the erratic\u000abehaviour of the Chaos moon Morrslieb, has convinced the\u000aold sorcerer that the time is right to attack. Using a handful of\u000astealthy Gutter Runners, he plans to poison the guests at the ball\u000awith Warpstone; the resulting death and mutation will cause\u000ahavoc and weaken the Empire''s nobility in one fell swoop.\u000aAt various points in the evening, the Skaven will try to dose\u000athe food and drink with powdered Warpstone. If any of their\u000aattempts is successful, guests will begin to exhibit mutations\u000aabout half an hour later. Treat each exposure by a Character to\u000aany tainted food or drink as Moderate ( **WFRP,** p. 182).'));
INSERT INTO module_plots VALUES(155,5,'Plot 7 - A Blot on the Escutcheon',unistr('House Aschaffenberg sees itself as the natural choice for the\u000anext lord of Ubersreik. However, it recently allied itself closely\u000ato House Bruner through a mixture of marriage and military\u000asupport.'));
INSERT INTO module_events VALUES(84,1,'9:00 p.m.',0,unistr('The Characters arrive at the inn. The Gravin Maria-Ulrike and\u000aher party are already in residence ( _Plot 1_ ).\u000aBruno Franke sits bare-chested at table _a_, arm-wrestling with one\u000aof the guards. Others are gathered round, drinking and shouting\u000aencouragement. Bruno wins easily, and will accept any challenge\u000afor stakes of 2/- or higher. Rules for arm-wrestling are given in\u000a**Appendix 2: Pub Games** on page 91.\u000aThe guards and servants in the barroom may talk to the adventurers\u000aif offered a few drinks and/or on a successful **Average (+20) Charm**\u000aTest. If a Character is looking for information, an **Opposed Gossip/Cool** Test reveals the Gravin is going to Kemperbad to\u000adeal with some legal matter; on an Impressive Success (+4), the\u000aservant or guard also reveals that it has to do with the death of a\u000aguest at a party held by the Gravin''s aunt, Countess Emmanuelle\u000avon Liebwitz of Nuln.\u000aOn a successful **Average (+20) Lore (the Empire)** Test (Courtier\u000aCharacters can attempt this test without the Skill using their\u000aunmodified **Int** ) the Characters have heard of Countess\u000aEmmanuelle''s legendary parties, which are at their wildest during\u000aBlack Powder Week, a week-long winter festival held in Nuln.\u000aOn an Impressive Success (4+), they have already heard some\u000agossip about the incident: Baron Otto von Dammenblatz, a minor\u000anoble from Duchy of Dunkelberg, was found dead, face down\u000ain a punch bowl. His son, Baron Eberhardt von Dammenblatz,\u000ahas accused the Gravin of causing his father''s death through\u000apoisoning or witchcraft. Everyone in the Gravin''s party believes\u000athat the Baron drank himself unconscious, slumped comatose\u000ainto the punch bowl, and drowned.\u000aAlso in the barroom is a grinning Halfling, Mercinellin ''Seedling''\u000aThorncobble who sits at table _b_ talking to the gravin as she fingers\u000aa pack of cards. As the Characters enter the inn, the gravin shakes\u000athe Halfling''s hand, and heads up to her room along with her\u000aguards - she has just completed a deal to hire Seedling for an\u000aupcoming party in Ubersreik. Seedling is delighted, and will\u000ahappily tell anyone exactly why. She will play a game of\u000aScarlet Empress with anyone who offers, for stakes of 1/-\u000aa game. Rules for playing Scarlet Empress are given in\u000a**Appendix 2: Pub Games** on page 91.'),'[]');
INSERT INTO module_events VALUES(85,1,'9:10 p.m.',1,'','[]');
INSERT INTO module_events VALUES(86,1,'9:10 p.m.',2,unistr('Three travelling scholars come in out of the rain and hang their\u000aheavy cloaks and hats by the fire to dry. They book a double-room\u000a_c_\u000afor the three of them and order three hot meals. They sit at table\u000aand keep to themselves. These are the cultists of the _Ordo Ultima_\u000a(see **Plot 3** ).'),'[]');
INSERT INTO module_events VALUES(87,1,'9:15 p.m.',3,unistr('Glimbrin Oddsocks arrives, books a place in the dormitory, and\u000asits down to play cards with Seedling. ( _Plot 7_ ). Non-Halfling\u000aCharacters who have never seen a Gnome before will likely\u000amistake him for a Halfling. Halflings will never make that\u000amistake, and may find Glimbrin somewhat of a curiosity.'),'[]');
INSERT INTO module_events VALUES(88,1,'9:20 p.m.',4,unistr('A liveried servant comes downstairs and orders Bruno to stop\u000aarm-wrestling in case he injures himself. Anyone at the same table\u000aor an adjoining table can overhear this, as can Characters with\u000athe _Lip Reading_ Talent and a clear line of sight. Bruno stands up\u000aabruptly, towering over the servant, and tells him to mind his own\u000abusiness. The servant retreats upstairs.'),'[]');
INSERT INTO module_events VALUES(89,1,'9:25 p.m.',5,unistr('The gravin comes downstairs with three servants and orders\u000aBruno to his room (room 4). He obeys sulkily. A servant orders\u000asupper for the gravin''s party. The guards and some of the servants\u000aeat in the bar, while meals for the gravin, her champion, and half\u000aa dozen servants are sent upstairs.'),'[]');
INSERT INTO module_events VALUES(90,1,'9:30 p.m.',6,unistr('A small boat arrives, carrying a well-dressed man and woman\u000aand two boatmen ( _Plot 2_ ). Room 10 is booked in the name of\u000aJohann Schmidt, and the boatmen are put up in the dormitory.\u000aThe couple disappears upstairs without supper or even a drink.\u000aThe boatmen stay in the bar, sitting at table _a_, which was recently\u000avacated by Bruno. If asked, the boatmen will claim the Schmidts\u000aare newlyweds from Grissenwald. They know the couple''s true\u000aidentities, but have been well paid to keep quiet. It will take a\u000a**Hard (−20) Bribery** Test (the target is 2 GC 1/8!) to persuade\u000athem to tell the truth.'),'[]');
INSERT INTO module_events VALUES(91,1,'9:35 p.m.',7,unistr('Three travellers arrive by cart, dressed in embellished, black robes\u000aof Morr ( _Plot 5_ ). They ask for a double room for themselves and\u000atheir charge: they are conveying a body for burial, and ask to keep\u000ait in their room. The barman is uncertain and calls the landlord.\u000aCoins discreetly change hands and the Morrians are given room\u000a9 _,_\u000awell away from the gravin''s party. The ''initiates'' bring in a coffin\u000aand go straight to their room as the inn patrons look on in shock.\u000aThe ''priest'' tells the landlord not to worry about any noise in the\u000anight: they are required to pray over the body from midnight\u000auntil dawn.'),'[]');
INSERT INTO module_events VALUES(92,1,'9:50 p.m.',8,unistr('Ursula Kopfgeld arrives on horseback ( _Plot 6_ ). After seeing her\u000ahorse stabled, she enters the inn and books a single room (18).\u000aDespite her intimidating appearance, she seems friendly enough\u000aand will talk with anyone. If asked about her business, she\u000aclaims to be working for the Kemperbad town council, taking a\u000aconfidential message to Nuln. She will not say any more.\u000aAt some point early in the evening, one of the minor male\u000aNPCs - a servant or guard - makes an improper suggestion\u000ato her. She flattens him quickly and efficiently, and the landlord\u000asteps in to prevent a brawl. If one of the Characters insults her\u000afirst, she will react in the same way, without drawing a weapon.'),'[]');
INSERT INTO module_events VALUES(93,1,'10:00 p.m.',9,unistr('If weapons are drawn, or a fight lasts for more than 2 Rounds,\u000athe landlord and staff step in, aided by as many of the inn''s other\u000apatrons as necessary.'),'[]');
INSERT INTO module_events VALUES(94,1,'10:00 p.m.',10,unistr('A servant comes down from the gravin''s rooms and orders all\u000aher party to bed: they will be starting at first light tomorrow.\u000aReluctantly, various servants and guards finish their drinks and\u000adrift off to the dormitory.\u000aAt about the same time, ''Herr Schmidt'' comes down for a bottle\u000aof wine. On his way back to his room, he is approached by one\u000aof the gravin''s servants. An inaudible but clearly heated exchange\u000atakes place, and ''Schmidt'' hurries back upstairs looking angry.\u000aThe servant heads off to the dormitory. Characters with the _Lip_\u000a_Reading_ Talent may learn that the servant is threatening to tell\u000asomeone something, but that is all.'),'[]');
INSERT INTO module_events VALUES(95,1,'10:10 p.m.',11,unistr('Bruno Franke returns to the bar, grinning broadly and looking\u000aaround with theatrically exaggerated caution to make sure that\u000anone of the gravin''s party is still there. He orders a mug of ale,\u000atelling the barman to ''keep ''em coming,'' and sits down at table\u000a_a_ with the two boatmen. After a few minutes, an arm-wrestling\u000acontest starts again. Ursula watches for a while and then\u000achallenges Bruno, putting ten silver shillings on the table.\u000aBruno demurs for a moment, but accepts the challenge: a small\u000acrowd gathers. Bruno''s arm begins to go down - he was being\u000agentle with the lady - but he quickly applies his full strength\u000aand the contest begins in earnest. Neither contestant moves - a\u000asheen of sweat breaks out on Bruno''s forehead, but it is an even\u000amatch. Then Ursula''s arm wavers, and Bruno - no longer the\u000agentleman - forces the Bounty Hunter''s arm slowly but surely\u000adown to the table.\u000aBruno looks at Ursula with a new respect, and the two of them\u000aspend some time talking and drinking together. Bruno will not\u000aaccept any more arm-wrestling challenges tonight.\u000aA few minutes later, another tray of fresh drinks is taken to\u000aBruno''s table. One mug of ale is drugged: it is intended for\u000aBruno, but the GM should take care that someone else drinks\u000ait - a minor NPC or one of the adventurers. The ale is laced with\u000aHeartkill ( **WFRP,** page 306).\u000aIf and when the victim of the drugged ale passes out, a successful\u000a**Average (+20) Perception** Test reveals that one of the staff\u000asuddenly looks worried and leaves. If the Characters pursue this\u000aindividual, he escapes through the darkness of the courtyard.'),'[]');
INSERT INTO module_events VALUES(96,1,'10:15 p.m.',12,unistr('One of the ''initiates'' comes down and speaks to the landlord.\u000aSuccessful _Lip Reading_ reveals that the ''initiates'' are expecting\u000aa boat during the night, and want the landlord to tell them the\u000amoment it arrives. The ''initiate'' then returns to their room.\u000aAs soon as the ''initiate'' has left, Ursula goes to speak to the\u000alandlord. Successful _Lip Reading_ reveals that she is asking the\u000alandlord about them, and he is telling her what they told him. A\u000afew coins change hands, and Ursula goes back to Bruno''s table.'),'[]');
INSERT INTO module_events VALUES(97,1,'10:25 p.m.',13,unistr('One of the gravin''s servants comes down and orders Bruno to\u000abed, explaining that the gravin checked his room and found him\u000amissing. He returns sheepishly upstairs.'),'[]');
INSERT INTO module_events VALUES(98,1,'10:40 p.m.',14,unistr('Gustaf Rechtshandler comes downstairs, dressed in a nightshirt\u000aand a silk dressing-gown. As he enters the barroom, one of the\u000athree _Ordo Ultima_ cultists leaves their table and heads upstairs.\u000aRechtshandler orders a brandy and takes it back to his room\u000a(room 3). A few minutes later, the other two cultists go upstairs\u000ato their room (room 8).'),'[]');
INSERT INTO module_events VALUES(99,1,'10:45 p.m.',15,unistr('One of the _Ordo Ultima_ cultists knocks on the door of\u000aRechtshandler''s room. The lawyer answers it after a moment and\u000athere is a brief exchange of words - too low to hear - before\u000athe cultist is admitted. A minute or so later, raised voices can\u000abe heard on a successful **Challenging (+0) Perception** Test (the\u000aTest is **Average (+20)** if a Characters is listening by the door):\u000aRechtshandler says he will not submit to blackmail, and the other\u000asays that he has no choice. Abruptly, everything goes quiet.'),'[]');
INSERT INTO module_events VALUES(100,1,'10:50 p.m.',16,unistr('Rechtshandler quietly opens the door of his room and looks\u000aoutside. If there is anyone in the passage, he says that he thought\u000ahe heard something outside: he closes the door, checking the\u000apassage again five minutes later. When the coast is clear he drags\u000athe cultist''s body out. If the PCs'' room is empty, he will leave the\u000abody there, completely by chance: if not, he will leave it in the\u000alinen cupboard.'),'[]');
INSERT INTO module_events VALUES(101,1,'11:00 p.m.',17,unistr('''Schmidt'' comes downstairs looking worried. If the PCs are still\u000ain the barroom, he asks one of them to take a message to the\u000adormitory for him, offering 5 silver shillings for the Character''s\u000atrouble. The job is to tell one of the gravin''s servants - a Hans\u000aErpresser - that ''Schmidt'' wants to see him. If the PCs are\u000anot in the barroom, ''Schmidt'' hires one of the boatmen to carry\u000athe message. Having paid the messenger, ''Schmidt'' returns to\u000ahis room.'),'[]');
INSERT INTO module_events VALUES(102,1,'11:05 p.m.',18,unistr('Erpresser goes to see ''Schmidt'' in his room. He knocks on the\u000adoor and is admitted straight away. There is a single thump (heard\u000awith a successful **Challenging (+0) Perception** Test; the Test is\u000a**Average (+20)** if a Characters is listening by the door or in an\u000aadjoining room) as ''Schmidt'' kills the servant. A few moments\u000alater, ''Schmidt'' cautiously opens his door to see if the passage is\u000aclear, and will attempt to dispose of the body in the same way as\u000aRechtshandler (see _10:50 p.m._ above).'),'[]');
INSERT INTO module_events VALUES(103,1,'11:15 p.m.',19,'','[]');
INSERT INTO module_events VALUES(104,1,'11:15 p.m.',20,unistr('One of the gravin''s servants asks the Characters to visit the\u000alawyer''s room. Rechtshandler explains that the travellers in room\u000a8 are blackmailing him, and offers 20 GCs to dispose of them.\u000aIf the Characters accept Rechtshandler''s offer, they will find the\u000a_Ordo Ultima_ cultists'' room is not locked as the two remaining\u000acultists are waiting for their companion to return - they have\u000anot yet become concerned about his long absence. Assuming the\u000aCharacters take advantage of this and initiate combat, the cultists\u000areceive a _Surprised_ Condition. After 3 Rounds of fighting, guests\u000afrom adjoining rooms will come to investigate the noise.\u000aMeanwhile, Ursula Kopfgeld leaves the barroom ''to check on her\u000ahorse'' - actually, she is spying out the room used by the smugglers.'),'[]');
INSERT INTO module_events VALUES(105,1,'11:30 p.m.',21,unistr('There is a great hammering on the inn''s main door. The landlord\u000arefuses to open it at first, but it seems that someone is prepared\u000ato break the door down if necessary. When the door is opened,\u000aa well-dressed - but fairly drunk - mustachioed man comes\u000ain, accompanied by three aggressive-looking men (this is Thomas\u000aPrahmhandler and his hired thugs, see _Plot 3_ ). The newcomer\u000ademands to know which room belongs to a Friedrich von\u000aPfeifraucher. When he is told that there is no one staying in the\u000ainn under that name, he pauses.\u000a_''Well, his boat''s moored outside,''_ he slurs, _''so we''ll just have to look_\u000a_for him ourselves. Gentlemen?''_ He waves his three thugs upstairs.\u000aA brawl breaks out as the staff try to stop them, aided by several\u000apatrons. Whether or not the PCs are in the barroom at this time,\u000athe brawl should reach them, and one of the PCs should lose a\u000adagger in the confusion: this will be important later on.\u000aIf Thomas Prahmhandler makes it upstairs, he breaks down\u000aevery door until he is stopped or until he finds von Pfeifraucher.\u000aTwo of the thugs will hold the noble down, and Prahmhandler\u000ahorsewhips him while the third thug forces the weeping young\u000awoman to watch.\u000aIf the brawl reaches the upper floor and lasts for more than 3\u000aRounds up there, three of the gravin''s guards (unarmed and\u000aunarmoured, of course) will come to investigate, and will join the\u000astaff and other patrons in trying to put down the disturbance.\u000aAt some time during this event, Ursula returns to the barroom.\u000aShe will automatically investigate any disturbance.'),'[]');
INSERT INTO module_events VALUES(106,1,'11:50 p.m.',22,unistr('If the two remaining cultists are still alive, they visit the lawyer''s\u000aroom, where a violent argument takes place. By the time anyone\u000acomes to see what is going on, Rechtshandler is dead. There is no\u000aone else in the room, which is bolted from the inside. The cultists\u000aleft via the window, and spend about five minutes on the roof\u000amaking their way back to their own room.\u000aMeanwhile, Ursula Kopfgeld goes to her room, locking the door.'),'[]');
INSERT INTO module_events VALUES(107,1,'Midnight',23,unistr('There is a tremendous shouting and scuffling from the smugglers''\u000aroom. The landlord tries to prevent anyone going in, explaining\u000awhat the ''initiates'' told him about praying over the body through\u000athe night. However, after a few minutes he decides he must\u000aspeak to them, and he will be glad of anyone''s company. As he\u000aapproaches the door of the room, though, everything suddenly\u000agoes quiet. The ''priest'' opens the door and apologises for the\u000anoise. In the room, his two ''initiates'' can be seen sitting firmly on\u000aa third. The one at the door explains that their brother sometimes\u000ahas these spasms, being particularly sensitive to vibrations from\u000abeyond the Portal. It makes him a first-class priest of Morr, but\u000acan be inconvenient. The landlord goes away, puzzled.\u000aThe smugglers'' charge woke up as the effects of the drug wore off,\u000aand their efforts to keep him quiet were not entirely successful.\u000aIf the Characters accompany the landlord to the room, they may\u000anotice that there are now four ''Morrians'' rather than three. If\u000athey mention this, the landlord will tell them that they must\u000abe mistaken, and will be very unwilling to go back to the room,\u000aor to allow anyone else to do so, unless a **Hard (−20) Charm**\u000aTest is passed. If any do go back to the room, they will find only\u000athree ''Morrians'' there: the smugglers have knocked their charge\u000aunconscious and hidden him under a bed.'),'[]');
INSERT INTO module_events VALUES(108,1,'12:10am',24,unistr('Glimbrin heads for the dormitory. Seedling then asks if anyone\u000aelse wants to play cards with her. If not, she shrugs and also heads\u000afor the dormitory. The boatmen and coachmen retire as well.'),'[]');
INSERT INTO module_events VALUES(109,1,'12:20am',25,unistr('A woman screams from the gravin''s wing. If the Characters arrive\u000aon the scene, they find a small crowd around the door to Bruno''s\u000aroom (room 4). He is dead, with a dagger embedded between his\u000ashoulders. Everybody is roused from their beds and summoned\u000ato the barroom. It will soon become obvious that several other\u000apeople are dead or missing.\u000aThe innkeeper announces that there is a murderer on the loose\u000aand advises everyone to lock themselves in their rooms until\u000adaylight, when he can send for the road wardens or river patrol.\u000aOr both. However, before everyone goes back to bed, the Gravin\u000adisplays the dagger with which Bruno was killed.\u000aIt will look familiar to the Characters, since it was stolen from one of\u000athem about 20 minutes earlier. If its owner does not come forward\u000astraight away, one of the inn''s staff (the one who stole it, naturally)\u000aremembers seeing an identical dagger in the Character''s possession.\u000aThe PC is challenged to produce the weapon, but will, of course, be\u000aunable to do so. It will take a successful **Hard (−20) Charm** Test to\u000aconvince anyone that the dagger went missing during the brawl at\u000amidnight. The penalty reflects the fact that people prefer the simple\u000aexplanation: that the Character murdered Bruno.\u000aAfter all the accusations and protestations of innocence have died\u000adown, the gravin rises.'),'[]');
INSERT INTO module_events VALUES(110,1,'1:20am',26,unistr('_''I am authorised by my aunt to exercise her Imperial right of dispensing_\u000a_common justice, and it seems right I should do so here given I am the_\u000a_most prominent wronged party. Therefore, I rule that this group shall_\u000a_be locked in their room until the morning, when I shall decide further._\u000a_All their weapons and equipment will be confiscated, and guards will_\u000a_be posted at their door and beneath their window. You, however,''_ -\u000ashe points at the strongest-looking Warrior Class Character, or\u000athe closest to that - _''I sentence to replace my murdered champion_\u000a_until it pleases me to decide otherwise.''_ A murmur runs around the\u000abar, but no one questions her ruling.\u000aBruno''s body is handed over to the ''Morrians'' with a request that\u000athey look after it until dawn. It is taken to their room wrapped in\u000aa blanket, as are any other bodies that have been discovered so far.\u000aEscape is effectively impossible: there are too many people in\u000athe bar. The Characters are locked in their room with two of the\u000aGravin''s guards outside the door and another two beneath their\u000awindow, if they have one. All their weapons and equipment are\u000ataken. The Character whom the Gravin has chosen as her new\u000achampion is taken to Bruno''s room (room 4) and locked in. After\u000aabout half an hour, everyone goes back to bed.'),'[]');
INSERT INTO module_events VALUES(111,1,'1:20am',27,unistr('A servant comes to the PCs'' room: the Gravin wants to talk\u000ato them. They are taken to her room (room 1) by four guards,\u000astopping along the way to collect the new champion. The Gravin\u000ais waiting for them, still fully dressed. After ordering the guards\u000ato wait outside, she speaks to the PCs.\u000a_''I''m sorry it was necessary to have you locked up, but it seemed to be_\u000a_the only way to calm everyone down. I believe you are innocent - no_\u000a_one would be so stupid as to leave his own dagger behind as a clue._\u000a_Anyway, we have until dawn to discover who actually killed Bruno._\u000a_I''m sure Dammenblatz is behind it all - I''m going to Kemperbad to_\u000a_fight a lawsuit against him. If I''m right, then his agents will try to kill_\u000a_my new champion''_ - she favours this Character with a sardonic\u000asmile - _''but this time you will all be waiting for them. The guard_\u000a_will be left on your room for the sake of appearances, but you will all_\u000a_spend the rest of the night in Bruno''s room. One weapon of your choice_\u000a_will be returned to each of you... no, no more than one - I don''t want_\u000a_you trying to make a break for it. Well, then, let''s get moving - there_\u000a_isn''t much of the night left.''_\u000aEach Character is given one item from their weapons and\u000aequipment, and the party is locked in Bruno''s room. The guards\u000areturn to their posts. There is to be no light in the room, so the\u000aCharacters must wait in darkness. Each Character must pass\u000aan **Average (+20) Endurance** Test or fall asleep before the next\u000aevent happens.'),'[]');
INSERT INTO module_events VALUES(112,1,'2:00am',28,unistr('All awake Characters should attempt a **Hard (−20) Perception**\u000aTest. If passed, a soft scraping noise is heard coming from the\u000achimney of Bruno''s room. Sleeping characters can attempt a\u000a**Very Hard (−30) Perception** Test to wake up with a start and\u000aa _Fatigued_ Condition. They are also given the _Unconscious_ and\u000a_Prone_ Conditions for Round 1, and a _Surprised_ Condition on the\u000aRound they awaken.\u000aIf the PCs rush to investigate or give any other indication that they\u000aare awake, the noise stops. If they keep quiet, someone comes down\u000athe chimney and into the room. Characters with the _Night Vision_\u000aTalent recognise one of the inn''s serving staff. The servant, actually\u000aan agent in the employ of Baron von Dammenblatz, can barely see\u000ain the darkness, so creeps towards the bed, relying on memory and\u000acare to avoid falling over anything. If attacked, she tries to escape\u000athrough the window or up the chimney; the two guards posted\u000aoutside will come in at the first sound of any disturbance.\u000aIf the agent is captured, the guards bind and gag her to await the\u000agravin''s pleasure in the morning.'),'[]');
INSERT INTO module_events VALUES(113,1,'4:30am',29,'','[]');
INSERT INTO module_events VALUES(114,1,'4:30am',30,unistr('Dawn breaks. The gravin calls everyone to the barroom, but there\u000ais no answer from the smugglers'' room. The door is forced open to\u000areveal a scene of carnage. All three ''Morrians'' are dead, and their\u000acoffin has been broken open and contains a freshly-dead, headless\u000abody. It has no distinguishing characteristics, making identifying\u000athe mysterious corpse almost impossible, but it does have printed\u000aleaflets stuffed in an inside pocket denouncing the Countess of\u000aNuln as a ''LUSTY DEGENERATE who must be REMOVED\u000afor the benefit of ALL the EMPIRE!''. Ursula Kopfgeld and her\u000ahorse are also missing.\u000aOnce everyone has assembled, the gravin brings out the captured\u000a(or dead) servant. The gravin then explains that the woman was in\u000athe pay of Baron von Dammenblatz, and is responsible for Bruno''s\u000amurder as well as the attempted murder of her newly-appointed\u000achampion. The gravin rules the Dammenblatz agent is to be\u000alocked up and handed over to the road wardens or river patrol\u000aat the first opportunity, and then everyone goes on their way. It''s\u000abeen a busy night, and one that no one will forget in a hurry.\u000a**RESOLUTION Rewards**\u000aAs well as the usual awards for good roleplaying and bright ideas,\u000aexperience points should be awarded for the following:\u000a30 points for actively participating in capturing Bruno''s murderer\u000a10 points for participating directly in disposing of the cultists\u000a5 points for winning an arm-wrestling match with Bruno\u000a5 points for coming out ahead when playing cards with Seedling\u000a10 points for catching anyone who is trying to hide a body\u000a10 points for taking direct action to stop Prahmhandler before\u000ahe reaches Pfeifraucher.\u000aThere are many other Character actions that will contribute to\u000abringing the adventure to a satisfactory conclusion; you should\u000afeel free to award XP for anything else you judge deserving, using\u000athe general level of the awards given above as a guideline.\u000a**Aftermath Following the Campaign**\u000aIf you are planning to follow the **Rough Nights & Hard Days**\u000acampaign, have one of the Characters take over the job of the\u000agravin''s champion from the unfortunate Bruno Franke. That\u000aCharacter can then enter the Judicial Champion (Duelist level\u000a4) Career for 0 XP; this is a one-off offer that must be taken\u000aimmediately, or the Character stays in their current Career. The\u000agravin will find jobs in her retinue for the other members of\u000athe party, according to their particular abilities. If there are no\u000aobvious uses for the other Characters, they will be employed as\u000aguards, and can enter the Guard Career (Guard level 2) for 0 XP;\u000aagain, the Players must immediately choose to either enter this\u000aCareer for free, or stay in their current Careers. The Characters''\u000abarge, if they have one, will be added to the gravin''s party. The\u000anew champion is promised a bonus of 40 GCs if the Gravin wins\u000athe case in Kemperbad. They can travel in their barge, if they\u000ahave one, while the Gravin''s party takes their own. Otherwise,\u000athey are given space in the hold of the Gravin''s vessel alongside\u000athe other guards.\u000aThe journey to Kemperbad will be uneventful unless you decide\u000ato have another of Dammenblatz'' agents make an attempt on\u000athe new champion''s life at another inn. The gravin''s presence will\u000aensure the Characters are not troubled by the river patrol or other\u000aofficials. A few days later, the party arrives in Kemperbad and the\u000anext chapter begins.\u000a**A Stand-Alone Adventure**\u000aIf _A Rough Night at the Three Feathers_ was played as a stand\u000aspent in Nuln.\u000a# The Gravin’s party\u000a|M|WS|BS|S|T|I|Ag|Dex|Int|WP|Fel|W|\u000a|---|---|---|---|---|---|---|---|---|---|---|---|\u000a|4|43|31|28|28|47|34|47|54|50|66|11|\u000a**Bruno Franke**\u000aBruno, the gravin''s judicial champion, is a tower of muscle\u000atopped with a smiling face that hints at mischief. His Altdorf\u000aaccent is deep - he was born in the imperial capital to parents\u000aof Southlander extraction almost forty years ago. He has a\u000adistinctive, infectious laugh, and he loves a good challenge.\u000a**Gustaf Rechtshandler**\u000aA droning self-important man with a polished accent, Gustaf\u000ais in his late 50s. He adores attention, so takes any opportunity\u000ato interrupt conversations to show off his knowledge. Knowing\u000anothing about the topic at hand is no impediment - he simply\u000aparaphrases what others say around him as if they were his ideas.\u000aWhen panicked, his well-trained accent evaporates to the vulgar\u000a|M|WS|BS|S|T|I|Ag|Dex|Int|WP|Fel|W|\u000a|---|---|---|---|---|---|---|---|---|---|---|---|\u000a|4|26|26|28|29|64|31|48|62|51|42|11|\u000a|M|WS|BS|S|T|I|Ag|Dex|Int|WP|Fel|W|\u000a|---|---|---|---|---|---|---|---|---|---|---|---|\u000a|4|68|47|69|42|53|63|31|25|50|29|17|\u000a# The Gravin’s Staff\u000a**The Gravin''s Staff**\u000aThe gravin has as many servants, handmaids, men-at-arms,\u000abodyguards, and associated other staff, all dressed in her magenta\u000aand yellow livery. Amongst her staff is Hans Erpresser, a servant\u000awith a penchant for blackmail (use the Handmaids and Servants\u000astats for him), and Eliza, a new hire who isn''t everything she\u000aappears to be.'),'[]');
INSERT INTO module_events VALUES(115,2,'9:00 a.m.',31,unistr('The gravin sends the party to observe the preparations for the trial.\u000a_''We''ve seen how low von Dammenblatz will stoop. He may try to_\u000a_bribe or threaten one of the magistrates, or tamper with the arena_\u000a_somehow, or - well, you would know better than I do. Just keep_\u000a_your eyes open and trust no one. And, above all -''_ she points to her\u000achampion _''- look after this one. I''ve lost one champion already, and_\u000a_I can''t afford to lose another on the day of the trial.''_'),'[]');
INSERT INTO module_events VALUES(116,2,'9:15 a.m.',32,unistr('The adventurers arrive at the court to find an oval ring marked\u000aout with rope. A few workers are inside the rope, sprinkling\u000asawdust on the cobbles to provide better footing and soak up\u000aany spilled blood. A wooden stand is being erected in front of\u000athe courthouse. Three ornate chairs in the middle are reserved for\u000athe town magistrates, and seating at either end of the stands is\u000amarked with the arms of Ambosstein and von Dammenblatz. At\u000aeither end of the arena, servants are erecting small pavilions for\u000ause by the two champions.'),'[]');
INSERT INTO module_events VALUES(117,2,'9:30 a.m.',33,unistr('The champions'' pavilions are raised, and servants carry in\u000afurnishings and equipment: armour stands, weapon racks, and\u000asome light furniture. Gustaf Rechtshandler, the gravin''s lawyer, is\u000atalking with a group of people in front of the stands: two men and\u000aa woman wear magistrate''s robes emblazoned with Kemperbad''s\u000atown crest, the fourth is dressed in a lawyer''s court garb like\u000aRechtshandler himself. Clerks stand to either side of the small\u000agroup, making notes as the others talk.\u000aIf the Characters overhear the conversation, they find that it\u000aconcerns the procedural details of the trial: the bout will begin\u000aat noon, and will last until one champion is unable to continue.'),'[]');
INSERT INTO module_events VALUES(118,2,'9:45 a.m.',34,unistr('Rechtshandler comes over to the adventurers to check that\u000aeverything is in order with the preparations for the trial. Any\u000aCharacter scanning the scene can make a **Perception** Test to\u000anotice that two people - a man and a woman, both in their\u000atwenties - seem to be watching the lawyer. If the adventurers try\u000ato question them, they melt into the crowd, using their Stealth\u000aSkill to evade pursuit.\u000aThese are _Ordo Ultima_ cultists (see _Plot 3_ above) who have been\u000asent to murder the lawyer in revenge for the deaths of their\u000acomrades in the Three Feathers. If the Characters capture the\u000acultists, they find the telltale letter O enclosed within a letter U\u000atattooed on their chests.\u000aWhile this is happening, another successful **Perception** Test will\u000aallow one or more Characters to recognise a familiar face from\u000athe Three Feathers. Ursula Kopfgeld approaches the magistrates\u000aafter their conversation with the lawyers. She speaks to one of\u000athe male magistrates, and the conversation grows heated. He\u000asignals two guards who approach with their halberds at the\u000aready, and Ursula strides off fuming. If anyone tries to stop or\u000aquestion her, she tells them in no uncertain terms to mind their\u000aown business.'),'[]');
INSERT INTO module_events VALUES(119,2,'10:00 a.m.',35,unistr('As work continues on the stands, part of one railing collapses.\u000aThere are some minor injuries, but nothing serious; however, the\u000aaccident makes a lot of noise and every head turns to see. Every\u000ahead, that is, except one: a Dammenblatz agent arranged for the\u000aaccident to happen.'),'[]');
INSERT INTO module_events VALUES(120,2,'10:15 a.m.',36,unistr('While the adventurers are looking at the source of the\u000acommotion, he slips a blowgun and a small wallet of poisoned\u000adarts into the clothing of the Character who looks least likely\u000ato notice the attempt. This is treated identically to pocketpicking - it just works in the opposite direction - so requires\u000aan **Opposed Sleight of Hand/Perception** Test to succeed, with\u000athe Difficulty modified according to the circumstances as you\u000asee fit. The wallet has spaces for four darts, but it contains only\u000athree: the significance of this is revealed later (see _10:45 a.m._ ).\u000aThe three darts are coated with Black Lotus ( **WFRP,** p. 306).'),'[]');
INSERT INTO module_events VALUES(121,2,'10:15 a.m.',37,unistr('Work on the stands is completed. Servants hang curtains while\u000aothers position chairs and bring cushions. A successful **Perception**\u000aTest allows the adventurers to notice the two _Ordo Ultima_ cultists\u000a(see _9:45 a.m._ above) among those bringing cushions. They speak\u000abriefly to a liveried official who points them to a space on the\u000aright of the gravin''s chair, and they leave a cushion there.\u000aThe cushion has a concealed needle coated in Black Lotus\u000a( **WFRP**,\u000ap. 306). Unless the adventurers investigate and find the\u000aneedle, Rechtshandler will sit on it when the gravin''s party takes\u000atheir seats at 11:00 a.m.'),'[]');
INSERT INTO module_events VALUES(122,2,'10:30 a.m.',38,unistr('A mob of street urchins, tired of waiting for the trial to begin,\u000astarts to scuffle among themselves. Two of them begin fighting\u000ain earnest, and one breaks away with several of his fellows in hot\u000apursuit. Apparently by chance, he runs right into one or more\u000aof the adventurers. Seconds later, the whole mob of pursuing\u000aurchins does the same thing.\u000aIf the gravin''s champion is with the Characters, the urchins target\u000ahim or her; if not, they pick the toughest-looking PC in the\u000ahonest but mistaken belief that this is the Ambosstein champion.\u000aAs they bump and buffet their way past their target, three attacks\u000awill be made on that Character''s legs. Knees and hamstrings are\u000athe main targets, with the aim of rendering the gravin''s champion\u000aincapable of fighting. The urchins attack with a modest **WS** of 20.\u000aUse the normal combat rules, with all three attacks taking place\u000ain the same Round and benefitting from the Outnumbering\u000arules. Unless the target Character has an appropriate Talent to\u000aavoid Surprise, it requires a **Very Hard (−30) Perception** Test to\u000aspot the makeshift knives being drawn. If this Test is failed, the\u000atarget receives a _Surprised_ Condition.\u000aThe urchins are small, quick, and streetwise. They know every\u000aalley, every gap between two buildings, and every hole in every\u000awall and fence in the whole town of Kemperbad. Catching them\u000awill be a challenge - if you wish to use the Pursuit rules, the\u000aurchins have an Athletics of 40 and start at a Distance of 4 - but\u000aif even one is detained, it won''t take much to force a confession.\u000aA stranger gave the urchins a small bag of coins containing 80d,\u000aa small fortune in their eyes, to disable the gravin''s champion. The\u000aurchins can give a description of this stranger, which matches the\u000aDammenblatz agent (see page 18).'),'[]');
INSERT INTO module_events VALUES(123,2,'10:45 a.m.',39,unistr('The von Dammenblatz party arrives. Led by a drummer-boy\u000aand a servant carrying the family''s banner, it consists of Baron\u000aEberhardt, on horseback; his widowed mother the dowager\u000aBaroness Violetta, riding in a sedan chair; his champion, Heinrich\u000aBöttcher; and a dozen or so footmen and other servants. They\u000atake their places to the left of the magistrates.\u000aBöttcher takes a moment to acknowledge the crowd''s cheers\u000abefore heading to his pavilion. However, as he does so, he flinches\u000afor a moment before pulling a small, feathered dart from the\u000aleather of his breeches. Baron von Dammenblatz hurries to his\u000achampion''s side, followed by a liveried junior official; it appears\u000athat an attempt has been made to injure or even kill the Baron''s\u000achampion. Von Dammenblatz claims, very loudly, that someone\u000ain the Ambosstein party is behind the attempt, probably acting\u000aon the orders of their unscrupulous mistress. He points to the\u000aadventurers, Gustaf Rechtshandler the lawyer, and anyone else\u000ain Ambosstein livery, and insists that they be searched forthwith.\u000aIf the blowgun and darts are found on one of the adventurers (see\u000a_10:00 a.m._\u000aabove), it is clear that the dart fired at Böttcher is an\u000aexact match for those in the wallet. The Character in question is\u000aimmediately marched off to the cells, stripped of all equipment, and\u000alocked up. The gravin will face some questions after the trial is over.'),'[]');
INSERT INTO module_events VALUES(124,2,'11:00 a.m.',40,unistr('Gravin Maria-Ulrike arrives with her own retinue of servants\u000aand hired guards. Anyone watching the witch hunter, Matthias\u000aHubkind, will see him studying the gravin intently, as if searching\u000afor something.\u000aIf the cushion with the hidden needle has not been found (see\u000a_10:15 a.m._ above) Gustaf Rechtshandler stands up with a yelp\u000aas the gravin''s party seats itself. He picks up the cushion from\u000a**WFRP**,\u000ahis seat and finds the hidden needle: the Black Lotus (\u000ap. 306) is already in his system and he''s beginning to choke. If\u000aRechshandler falls to 0 Wounds, he dies, face swollen and black,\u000abloody froth spilling from his nose and lips.\u000aUnless the cultists are captured and the truth comes out, the\u000agravin assumes that the attempt on her lawyer''s life comes from\u000aBaron von Dammenblatz. She complains to the magistrates, who\u000adeliberate for a few minutes before ruling that her complaint\u000aagainst von Dammenblatz is a separate case, which must be heard\u000aafter the trial by combat. Meanwhile, if required, a clerk stands in\u000afor Rechtshandler.'),'[]');
INSERT INTO module_events VALUES(125,2,'11:15 a.m.',41,unistr('Flanked by two watchmen, a herald in the town''s livery marches\u000ainto the ring and blows three flourishes on a trumpet.\u000a_''Hear ye, hear ye!''_ he cries. _''Order and silence for their worshipful_\u000a_eminences, Magistrate Hannes Richter, Magistrate Hanna Anwalt, and_\u000a_Assistant Magistrate Gerhard Urteil!''_ The hubbub around the ring\u000adies down a little as the town''s three magistrates take their seats.\u000a# Trial by Combat'),'[]');
INSERT INTO module_events VALUES(126,2,'11:30 a.m.',42,unistr('The crowd is starting to grow restless as the herald blows another\u000ablast on his trumpet.\u000a_''Hear ye, hear ye!''_ he cries. _''In the matter of the noble Baron Eberhardt_\u000a_von Dammenblatz of Wissenberg, against the noble Gravin Maria-_\u000a_Ulrike von Liebwitz of Ambosstein, concerning the death of the_\u000a_late noble Baron Otto von Dammenblatz, let the parties and their_\u000a_champions come forward and be duly sworn!''_\u000aThe two nobles and their champions enter the ring, where they\u000aare joined by the town''s high priest of Verena, Mother Petra\u000aSteinmetz. She administers the Oath of Verity, the first step in\u000athe preparations for the trial.\u000a_''I swear before all assembled here and in the sight of Verena that my_\u000a_cause is just and my case is truthful. I swear that I shall abide forever_\u000a_by the results of this trial, seeking no other remedies and pursuing no_\u000a_other means if my appeal to Verena''s judgement should be unsuccessful._\u000a_May all-knowing Verena strengthen the hand that is true, and see_\u000a_justice prevail. This I swear.''_\u000aWhile all eyes are upon the swearing-in, von Dammenblatz''s\u000aagent approaches the back of the Ambosstein pavilion, carrying a\u000awicker basket: the adventurers may notice this with an **Opposed Perception/Stealth** Test. Unless intercepted, the agent crouches\u000adown and slides the basket under the canvas wall of the pavilion,\u000areleasing a poisonous snake inside.\u000aOnce the oaths are sworn, the herald blows another flourish on\u000ahis trumpet and the nobles return to their seats in the stands.\u000aLiveried court officials inspect the two champions and their\u000aequipment, and after a few minutes they stand before the\u000amagistrates and declare that nothing untoward has been found.\u000aThe magistrates respond with a wave of their hands and the\u000atrumpet sounds again; the champions retire to their pavilions to\u000aprepare themselves. If the assassin was successful in releasing the\u000asnake, it attacks the Ambosstein champion.'),'[]');
INSERT INTO module_events VALUES(127,2,'11:45 a.m.',43,unistr('As the champions prepare, the high priestess of Verena\u000awalks around the perimeter of the ring, accompanied by two\u000aacolytes. She sprinkles the sawdust with blessed oil and chants\u000aa succession of prayers intended to prevent any attempts to'),'[]');
INSERT INTO module_events VALUES(128,2,'Two Rounds Later…',44,unistr('_''Hear ye, hear ye!''_ he cries. _''In the matter of the noble Baron_\u000a_Eberhardt von Dammenblatz, lord of Wissenberg, against the noble_\u000a_Gravin Maria-Ulrike von Liebwitz, Baroness of Ambosstein and_\u000a_Lady of Nuln, concerning the death of the late noble Baron Otto von_\u000a_Dammenblatz, lord of Wissenberg, let the champions come forth and_\u000a_let the trial begin!''_\u000aThe two champions come out of their pavilions and face off.\u000aMagistrate Richter raises a white handkerchief in the air. For a\u000along moment, all is hushed. Then he lets the handkerchief fall,\u000aand the fight is on! Or is it?'),'[]');
INSERT INTO module_events VALUES(129,2,'Two Rounds Later...',45,unistr('The racketeers ( _Plot 2_ ) have placed gunpowder charges against the\u000adoor of Kappan''s cell and the back wall of the courthouse yard.\u000aUnfortunately, they have seriously overestimated the amount\u000aof powder needed to achieve their goal. On Round 1, the fuse\u000ais lit. At the end of Round 2, there is an almighty explosion of\u000afairly epic proportions at the back of the courthouse. The ground\u000ais rocked, and several hundred yards away, some of the more\u000aprecarious buildings perched upon the cliffsides of Kemperbad\u000afall loose to the Reik below. There is a sharp intake of collective\u000abreath as the fiery plume rolls into the heavens. The magistrates,\u000aas they gather their wits, frantically signal for the bout to be\u000astopped. The herald intervenes, blowing his trumpet and yelling\u000afor the champions to return to their pavilions immediately.\u000aWatchmen from around the square run into the courthouse. The\u000aguards flanking the stands escort the three magistrates inside,\u000awhile everyone else either scrambles for a view of the damage or\u000asimply stands there, unsure what just happened.'),'[]');
INSERT INTO module_events VALUES(130,2,'12:15 a.m.',46,unistr('Details vary wildly: some say the escape was successful, others\u000athat everyone involved was killed. Some say the back wall of\u000athe courthouse was brought down, others that the explosion\u000acaused no damage. Some say the criminal was a murderer,\u000aothers a racketeer, and others still are certain he was actually a\u000awasherwoman accused of witchcraft, who escaped by means of\u000asome spell. It is up to you to know how successful the attempt to\u000afree Kappan is, but any Characters locked up in prison (see **10:45 a.m.** ) can easily make their escape in the confusion to rejoin\u000athe party. Meanwhile, the two champions come forth, and the\u000amagistrate drops his handkerchief again to restart the bout.'),'[]');
INSERT INTO module_events VALUES(131,2,'Two Rounds Later...',47,unistr('Matthias Hubkind the witch hunter ( _Plot 4_ ) edges around the\u000aoutside of the ring, trying to get closer to the spot where Gravin\u000aMaria-Ulrike sits in the stands. When he is more or less in front\u000aof the magistrates, something horrific happens.\u000aSawdust flies into the air as a greenish-white flame erupts from\u000athe ground between the two champions, at the very spot where\u000aHubkind''s innocent victim was burned years before. The crowd\u000adraws back: there are screams, and some are trampled. A shape\u000abegins to form within the flame. A distorted image of a man is\u000ain the centre of the flame, wavering as though seen through a\u000aheat haze, his eyes bulging and his mouth open in a perpetual\u000ascream. The figure flies at the witch hunter, trying to lock its\u000ainsubstantial fingers around his neck. As it does so, the herald\u000ablows his trumpet again, signalling that the bout should stop.\u000aThe figure is a Ghost. If the adventurers intervene, they can fight\u000ait normally; if not, the Ghost and the witch hunter struggle for\u000aa moment before Kemperbad''s high priest of Morr gains his\u000awits and begins to intone a prayer - _Vanquish the Unrighteous_ . If\u000ayou want to make it easier on the party, or if the party does not\u000ainvolve itself, count this as the _Destroy Undead_ Miracle, which\u000athe priest can invoke each Round with a **Challenging (+0) Pray**\u000aTest (count his _Pray_ Skill as 50). Otherwise, the priest''s words are\u000aineffective as he is not blessed by Morr.\u000aWhen the Ghost is dealt with (or Hubkind is dead, and the\u000aGhost vanishes), the magistrates officially call a break so that\u000aorder can be restored and those injured in the stampede can\u000areceive medical attention. Any help the Characters can offer\u000aOrder is finally restored, and the last of the injured are carried\u000aoff to the temple of Shallya. The magistrates give the signal\u000afor the bout to re-start. Just as they do so, the _Ordo Ultima_\u000acultists approach the stands and, half-hidden in the crowd,\u000aone of them fires a blowgun dart at Rechtshandler from\u000ashort range. It is coated in Black Lotus ( **WFRP**, p. 306)\u000alike the needle in the cushion (see _11:00 a.m._ ). Again,\u000athe adventurers can spot them with an **Opposed Perception/Stealth** Test, and raise a hue and cry to\u000aprevent them escaping.'),'[]');
INSERT INTO module_events VALUES(132,2,'12:45 a.m.',48,unistr('Rechtshandler cries out in dismay and clutches his neck,\u000apulling out the dart and showing it to the gravin, who stands\u000aand approaches the magistrates. The bout is stopped yet again\u000a- to some jeers and boos from the crowd - while the dart is\u000aexamined. Guards are dispatched into the crowd to try and find\u000athe attackers, but all they come up with is a discarded blowpipe,\u000awhich the cultists dropped after firing the dart. Meanwhile,\u000aRechtshandler is either black-faced and very dead, or not in\u000aparticularly good shape, so a clerk steps in to take over for the\u000arest of the trial.'),'[]');
INSERT INTO module_events VALUES(133,2,'12:45 a.m.',49,unistr('By now, the cultists have either been captured or they have made\u000agood their escape. The magistrates make another attempt to restart the trial, signalling the champions to take their positions as\u000aone of the magistrates raises a handkerchief.'),'[]');
INSERT INTO module_events VALUES(134,2,'Two Rounds Later...',50,unistr('The bout seems to be under way at long last, until Assistant\u000aMagistrate Gerhard Urteil suddenly stands up, his face a mask\u000aof horror and his arm stretched out toward the crowd. The\u000aadventurers may remember that he is the same magistrate who\u000aargued with the bounty hunter Ursula Kopfgeld earlier (see _9:45_\u000a_a.m._\u000a). Scanning the crowd, they find her standing toward the\u000aback, with a small, sleeping child on her shoulder.\u000a''Hanna!'' bawls the magistrate, rushing down from the stands\u000aand running across the ring where the champions have just\u000abegun to fight. The herald quickly stops the bout once more -\u000ato more boos and catcalls from the crowd - as the magistrate\u000acrosses the ring and tries to push his way through the crowd on\u000athe other side. Ursula is already running towards a horse that\u000ais hitched to a post outside a nearby building: it will take the\u000aCharacters 3 Rounds of pushing through the crowds to reach\u000aher, but by that time she will already have mounted and spurred\u000aher horse away.\u000aHanna is Urteil''s daughter. If the party can stop the bounty\u000ahunter, they may be able to find out the full story: when Ursula\u000abrought the head of the wanted agitator Josef Aufwiegler to\u000aKemperbad to claim her bounty, a corrupt magistrate cheated her\u000aand claimed the bounty for himself.\u000aHe dismissed her when she approached him this morning, so\u000aUrsula retaliated by kidnapping his daughter. She intends to keep\u000athe girl until the magistrate pays her what she is owed. Ursula\u000aused a harmless drug to put the little girl to sleep, and looks after\u000aHanna with great care - she is a hard-bitten bounty hunter,\u000acertainly, but she has no desire to harm an innocent child on\u000aaccount of a parent''s transgressions.\u000aThe Watch is mobilised, but will be too late to stop the escaping\u000abounty hunter by itself. The distraught Urteil is led away weeping\u000aand raving, while the herald announces that Mother Petra\u000aSteinmetz, High Priestess of Verena will take his place.'),'[]');
INSERT INTO module_events VALUES(135,2,'1:00 p.m.',51,unistr('Once again, the champions take their places and the white\u000ahandkerchief is raised. And at last, the bout gets under way in\u000aearnest. The crowd cheers for both champions, less interested in\u000athe causes they represent than in their ability to spill blood. The\u000adignitaries in the stand watch closely, alert for any breach of the\u000arules. Clerks make notes and the two nobles shoot each other\u000aglances that are smug and venomous by turns, whenever one\u000achampion wounds the other.\u000aPlay the bout using the normal combat rules, but remember\u000athe fight is the spectacle here, and that plenty of time should\u000abe spent savouring the details and the crowd''s reaction to them.\u000aEventually, one champion weakens and falls to the bloody,\u000asawdust-covered ground, unable to rise: the bout is decided,\u000aand the trial is over. A huge cheer erupts from the crowd. Then\u000asomething terrifying happens.\u000a# Who Won?\u000aEight watchmen step into the ring. Unless the party intervenes,\u000athree seize the fallen, bleeding champion while a fourth cuts off\u000athe Character''s head; four more attempt to do the same to the\u000avictor. As blood pours onto the ground, the watchmen cry ''Blood\u000afor the Blood God!'' Characters passing a **Challenging (+0) Lore (Theology)** Test recognise this as a profane warcry of Khorne, the\u000aBlood God. An Impressive Success (+4) or better also allows the\u000aPCs to know that eight is Khorne''s sacred number.\u000aAny of the watchmen not fighting then draw daggers and cut\u000atheir own throats, spraying blood everywhere. As the crowd gapes\u000ain horror, the blood draws in on itself, ripples, then pools upright\u000ainto several slick forms. The watchmen are survivors of a Chaos\u000acult recently rooted out by the authorities ( _Plot 6_ ), and their\u000asacrifice is an act of revenge that summons Bloodletters, ferocious\u000aDaemons of Khorne. The exact number is up to you: there should\u000abe enough so the Characters can only overcome them after a hard\u000afight (with the help of any others they can rally to their side). The\u000aDaemons attack anything close - they care not from whence the\u000ablood flows, just that it does.\u000a**Who Won?**\u000aOnce the Daemons are destroyed, any surviving magistrates\u000arender their verdict. The outcome is clear enough: the champion\u000astill standing when the renegade watchmen came forward wins.\u000a**RESOLUTION Rewards**\u000aAs well as the usual awards for good roleplaying and bright ideas,\u000aexperience points should be awarded for the following. There are\u000avariable amounts on offer: the more involved the Characters are\u000awith resolving the situation, the more points should be awarded.\u000a10-50 points if the gravin wins\u000a10-50 points for each time the Dammenblatz agent is foiled\u000a10 points for thwarting the _Ordo Ultima_ cultists\u000a20 points for helping capture the cultists\u000a20 points for helping deal with the Ghost\u000a5 points for helping the wounded in the crowds\u000a10-30 points for helping recover the magistrate''s daughter, Hanna\u000a20 points for capturing Ursula Kopfgeld\u000a**Aftermath Following the Campaign**\u000aIf the gravin''s champion was victorious, Maria-Ulrike is free\u000ato leave Kemperbad. Her party travels to Nuln, there to report\u000athe outcome of the trial to Grand Countess Emmanuelle von\u000aLiebwitz. If Baron von Dammenblatz wins, he insists the gravin be\u000aburned without any further delay. If Matthias Hubkind the witch\u000ahunter is still alive, he offers to have a stake and firewood ready\u000awithin the hour.\u000aHowever, Rechtshandler - or his replacement - claims the\u000aoriginal charge was imprecise and requires clarification. The\u000acomplaint accused the gravin of causing a death by poisoning\u000aor by witchcraft, but the trial by combat did not establish which\u000aof these means was used. While witchcraft is punishable by\u000aburning, the penalties for murder by poison are different -\u000aand, in the case of a noble, commutable to a fine. The lawyer\u000aentreats the magistrates to accept a payment of bail and hear\u000afurther arguments at a later time. Any surviving magistrates,\u000abacked up by Mother Steinmetz of the cult of Verena, agree\u000ato Rechtshandler''s motion. Both parties are to return to\u000aKemperbad in one month.\u000aLater, the gravin''s lawyer promises that any further proceedings\u000acan be delayed almost indefinitely, and that the court will almost\u000acertainly find in her favour - especially if the Characters testify\u000aon the murder of Bruno Franke at the Three Feathers and the\u000aattempts by the Baron''s agent to sabotage the trial.\u000a**A Stand-Alone Adventure**\u000aIf _A Day at the Trials_ is played as a stand-alone adventure,\u000athe Characters are under no further obligation to the gravin.\u000aHowever, before they part ways, she insists each of them dictates\u000aa full account of the day''s events for her lawyer to cite later. In\u000athe future, when least expected, the party\u000amay receive a message from the\u000agravin, summoning them back\u000ato Kemperbad as witnesses...\u000a**NON-PLAYER CHARACTERS The Gravin s Party**\u000aUse the statistics on pages\u000a16-18 for the gravin and\u000aher party.\u000a**The Dammenblatz Party Baron Otto von Dammenblatz**\u000aIn his late 30s, Otto has been angry\u000ahis entire life. Though years in the\u000aState Army have left him relatively\u000afit, he was never much of a fighter,\u000apreferring fierce debate to physical\u000asolutions. His accent is urbane, but\u000asomewhat monotone.\u000a# The Agent\u000a|M|WS|BS|S|T|I|Ag|Dex|Int|WP|Fel|W|\u000a|---|---|---|---|---|---|---|---|---|---|---|---|\u000a|4|52|67|51|49|41|42|42|47|43|54|17|\u000a**The Agent**\u000aIf Dominique Herveaux survived _A Rough Night at the Three_\u000a_Feathers_, she''s back, having escaped custody to continue her\u000awork. To ensure she''s not recognised, she has cut her hair\u000ashort, bleached it blonde, and donned a heavy hood. She also\u000aadopts a thick Talabeclander accent. She''s very good at her job,\u000ameaning any Tests to recognise her are at least **Very Hard (−30)** .\u000aIf Dominique is already dead, von Dammenbratz hires Wilhelm\u000aKönig to replace her. Use Dominique''s statistics from page 18 to\u000arepresent Wilhelm, but reduce all Attributes and Skills by −10\u000a**The Agent''s Snake**\u000aNormally no longer than 3'' in length, the Imperial Viper is one\u000aof the more deadly snakes in the Empire. It typically inhabits\u000ameadows, fields, and rocky hillsides, and is known for its irritable\u000adisposition. It readily strikes when approached, and its venom is\u000apotent enough to kill.'),'[]');
INSERT INTO module_events VALUES(136,3,'6:30 p.m.',52,unistr('**Events**\u000aThese events can be affected by what the adventurers do and\u000awhere they are at any particular time. The GM should also feel\u000afree to change events and times as required.'),'[]');
INSERT INTO module_events VALUES(137,3,'6:30 p.m.',53,unistr('The Grand Countess sends servants to ensure her box is made\u000aready and is safe. If you wish, the gravin may send the more\u000asocially adept Characters (or the whole party, if that makes things\u000aeasier) to observe and help as needed. Although the PCs have\u000abeen with her for a little while now, she considers them a band\u000aof wandering ne''er-do-wells, and she wants them to take every\u000aopportunity to learn the duties of good servants.\u000aHowever, on reaching the opera house, the Countess''s head\u000aservant declines the Characters'' help, in terms that are faultlessly\u000apolite, immovably definite, and a little - but only a little -\u000ademeaning. Unless anyone insists on watching and promises to\u000akeep out of the way, the party is free to wander the lobby and see\u000athe final preparations being made for the evening. The party will\u000anot be permitted into any other part of the opera house, except\u000afor the staircase and corridor leading to the Ducal box.\u000aOn a successful **Perception** Test, the adventurers realise they and\u000atheir companions from the palace are being watched: a small,\u000anondescript man stands outside and ccasionally takes notes. If\u000achallenged, he runs for the surrounding alleys. If captured, a small\u000anotebook and a charcoal pencil is in his possession. The notebook\u000acontains details of everyone from the court and the gravin''s\u000aentourage who has come and gone between the palace and the\u000aopera house that day. The man refuses to answer questions, but\u000aextreme measures may force him to reveal that he is working for a\u000awitch hunter named Matthias Hubkind, who is interested in the\u000agravin, the Countess, and all of their associates ( _Plot 7_ ).'),'[]');
INSERT INTO module_events VALUES(138,3,'7:00 p.m.',54,unistr('The lamps are lit and the doors are opened. People begin to arrive\u000aat the opera house, and the lobby soon fills up with people dressed\u000ain their finest, laughing, chatting, posing, and taking advantage of\u000athe bars set up in the lobby and the gallery. Wine and brandy are\u000aavailable, with a fruit punch on hand for those who prefer not\u000ato drink alcohol. Prices are not cheap (1/- for a drink of wine\u000aor brandy, 4d for the punch), and requests for anything else -\u000aparticularly ale - are met with a raised eyebrow, a sniff, and the\u000apatronising explanation that the opera house serves people of\u000aquality, and people of quality do not drink such things.'),'[]');
INSERT INTO module_events VALUES(139,3,'7:40 p.m.',55,unistr('There is a commotion in the lobby as two groups of students\u000afrom the Imperial Gunnery School throw firecrackers at each\u000aother ( _Plot 2_ ). They are from two different parts of the school:\u000athe Faculty of Direct Fire (cannon) and the Faculty of Indirect\u000aFire (mortars). Each group is trying to prove the superiority of its\u000aown method: the cannon students are flinging single firecrackers\u000adirectly at their rivals, while the mortar students are lobbing\u000ahandfuls of the things in a high arc.\u000aThe faint-hearted scream, run, and hide. Opera-house staff,\u000ahelped by a few members of the public (such as the Characters,\u000aif they choose to become involved), tackle the miscreants and\u000amanhandle them out. One elderly man seems particularly upset, and\u000aharangues the half-drunk and giggling students with threats of dire\u000aretribution: those who ask will be told that he is Professor Erwin\u000aPakker, a ballistics instructor at the Gunnery School and a man\u000aof great influence, if little popularity. Nearby Characters may spot\u000aGlimbrin is shadowing the professor with an **Opposed Perception/ Stealth** Test. The Gnome is skulking in the shadows, waiting for an\u000aopportunity to pick the aging academic''s pockets without observers.'),'[]');
INSERT INTO module_events VALUES(140,3,'7:45 p.m.',56,unistr('The Countess and her party, including any remaining Characters,\u000aarrive at the opera house by coach, escorted by her shining\u000ahousehold guard. Outside, crowds cheer as inside opera house\u000astaff and dignitaries form a receiving line to bow as the Countess\u000apasses by and receive the honour of a word here and a smile there.\u000aThe gravin attends with her aunt, dressed in a similar fashion\u000ato her, which includes a tricorn hat, a high collar, and a panel\u000acut from the front of the skirt revealing stockings in household\u000acolours. Such clothes are enough to cause a scandal in Altdorf,\u000abut are commonplace in the Countess''s Nuln.\u000aAmong the loyal throng are several senior members of House\u000aPfiefraucher - Wissenlander nobles who currently enjoy the\u000aCountess''s favour. If Baron Freidrich is still alive (see page\u000a19), he stands behind his father, Count Bruno Pfiefraucher of\u000aGrissenwald and Kreutzhofen, somewhat sulkily. He is notably\u000awithout his paramour from the Three Feathers.\u000aAs the Countess pauses to exchange a few words with Count\u000aBruno, he loudly denounces her as a common street harlot, smiling\u000agenially as he does so. As shocked silence spreads, the count''s face\u000asuddenly becomes a mask of horror as he immediately falls to his\u000aknees and blusters apologies, his hands over his mouth. Outside the\u000aopera house, a wizard hired by the Toppenheimers ( _Plot 5_ ) to cast\u000athe Spell _Murmured Whisper_ (a spell that is not strictly even legal)\u000aslips from the crowd outside, her job done. Unless the Characters\u000aare especially vigilant, they are very unlikely to catch her.\u000aBack inside the opera house, the Countess allows silence to reign\u000abefore eventually smiling. She gestures for the grovelling count to\u000arise. _''Darling, whilst I''m sure the view down there has much to merit_\u000a_it, there is no need to crawl.''_ She then leans in close and reassures\u000athe mortified baron with a few gracious words before moving on,\u000aher entourage in tow. Nervous bystanders bow until she is out of\u000asight, then the gossip begins.\u000aOnce in the corridor leading to her ducal box, the Countess rages\u000aat her staff: _''Find me the bloody witch behind that farce, and_ _**find it**_\u000a_**now**_ _! And if it''s another bloody Grey, I swear I''ll ban them_ _**all**_ _from my_\u000a_city! Permanently!''_ She then turns to the gravin. _''Sorry you had to see_\u000a_that, darling. It''s my fault, I left my wizards at the palace. Foolish of me,_\u000a_but they get on my nerves with their constant interference. Come, let''s sit_\u000a_down, watch this opera, and celebrate our victory.''_'),'[]');
INSERT INTO module_events VALUES(141,3,'7:50 p.m.',57,'','[]');
INSERT INTO module_events VALUES(142,3,'7:50 p.m.',58,unistr('Scuffles break out in the balcony seats between some of the\u000ayounger Pfeifrauchers and Toppenheimers. More senior\u000amembers of both noble Houses attempt to keep order, issuing\u000astern warnings before departing to their boxes, quite confident\u000athe foolishness is resolved.'),'[]');
INSERT INTO module_events VALUES(143,3,'7:55 p.m.',59,unistr('Almost as soon as more senior backs are turned, Herbard\u000aPfiefraucher, a young man who has taken to accusing the\u000aToppenheimers (correctly) for his uncle''s embarrassment before\u000athe Countess, is thrown over the balcony by Gerlecht and\u000aSölbrecht Toppenheimer, a rather rowdy pair of twins. Herbard\u000ahowls as he falls into a group of unfortunates in the cheaper\u000aseats below. Three people, including Herbard, require medical\u000aattention. The two Toppenheimers are ejected from the opera\u000ahouse by the Countess''s guard (perhaps with the Characters''\u000ahelp), though the twins are too busy laughing at the evening''s\u000aevents to care.'),'[]');
INSERT INTO module_events VALUES(144,3,'8:00 p.m.',60,unistr('With everyone in their seats, the orchestra strikes up the overture,\u000athe curtain rises, and the show begins.'),'[]');
INSERT INTO module_events VALUES(145,3,'8:02 p.m.',61,unistr('Disguised as opera house staff, two Dammenblatz agents (one\u000aof whom is Dominique Herveaux, if she still lives) carry a large\u000apotted plant to the antechamber of the Ducal box. If challenged,\u000athey claim that management received a message from the box\u000acomplaining that the antechamber was somewhat drab and\u000awould be improved by some greenery. The plant''s pot is filled with\u000agunpowder, and has a concealed fuse ( _Plot 1_ ).'),'[]');
INSERT INTO module_events VALUES(146,3,'8:04 p.m.',62,unistr('As soon as the plant is delivered, an agent of the witch hunter\u000aMatthias Hubkind stations himself at the end of the corridor\u000aleading to the Ducal box, with orders to watch who comes and\u000agoes. If challenged, he will pretend to be lost and make his way\u000adownstairs amid many apologies ( _Plot 7_ ).'),'[]');
INSERT INTO module_events VALUES(147,3,'8:05 p.m.',63,unistr('If the gravin''s lawyer, Gustaf Rechtshandler, is still alive, he meets\u000ain the ducal box''s antechamber with his counterpart from the\u000acourt of Nuln, one Brecht Kavenner. Rechtshandler brief ''s him\u000aon the proceedings at the trial and discuss what its outcome\u000ameans for the Grand Countess, who was also named in the\u000aDammenblatz complaint.'),'[]');
INSERT INTO module_events VALUES(148,3,'8:10 p.m.',64,unistr('A Valantina assassin ( _Plot 6_ ) creeps into the balcony, armed with a\u000acompact crossbow pistol that''s loaded with a bolt coated in Black\u000aLotus ( **WFRP**, p. 306). He locates Albrecht Oldenhaller and\u000atakes up a position at the back of the balcony about four yards\u000aaway, with a clear line of sight. Everyone is looking at the stage,\u000aso no one notices as he reaches inside his short Miraglianese cape\u000afor the weapon - and slumps to the floor, dead.\u000aAnyone who is looking directly at the assassin may spot the rival\u000aHuydermans assassin as she glides up behind him, slips a thin\u000aand deadly blade into his ear, and carries on without breaking\u000aher stride, taking a vacant seat with many whispered apologies\u000ato her neighbours.\u000aThe dead assassin lays on the floor at the back of the balcony until\u000adiscovered. The murder weapon in his ear is a thin piece of metal,\u000aattempts to kill him at the trial (see page 28).\u000aAs the two lawyers talk, Kavenner leans forward to touch\u000aRechtshandler on the arm. This is no innocent gesture, but\u000athe completion of a Spell that Kavenner prepared earlier.\u000aUnless Rechtshandler makes a successful **Challenging (+0) Endurance** Test, he will gain one physical mutation, rolled on\u000athe Physical Corruption Table ( **WFRP**, p. 184). Even if the\u000aTest is successful, Rechtshandler gains one _Stunned_ condition\u000aand 1 Corruption point.\u000aHaving cast the Spell, Kavenner leaves the anteroom with the\u000awords, '' _now you cannot deny that you are one of us_,'' and returns\u000ato his chambers in the palace. On the way out, he will pass\u000aHubkind''s agent ( _Plot 7_ ), who withdraws to the gallery whenever\u000ahe sees anyone coming down the corridor towards him. As\u000aKavenner passes, the agent murmurs a short phrase, audible only\u000ato the lawyer and himself, which is a recognition code used by\u000aSlaanesh cultists throughout the Empire. Distracted and in a'),'[]');
INSERT INTO module_events VALUES(149,3,'8:30 p.m.',65,unistr('hurry, Kavenner requires a successful **Willpower** Test to avoid\u000agiving the correct response without thinking: if he does so, he will\u000abe so rattled that he will break into a run once out of the opera\u000ahouse, and run straight into Hubkind and his accomplices, who\u000aare waiting in the shadows of a nearby alley and were alerted by\u000athe agent signaling from the gallery window.\u000aIf he is mutated, Rechtshandler tries to flee the opera house\u000awithout being spotted. If Hubkind''s agent in the corridor sees\u000ahim (see _8:04 p.m._ above) and notices his mutation (which\u000awill depend on its precise nature), he will leave immediately\u000aand report to his master. The witch hunter will then capture\u000aRechtshandler, and the confrontation between the witch hunter\u000aand the Countess (see _11:30 p.m._ below) will be that much worse\u000afor this ''evidence'' of corruption in high places.'),'[]');
INSERT INTO module_events VALUES(150,3,'8:30 p.m.',66,unistr('With the opera house staff relaxing now the performance has\u000abegun, two students sneak into the auditorium and locate the seats\u000aoccupied by Professor Pakker (see _7:40 p.m._ ) and his wife, near the\u000acentre aisle. Unless spotted and stopped, they will retreat to the\u000aback near the door, light the fuse on a string of firecrackers using a\u000asmall fire-pot they carry, and lob the string toward their foe.\u000aMost members of the audience will notice nothing until the\u000aglow of the lit fuse arcs through the air, landing a split-second\u000alater with a barrage of small explosions. You can roll to hit if\u000adesired: assume the thrower has **BS** 50 and Ranged (Explosives)\u000a50, while the string of firecrackers has Damage +0, _Blast_ 1,\u000a_Dangerous_, and a 5% chance of causing 1 _Ablaze_ Condition to\u000aany Character within 1 yard, even if no Wounds are suffered.\u000aThis chance is increased at your discretion if a victim is wearing\u000aparticularly flammable clothes, such as a laced formal gown.\u000aThe students will try to flee if they realise they have been spotted,\u000aalthough one of them will still try to throw the firecrackers in\u000apassing. The performance is brought to a halt amid screams and\u000acurses, but fortunately panic does not break out. In the general\u000ahubbub, Glimbrin the Gnome slips under Professor Packer''s\u000achair, to better place himself to steal the keys to the Imperial\u000aGunnery School ( _Plot 2_ ). If the students are apprehended, they\u000acan be handed over to the Watch: they will spend the rest of\u000athe night in the cells, to face a fine for breach of the peace in\u000athe morning, followed by the wrath of the Gunnery School''s\u000aChancellor-General and almost certain expulsion.\u000aProfessor Pakker and his wife are shaken, but not seriously\u000ahurt. Loudly declaring that he will deal with these young\u000ahooligans later and not allow them to ruin his evening,\u000ahe reclaims his seat. After an awkward pause, and a\u000asmattering of applause, the performance resumes.\u000aThose watching this may attempt an **Opposed Perception/Stealth** Test to spot Glimdrin hiding\u000aunder the Professor''s seat. The Gnome is perfectly\u000aplaced for his thievery, but dares not move when\u000aso many people are watching the professor.'),'[]');
INSERT INTO module_events VALUES(151,3,'9:30 p.m.',67,unistr('The first half concludes and the curtain is lowered to thunderous\u000aapplause. Most audience members leave their seats, heading either\u000ato the lobby or the gallery where liveried opera-house staff are\u000awaiting with wine and canapes. Some of ''the quality,'' as theatrefolk call them, take the opportunity to visit each other''s boxes.\u000aRefreshments are brought to the ducal box, and a servant informs\u000athe Countess that people are waiting to pay their respects. With a\u000atheatrical sigh, she goes to the box''s antechamber to receive them.\u000aAs opera-house lackeys light candles in the room''s wall-sconces,\u000aone of the Dammenblatz agents stealthily lights the fuse to the\u000abomb in the plant pot: it is positioned out of sight, but a **Difficult (−10) Perception** Test can be made to hear the soft fizzing of the\u000afuse or spot a telltale wisp of smoke from behind the pot: if you\u000afeel it''s appropriate, Characters with gunpowder-related Skills\u000aor Talents - such as _Ranged (Blackpowder), Trade (Gunsmith,_\u000a_Explosives),_ or _Craftsman (Explosives)_ - reduce the Difficulty by\u000aone step. The fuse is a slow one, set to burn for an hour, so that the\u000abomb will detonate in the middle of the second act ( _10:45 p.m._ ).\u000aDetonation can be prevented by pulling the fuse out.\u000aMeanwhile, another of Hubkind''s agents is stationed in the\u000agallery, watching the goings-on and paying particular attention\u000ato the Countess and her party.'),'[]');
INSERT INTO module_events VALUES(152,3,'9:32 p.m.',68,unistr('In the upstairs gallery, three young Toppenheimers stand around\u000adrinking and laughing about the unfortunate '' _Pfiefraucher fall_ ''\u000a( _7:55p.m._ ). Their jokes and chuckles reach the ears of a half\u000adozen young Pfiefrachers, who confront the Toppenheimers'),'[]');
INSERT INTO module_events VALUES(153,3,'9:34 p.m.',69,'','[]');
INSERT INTO module_events VALUES(154,3,'9:34 p.m.',70,unistr('Albrecht Oldenhaller goes to the gallery, approaching one\u000aof the tray-bearing servants for a drink. Just as he gets there,\u000aan attractive young woman - the Huydermans assassin -\u000aaccidentally bumps into him, apologising profusely and dazzling\u000ahim with her smile. He insists she take the last drink on the tray.\u000aThe two talk for a moment, and then she turns, wide-eyed, with\u000aa gasp, spinning the Councillor around and knocking a nearby\u000aman into a chair. Laughing at herself, she explains to the startled\u000aOldenhaller that she thought she saw the Countess coming out,\u000abut was mistaken. As she turns to apologise to the man in the\u000achair, he slumps forward, seeming asleep or drunk. She laughs,\u000aand steers Oldenhaller toward an approaching servant who\u000acarries a fresh tray of drinks.\u000aIt takes an **Oppose** d **Perception/Stealth** Test to see that the fallen\u000aman - another assassin, hired by the Schatzenheimer family -\u000ahad a dagger in his hand, and that by spinning the Councillor\u000aaround she also grabbed this man by the wrist and guided his blade\u000ainto his own heart. Another, identical Test is required to spot her\u000adropping a clear liquid into Oldenhaller''s fresh drink from a tiny\u000acompartment in a ring: this is Heartkill ( **WFRP**, p. 306).\u000aHowever, as she does so, she clutches her heart and screams. Over\u000athe next few seconds, horrified onlookers see her age twenty\u000ayears or more: white shoots through her hair, wrinkles shrivel her\u000aface, and her elegant, manicured hands become wizened claws.\u000aThe servant drops his tray in apparent horror and goes to her\u000aassistance, while others rush to assist her and the dumbstruck\u000aCouncillor.\u000aIn the commotion, Oldenhaller''s drink falls to the floor, and\u000ahe almost does likewise: a few onlookers rush him and the no\u000alonger-young lady outside ''for some air.''\u000aAll of these - including the opera house servant - are Nurgle\u000acultists, determined to take Oldenhaller alive and torture him for\u000athe location of their sacred gem ( _Plot 6_ ). If necessary, they use\u000aSpells like _Shock_ and _Sleep_ to subdue him so that he can be taken\u000aout of the opera house and spirited away to a cult base in the city.\u000aThere is a chance that Hubkind''s agent will recognise one or more\u000aof the cultists, either from having had them under observation\u000abefore or from their behaviour. When the aging Spell takes\u000aeffect on the assassin, the agent is permitted a **Challenging (+0) Intelligence** Test to suspect that it is Chaotic in origin, and an\u000a**Average (+20) Perception** Test to identify those involved in\u000adisabling the assassin and kidnapping the Councillor. In that\u000acase, he will follow the cultists outside and signal Hubkind, who\u000ais waiting in the shadows with a half dozen accomplices; they will\u000aattack the cultists and try to rescue the Councillor.'),'[]');
INSERT INTO module_events VALUES(155,3,'9:35 p.m.',71,unistr('The throng of people waiting to pay their respects to the Countess\u000aparts amid excited whispers: as they come closer, the name ''Detlef\u000aSierck'' can be heard.\u000aSierck is the Empire''s greatest living playwright, famous for\u000afacing the dreaded Drachenfels some eight years ago. His play\u000a_The Tragedy of Oswald_, which dramatically details the terrible\u000aevents and paints Sierck as a hero, is wildly popular. Natives of\u000aNuln - and, if you wish, any Characters with the _Lore (Nuln)_ or\u000a_Perform (Acting)_ Skills, or some other reason to be knowledgeable\u000aabout the theatre - automatically know that Sierck was born\u000ain the city, which is very proud of its native son; others might\u000arequire a **Challenging (+0) Intelligence** Test to know this.\u000aSierck is conducted forward by a slender, well-dressed young\u000aman with curly, red-brown hair and a large, drooping moustache.'),'[]');
INSERT INTO module_events VALUES(156,3,'9:55 p.m.',72,unistr('This is Edwina Lowenherz, the daughter of the actor Edvard\u000a( _Plot 3_ ) in disguise: to notice that something is wrong about the\u000ayoung man requires an **Opposed Perception/Entertain (Acting)**\u000aTest against Edwina. Bowing to the Countess and her party, the\u000ayoung man introduces the celebrated actor and playwright with\u000aa gravel-voiced, _''Detlef Sierck, your Grace''_ before standing aside\u000aas Sierck steps forward to bow in his turn. At that moment,\u000aseveral things happen very quickly: the frustrated actor Edvard\u000aLowenhertz is playing out his long-planned revenge.\u000aA tall, hooded figure steps forward from the crowd, brushing Sierck\u000alightly with one hand and pronouncing a strange syllable. The\u000aplaywright twitches slightly, and appears confused (Lowenhertz\u000ahas cast a _Shock_ Spell on him, giving him one _Stunned_ Condition).\u000aAt the same time, the ''young man'' mutters in a low voice and\u000aSierck''s cloak wraps around him, holding him as fast as a shroud\u000a(an _Entangle_ Spell, giving him one _Entangled_ Condition).\u000aThe hooded figure throws off his cloak, and onlookers gasp: the\u000afigure of Constant Drachenfels stands before them, familiar to all\u000afrom Sierck''s play _The Tragedy of Oswald_ . (Lowenherz is dressed\u000ain a fair-to-middling theatrical costume, which he has enhanced\u000aby casting _Fearsome_ on himself) _._ Everyone who sees him must\u000amake a **Fear 1** Test.\u000a_''Detlef Sierck,''_ he intones, his voice ominous but rather overdone,\u000a_''you wronged Edvard Lowenherz with your pen many years ago._\u000a_Now he shall be avenged by the hand of your own creation!''_ No longer\u000a_Stunned_ but still _Entangled_ and more than a little confused, Sierck\u000arecites a few lines of his famous play in a voice that is not his own\u000a(Edwina, hiding in the crowd, is using the _Murmured Whisper_\u000aSpell). ''Drachenfels'' reaches out a skeletal hand and, with the\u000acry _''In the name of Drachenfels!''_ - an obvious parody of Sierck''s\u000afamous line _''In the name of Sigmar!''_ from the play - clamps his\u000ahand on the playwright''s forehead. Sierck screams as the mad\u000aactor''s _Caress of Laniph_ Spell takes effect.\u000aBy this time, someone - ideally the Characters - should have\u000aintervened, but Lowenhertz is not expecting any interference:\u000ain his mind, the brilliance of his performance will keep the\u000aonlookers transfixed indefinitely. If no one acts to stop him or to\u000ahelp Sierck, Lowenhertz will continue to drain Sierck''s life using\u000a_Drain_ Spells, all the while declaiming in the same melodramatic\u000astyle that drew the ridicule of critics all those years ago. He starts\u000awith Drachenfels'' lines from the play, changed where necessary\u000ato reflect the situation, and goes on to improvise, becoming more\u000agrandiose until he is stopped or Sierck is dead (or appears to be: as\u000aa famous Character who has survived some perilous adventures,\u000athe GM may be forgiven for allowing him some Fate Points).\u000aIf tackled, Lowenhertz struggles, favouring wide, theatrical gestures\u000aover effective fighting moves. As he is carried away, he rants and\u000araves about Sierck and his poisoned pen: some in the crowd may\u000aremember that as a student, Sierck wrote a particularly barbed\u000areview of Lowenhertz''s first - and last - stage performance, after\u000awhich the actor disappeared from sight.\u000aMeanwhile, the ''young man'' played by Edwina seems to have\u000avanished; as soon as her father''s capture seemed inevitable, she ran\u000adownstairs, shouting in her gravelly assumed voice that someone\u000awas trying to murder the Grand Countess. This sent a crowd of\u000aopera house staff, the Countess''s guard, and valiant onlookers\u000apounding up the stairs, making it impossible for anyone to follow\u000aher. Once downstairs, she ducked into a storage room where she\u000ahad previously stashed a change of clothes, and made her way\u000aout dressed as a male servant (with straight, sandy hair this time)\u000acarrying a food hamper marked with the arms of the Richtofen\u000afamily, owners of the city''s largest cannon foundry and patrons of\u000athe arts with a box at the opera. From there, she lost herself in the\u000amaze of streets, dumping the hamper and reversing her doublesided cloak as a precaution.\u000aEdwina maintains a low profile for a few days, giving the gravin\u000aand her party enough time to move on. They may never see her\u000aagain - if, indeed, they can be said to have seen her this time -\u000abut they may hear of elaborate murders in Nuln over the next few\u000amonths, all with a theatrical twist: a wall of the Schlossfels Watch\u000aStation collapses in the same way as the wall of the Jutones'' fortress\u000ain Sierck''s _The History of Sigmar,_ with Edvard Lowenhertz among\u000athe escapees; next, several lesser playwrights and critics die in\u000aways inspired by their own works, or the works they have praised\u000amost highly in print; and finally, several attempts are made on the\u000alife of Detlef Sierck, wherever he may be at the time.'),'[]');
INSERT INTO module_events VALUES(157,3,'9:55 p.m.',73,unistr('A gong announces the end of the interval, and everyone drifts back\u000ato their seats. Among the throng are two more students ( _Plot 2_ ), who\u000asneak into the main auditorium and conceal themselves among the\u000ashadows at the back. One of them seems to have something large\u000aand bulky under his coat, and they will flee if challenged.'),'[]');
INSERT INTO module_events VALUES(158,3,'10:00 p.m.',74,unistr('With most of the audience back in its seats, and the few stragglers\u000abeing soundly hissed and pushed into place, the curtain rises for\u000athe second act.'),'[]');
INSERT INTO module_events VALUES(159,3,'10:05 p.m.',75,unistr('The two students light the fuse on a spherical artillery shell and roll\u000ait down the centre aisle towards the seats occupied by Professor\u000aPakker and his wife. There are gasps and curses from every row\u000ait passes, and it comes to a stop right beside the professor, its\u000afuse fizzing. The professor looks down at the shell, and even in\u000athe darkness of the auditorium his face seems to drain of colour.\u000aSuddenly, multicoloured sparks shoot out of the iron ball, coming\u000aout through the touch-hole that once held the fuse.\u000aThe whole thing is a relatively harmless prank, but the damage\u000ais done. Panic is sweeping the audience, and a stampede will\u000afollow unless someone can restore calm. Suitable Skills include\u000a_Charm, Entertain (Speeches),_ and _Leadership_, while Talents like\u000a_Commanding Presence, Inspiring, Master Orator,_ and _Public Speaker_\u000acould all be useful.'),'[]');
INSERT INTO module_events VALUES(160,3,'10:45 p.m.',76,unistr('If no one else tries to calm the crowd, the Countess herself stands\u000aup and, in a surprisingly robust voice, stills the crowd, urging\u000athem to remain calm and reassuring them that this was nothing\u000amore than a harmless but idiotic prank. All eyes are upon her, and\u000aas she motions the audience to sit, they do so - almost without\u000aknowing it. She nods to the conductor in the orchestra pit, who\u000aresponds with a low bow and taps his baton. The music swells,\u000aand the performance resumes.\u000aGlimbrin uses this disturbance to pick the professor''s pocket,\u000aand steal a key to the Imperial Gunnery School''s main ordinance\u000avault. He will make his way outside the opera house by the most\u000astealthy route he can find. When he reaches the Gunnery School,\u000ahe burgles as many experimental weapons as he can find. He\u000aintends to send the weapons back to the burrows of Glimdwarrow\u000a(see page 86) as a last line of defense for his people should their\u000alands be invaded again.'),'[]');
INSERT INTO module_events VALUES(161,3,'10:45 p.m.',77,unistr('The bomb concealed in the potted plant in the antechamber\u000ato the Ducal box explodes, unless the fuse has been pulled out\u000aearlier. A huge bomb, it has the _Blast 10_ Quality and causes\u000aDamage 1d10+15 Damage. Anyone affected, also takes Agility\u000aBonus − 1d10 _Ablaze_ Conditions. Those reduced to 0 Wounds\u000asuffer 1 Critical Wound to a random Hit Location for every 2\u000aWounds they would fall below 0, rounding up. So, if a Character\u000awould be reduced to −5 Wounds by the blast, 3 Critical Wounds\u000aare suffered.\u000aThe blast shreds the walls of the box, the antechamber, and\u000aneighbouring boxes, as well as the ceiling and floor. For those\u000asurviving the blast, a **Difficult (−10) Athletics** Test is required to\u000aavoid falling through the ruined floor onto the audience below\u000a(for a 7-yard fall).\u000aThe performance, of course, comes to an abrupt end, and the\u000asurviving audience members shout, scream, and stampede for the\u000adoors; the slower and weaker are trampled, some of them fatally.'),'[]');
INSERT INTO module_events VALUES(162,3,'11:00 p.m.',78,unistr('If nothing else has caused the performance to be abandoned, the\u000acurtain falls to great applause. Most of the audience begins to\u000aleave the opera house, but the nobles stay in their boxes, ordering\u000afresh drinks and food.\u000aMore people gather outside the ducal box to pay their respects\u000ato the Countess, who receives them in the antechamber\u000aas before. Among them is Count Bruno Pfiefraucher -\u000abut as he bows to kiss the Countess''s outstretched hand, a\u000aToppenheimer agent stealthily cuts his belt from behind\u000a(requiring a **Challenging (+0) Sleight of Hand** Test to perform\u000asuccessfully), causing the unfortunate count''s breeches to fall\u000adown. Instead of trying to escape through the shocked throng,\u000athe agent stays and acts as shocked as everyone else: if none of\u000athe Characters saw him carry out the deed, they might still be\u000aable to tell that he does not fit with the rest of the company.\u000aAn Opposed **Perception/Entertain (Acting)** Test against the\u000aagent will be necessary. If captured and questioned, the agent will\u000aconfess that he was hired by three of the younger Toppenheimers,\u000abut he does not know their names.'),'[]');
INSERT INTO module_events VALUES(163,3,'11:30 p.m.',79,unistr('The Countess, the gravin and their respective entourages leave\u000athe opera house, to find Hubkind and his followers waiting for\u000athem. Depending on the events of the evening, the witch hunter\u000amay have decided that one or both of them are either cultists\u000aor in league with cultists, and a tense standoff may develop as\u000aHubkind and his accomplices face the two noblewomen and\u000atheir accompanying guards outside the opera house.\u000aTo make things worse, a curious crowd gathers, made up of others\u000awho are late to leave the opera, people drawn from nearby taverns\u000aby the commotion, and passers-by on their way to or from the\u000acity''s various other entertainments. After a few minutes, the\u000aWatch arrives, and the standoff could potentially develop into a\u000ariot if the witch hunter refuses to give way to the Countess, or the\u000aCountess refuses to submit to his questions - or at least, give her\u000aword to grant him an audience at some later time, at which all his\u000aquestions will be answered. Characters with strong Fellowship\u000aCharacteristics and diplomatic Skills may be able to prevent a\u000agreat deal of unpleasantness, and potentially earn the gratitude of\u000athe Countess into the bargain.\u000aIf the Characters do nothing, the Watch will arrive in sufficient\u000astrength to escort the Countess and her party back to the palace,\u000asweeping aside the witch hunter and his accusations. However,\u000aby the next morning, Hubkind whips up an angry mob from\u000aamong the city''s malcontents and Sigmarite faithful, whom\u000aalready disapprove of the licentious ruler; a noisy protest outside\u000athe palace may flare into violence against anyone coming or\u000agoing, and even to talk of overthrowing the Liebwitz family;\u000awhich, of course, will please House Dammenblatz and House\u000aToppenheimer greatly, and receive their enthusiastic support.\u000a# Following the Campaign\u000a**RESOLUTION Rewards**\u000aAs well as the usual awards for good roleplaying and bright ideas,\u000aXP should be awarded for the following:\u000a50 points for thwarting the Dammenblatz bomb plot\u000a10 points for each time the gunnery students are twarted\u000a30 points for thwarting Edvard Lowenhertz''s revenge\u000a10 points for capturing Edvard (or 5 XP for killing him)\u000a10 points for capturing Edwina (or 5 XP for killing her)\u000a20 points for thwarting Kavenner''s attack on Rechtshandler\u000a20 points for exposing Kavenner as a Slannesh cultist\u000a10 points for each time an incident between the Toppenheimers\u000aand Pfeifrauchers is prevented\u000a10 points for keeping Alcrecht Oldenhaller alive and free of the\u000aNurgle cultists\u000a30 points for preventing Matthais Hubkind''s planned\u000aconfrontation with the Countess and gravin\u000a20 points for persuading Hubkind to pursue the _Ordo Ultima_ or\u000athe Nurgle Cult instead or pursuing the Liebwitzes\u000a15 points for preventing Glimbrin''s theft of Professor Pakker''s keys\u000aThere are many other things the PCs can do which will contribute\u000ato bringing the adventure to a satisfactory conclusion; feel free to\u000aaward XP for anything else that is deserving, using the general\u000alevel of the awards given above as a guideline.\u000a**Aftermatch Following the Campaign**\u000aYou can decide how successful Hubkind''s attempts to create unrest in\u000aNuln are. Many Nulners are loyal to their Countess, and even those\u000awho do not have the highest opinion of her abilities will not look\u000akindly on an outsider trying to stir up trouble. Even so, play out this\u000asituation at length if you feel your Players are enjoying themselves.\u000aSooner or later, though, another matter arises to take the gravin\u000aand her entourage out of Nuln. Her brother Karl-Heinz, and the\u000aheir to her Ambosstein titles and estates, is due to marry Nastassia\u000avon Saponatheim, the daughter and heiress of the ancient House\u000aSaponatheim of Reikland. Countess Emmanuelle is not attending\u000a(unless you decide otherwise), but she uses her influence to charter\u000athe luxurious river liner _Emperor Wilhelm_ for the exclusive use of\u000aGravin Maria-Ulrike and her party, who are accompanied by as\u000amany minor figures from the court of Nuln as you see fit, sent along\u000awith some lavish gifts from the Countess herself.\u000a**A Stand-Alone Adventure**\u000aIf the adventurers are not following the campaign, they could\u000astay in Nuln. Perhaps they are called upon to deal with various\u000asituations arising from this adventure: dealing with the unrest\u000aspread by the witch hunter Hubkind; reprisals, both legal and\u000aotherwise, against the Dammenblatz family; rooting out the\u000a_Ordo Ultima_ from the University of Nuln, and its alumni from\u000athe court; hunting down the Nurgle cult and finding out the\u000aawful truth about the gem and Councillor Oldenhaller''s business\u000adealings; smoothing things over between the Toppenheimers and\u000athe Pfeifrauchers; or facing any number of other problems.\u000aAlternatively, they could head down the river to Altdorf and\u000abegin the **Enemy Within** campaign, or travel elsewhere for\u000afurther adventures. The Empire is large, and the Old World larger\u000astill, and the river can take them almost anywhere they wish to go.\u000a**NON-PLAYER CHARACTERS The Gravin '' s Party**\u000aUse the statistics presented on page 16-18 for the gravin and her\u000atheatre-going party.\u000a**The Countess and Her Party The Grand Countess**\u000aknown as just ''the Countess'' - is\u000aa childhood friend of the Emperor,\u000aromances, she is reputed to be the\u000ain the Empire, as well as the most\u000awild temper, capricious nature, and\u000aher disdain for politics\u000adog her every step,\u000amostly shared by those\u000ajealous of her undisputed\u000agrip on Nuln. People of all ranks\u000aemulate her to curry favour or\u000asimply be like her, meaning her\u000ahas the right to a Runefang - one\u000aof the magical warblades gifted to\u000athe Empire by the Dwarfs long\u000aago - but she rarely wears\u000ait outside official\u000aoccasions, preferring\u000ato keep it locked in\u000aher royal armoury.\u000a# Brecht Kavenner, Lawyer'),'[]');
INSERT INTO module_events VALUES(164,4,'Angestag Afternoon',80,unistr('**Events**\u000aThe wedding ceremony is due to begin at noon on Festag (the\u000alast day of the eight-day week in the Empire). Guests begin to\u000aarrive on Angestag afternoon (the second-last day of the week),\u000aand the twenty-four hours before the wedding will prove to be\u000aquite eventful.\u000aSet out below is roughly what will happen during that time,\u000asubject to the effects of whatever the Characters decide to do\u000a- and to whatever tweaks, changes, and additional events you\u000adecide to throw in. The more, the merrier!'),'[]');
INSERT INTO module_events VALUES(165,4,'Angestag Afternoon',81,unistr('The trickle of guests arriving by road and river turns into a\u000aflood. At about 3:00 p.m. the river liner _Emperor Wilhelm_ arrives\u000aamid much excitement, carrying most of the von Liebwitz\u000aparty (assuming the Grand Duchess Emmanuelle pulled some\u000astrings to appropriate the liner; if not, the gravin and her staff\u000aarrive by barge). Although the Countess is not attending the\u000awedding in person, she has sent several gifts with the small\u000agroup of Nuln von Liebwitzes who have come along with their\u000aAmbosstein cousins.\u000aMeanwhile, the personal barges of other noble guests draw up\u000aalongside the castle''s landing stage. Occasional scuffles break\u000aout between crew members when two or more barges arrive at\u000athe same time. Nobles - especially minor nobles - are very\u000aconscious of status and precedence: everyone has an opinion\u000aabout whose boat should be the next to dock, and no one likes\u000ato be kept waiting.'),'[]');
INSERT INTO module_events VALUES(166,4,'Angestag Evening',82,unistr('A feast is held in the Great Hall to welcome the guests. Graf\u000aWilhelm von Saponatheim has spared no expense, even engaging\u000alegendary Bretonnian chef Marcel de Morceaux for the occasion.\u000aEntertainers of all kinds amuse the guests, including a troupe of\u000aacrobats from faraway Ind. Gossip and scandal run up and down the\u000ahall as the assembled nobles get down to doing what nobles do best.\u000aAmid the merry-making, observant Characters will notice a\u000afew things.\u000aA **Challenging (+0) Perception Test** ( **Average (+20)** for\u000aEntertainers) spots the acrobats from Ind are not playing\u000athe hall like the other entertainers. They start off moving\u000aaround, collecting money thrown on the floor like everyone\u000aelse, but after a few minutes pay close attention to a\u000agroup of nobles from Telland. Any Courtier who learns\u000athis may make a **Challenging (+20) Intelligence** Test\u000ato recall that Countess Clothilde of Telland - who is\u000asitting with the group in question - has been showing\u000aoff a pink ruby all season. The ruby is said to have been\u000abought by her son when he last sailed to Ind. The\u000aparty may also notice that a richly dressed ''Halfling''\u000a- in fact, Glimbrin in disguise - is watching\u000athe Countess and the Indish performers closely.\u000aIf confronted, Glimbrin will fake a high-brow accent he learned\u000afrom Seedling - his Halfling friend from _A Rough Night at_\u000a_the Three Feathers_ - and attempt to remove himself from the\u000asituation.\u000aA **Challenging (+0) Intuition** Test notes the bride-to-be, while\u000aoutwardly radiant, looks around from time to time as if scanning\u000athe hall for someone or something. She does not even glance\u000aat the bridegroom. Karl-Heinz the bridegroom, for his part, is\u000aenraptured by an elegant sword that is to be his wedding gift\u000afrom his new father-in-law. The blade placed on display in a\u000aglass case for all to see. Karl-Heinz spends much of the evening\u000aengaged in an excited discussion with Graf Wilhelm as they both\u000afawn over its design. As the wine flows, Karl-Heinz cannot help\u000abut boast and brag about the heroic acts he will achieve with such\u000aa sword by his side.\u000aA **Challenging (+0) Perception** Test ( **Average (+20)** for\u000aCourtiers, **Easy (+40)** for Rogues) spots a couple of the guests\u000awho seem out of place (this information is automatic for any\u000aCharacter with the _Etiquette (Nobles)_ Talent). They are as\u000aexpensively dressed as anyone else, but their clothes somehow\u000adon''t quite fit them properly. They keep to themselves, and don''t\u000aseem to know anyone else at the feast. Nobles may think they are\u000aprovincial merchants who have somehow wangled an invitation,\u000abut Rogues will have no doubt they are criminals of some sort.\u000aAt some time in the evening, the two sidle up to a table near the\u000abottom of the hall, position themselves on either side of a young\u000amale guest, and a quiet but clearly heated exchange takes place.\u000aCourtiers may attempt a **Challenging (+0) Intelligence** Test to\u000aknow that the young guest is a cousin of the von Saponatheims,\u000aGraf Johann von Gient, recently returned from Marienburg.'),'[]');
INSERT INTO module_events VALUES(167,4,'12 midnight',83,unistr('_in_\u000aA couple may slip off for a secret assignation, and be caught\u000a_flagrante delicto_ in some bedchamber, crypt, or shrubbery. A\u000avisiting servant may try to slip a piece of von Saponatheim\u000asilverware inside his or her clothing, or offer to sell family\u000asecrets to a rival. Practical jokes and acts of petty theft and\u000avandalism may take place. Wine is flowing and high-spirited\u000ayoung Nobles are having a good time, so almost anything could\u000ahappen.\u000aThe feast ends around 11:00 p.m. Guests drift, stagger, and are\u000acarried to the various guest rooms. Nastassia is among the first\u000ato leave the tables, pleading a headache. By midnight, the Great\u000aHall is deserted apart from a few servants clearing away the ruins\u000aof the feast and a cluster of crusty old Barons gathered around\u000aa brandy keg, loudly re-enacting various historical battles on an\u000aempty table using salt cellars, wine glasses, and pieces of fruit.'),'[]');
INSERT INTO module_events VALUES(168,4,'12 midnight',84,unistr('Albrecht''s thugs ( _Plot 4_ ) go to von Gient''s room, having bribed\u000aone of the servants to find out its location. There is a muffled yell\u000a(requiring a **Challenging (+0) Perception** Test to hear if close\u000aby), and then everything is quiet.\u000aThe two leave after some ten minutes, having stripped the room\u000aof all its valuables. They sneak out of the castle and head off\u000adownriver, where a boat waits to take them home to Marienburg.'),'[]');
INSERT INTO module_events VALUES(169,4,'12:15 a.m.',85,unistr('There is a commotion at the foot of the stairs leading to the solar\u000atower. Graf Wilhelm has staggered out and collapsed, dragging\u000aa suit of armor noisily to the floor. White-faced and gasping, he\u000astammers incoherently about a monster in his room. A rapid\u000asearch by the servants turns up no trace of an intruder.\u000aThe Graf has already failed a Psychology Test to resist **Terror 3** and has three _Broken_ Conditions; it is impossible to get any\u000asense out of him. The Characters can try to calm him in any of\u000athe normal ways, though the servants may misinterpret their\u000aintentions and try to ''protect'' him. Once calm, he claims he was\u000aawakened by a glowing, snarling figure with a rotting head and\u000agolden jewellery. The thing made no attempt to harm him, but\u000aseemed angry and spoke harshly in a foreign tongue.\u000aThe apparition was Inta-Dapesht, a Nehekharan Wraith ( _Plot 3_ ).\u000aIt was disturbed when its tomb was looted and the sword recently\u000aacquired by the graf was stolen. It has stayed close to the graf,\u000aseething with anger, but is taking advantage of its _Ethereal_ nature\u000ato hide in a nearby wall.\u000aOnce the graf gathers his wits, he shrilly demands the\u000aCharacters exorcise the Wraith, or otherwise make the sword\u000a''disappear''. He states that the blade cannot be allowed to fall\u000ainto the hands of the Ambossteins in this cursed state, for they\u000awill take any such gifts as an attempt to harm their family.\u000aHowever, he cannot arbitrarily deny the young bridegroom the\u000agift given he loves it so.\u000aThe spirit will then show itself again - along with its Terror 3 Trait\u000a- making the graf scream and faint. Unfortunately, Inta-Dapesht\u000aonly speaks the ancient language of Nehekhara. It is unlikely any\u000aof the Characters can speak Nehekharan, but a **Very Hard (−30) Language (Magick)** or **Language (Arabyan)** Test will allow a\u000aCharacter to pick out odd words here and there, and piece together\u000aenough of the message to understand. If Inta-Dapesht is attacked\u000aor otherwise offended - in other words, if the sword is not packed\u000aaway and shipped back to Nehekhara - it will attack. Otherwise,\u000ait will accompany the sword back to its tomb, punishing anyone\u000awho interferes or delays its return as it goes.'),'[]');
INSERT INTO module_events VALUES(170,4,'12:30 a.m.',86,unistr('There is a scream from von Gient''s room. A serving-maid, with\u000awhom he had made an assignation for the night, went to his\u000aroom and found that it had been thoroughly wrecked.\u000aVon Gient is dead, tied to the bed with signs of having been\u000aseverely beaten. Strangest of all, a fresh herring is wedged between\u000ahis teeth. A successful **Very Easy (+60) Lore (Marienburg)**\u000aTest, or a **Challenging (+0) Intelligence** Test ( **Easy (+40)** for\u000aracketeers; **Average (+20)** for Rogues), allows a Character to\u000arecognise the calling-card of the dreaded Marienburg crime lord,\u000aAlbrecht the Fish.'),'[]');
INSERT INTO module_events VALUES(171,4,'12:45 a.m.',87,unistr('Outside the von Saponatheim family apartments, servants\u000aintercept a young guest who appears to have lost his way. He\u000aseems too drunk to speak - unable even to give his name or the\u000aname of his family so that he can be directed to the right quarters.\u000aThis is Joachim Bitterfeld, the jeweller''s apprentice from\u000aAltdorf who is planning to elope with the Baroness Nastassia.\u000aHe has lost his way and is pretending to be drunk in the hope of\u000abeing left alone so he can keep looking for Nastassia''s room. A\u000asuccessful **Average (+20) Intuition** or **Consume Alcohol** Test\u000awill reveal that his drunkenness is feigned. Anyone who tries to\u000asearch him will find that he is wearing two sets of clothes -\u000aone set is a disguise for Nastassia so that they can sneak out of\u000athe castle together.\u000aIf left alone, Joachim will keep looking for Nastassia''s room.\u000aHe may cause disturbances from time to time as he goes into\u000awrong rooms in various parts of the castle. He can be used as\u000aa distraction or an added complication whenever and wherever\u000ayou choose.'),'[]');
INSERT INTO module_events VALUES(172,4,'1:00 a.m.',88,unistr('Many of the castle''s servants are drunk by now, having finished\u000aoff any partially empty cups and bottles they found while clearing\u000aaway the feast. Left alone in the cellars, Manfred ( _Plot 6_ ) has\u000amanaged to free himself. He bursts into the kitchens, breaking\u000athe necks of two servants before anyone knows what is happening.\u000aWith the strength of the desperate, he shrugs off all attempts to\u000astop him, making his way up to the main hall.'),'[]');
INSERT INTO module_events VALUES(173,4,'1:15 a.m.',89,unistr('Unless he is stopped, Manfred will go through the family\u000aapartments, into the solar tower, and up to the master bedroom\u000ato kill his father. What he lacks in mental acuity he more than\u000amakes up in physical strength and rage.\u000aStopping Manfred is a delicate matter. As a nobleman - despite\u000ahis condition - it is theoretically illegal for a member of the\u000alower orders to lay violent hands upon him. Graf Wilhelm may\u000aoverlook this if Manfred can be subdued quickly and quietly, and\u000areturned to the cellars before anyone outside the family learns\u000athe truth. If Manfred is wounded, there will be consequences:\u000aparadoxically, though, the consequences for killing Manfred may\u000abe less severe if no one outside the family learns that he ever\u000aexisted. His death, after all, solves a problem for the family by\u000aleaving Nastassia unchallenged as Graf Wilhelm''s heir. However,\u000aif Manfred''s existence becomes known, his killers will pay the\u000aprice for the family''s embarrassment as well as for killing him.'),'[]');
INSERT INTO module_events VALUES(174,4,'1:15 a.m.',90,unistr('Nastassia leaves her room to look for Joachim (see _12:45_\u000a_a.m._ ). If she encounters anyone along the way she pretends to\u000abe sleepwalking, and will not resist anyone who tries to wake\u000aher and conduct her back to her room. Instead, she waits a few\u000aminutes before leaving again in search of her secret lover.\u000aAnyone who enters her room after this time will find a note to\u000aher father propped up on her dressing table. The note explains\u000athat she has eloped with her true love rather than face this\u000aarranged marriage.'),'[]');
INSERT INTO module_events VALUES(175,4,'1:30 a.m.',91,unistr('Posing as a wedding guest, the Dammenblatz agent ( _Plot 1_ )\u000awent to another guest''s room (choose a guest of your own\u000acreation, preferably one with a connection to the Characters,\u000aor simply use a minor noble) to share a bottle of brandy or\u000aother nocturnal activity. The agent then quietly murders the\u000aother guest, and then sets out to take the body to the gravin''s\u000aroom. If encountered, the agent will pretend to be drunk:\u000ausing the Entertain (Acting) Skill as best as possible. The\u000aagent claims the other guest has drunk himself unconscious,\u000aquite dead to the world, and will accept help in getting him\u000aback to his room; if successful, the agent will wait 15 minutes\u000abefore trying again.\u000aWhen arriving at the gravin''s room, the agent breaks in quietly\u000aand administers Moonflower vapours ( **WFRP**, p, 306) from a\u000asmall fire-pot to make sure she stays asleep. The body is then\u000adumped by her bed, and a bloody dagger is left near her hand.\u000aThe agent then scatters pages from a scandalous pamphlet about\u000athe room. While the pamphlet claims to describe and illustrate\u000athe rites of ''THE PRINTS OF PLESHUR'', it is simple\u000apornography and contains no heretical (or useful) information.\u000aFinally, the agent rings for the gravin''s maid and hides under\u000athe bed while the maid discovers the body, planning to sneak\u000aout when the alarm is raised. If escape proves difficult, the agent\u000awill blend in with the crowd of guests and servants drawn by the\u000amaid''s screams.'),'[]');
INSERT INTO module_events VALUES(176,4,'1:45 a.m.',92,unistr('Unless prevented, Nastassia and Joachim find each other and slip\u000aoff into the closed wings so she can change into her disguise. This\u000aprocess takes about ten minutes, and then the two ''young nobles''\u000atry to sneak out of the castle.'),'[]');
INSERT INTO module_events VALUES(177,4,'2:00 a.m.',93,unistr('Six young nobles ( _Plot 5_ ) emerge from various guest rooms\u000aand make their way down to the wine cellar. If challenged, they\u000apretend to be helping themselves to more wine and brandy.'),'[]');
INSERT INTO module_events VALUES(178,4,'2:15 a.m.',94,unistr('Once in the cellars, the cultists bar the door from the inside\u000aand begin their profane ritual. If Kavenner is alive, he leads the\u000aritual. If Rechtshandler lives and is a Mutant, he cowers in the\u000acorner, sobbing over his sorry lot in life. A low chanting and\u000athe occasional moan and muffled scream may be heard through\u000athe cellar door if anyone listens carefully with an **Average (+20) Perception** Test.\u000aThe cultists are casting a spell that will summon a number of\u000aDaemonettes to the castle. Once the summoning is complete,\u000athe cultists unbar the cellar door and the Daemonettes rampage\u000athrough the castle in an orgy of destruction, pain, and worse. You\u000ashould decide how many Daemonettes are summoned according\u000ato the capability of the Characters: there should be enough to\u000aprovide a hard fight for the party and any allies it can muster,\u000abut not enough to ensure a one-sided slaughter. If matters look\u000alike they are getting out of hand, simply bring more of Graf\u000aWilhelm''s soldiers in to help.'),'[]');
INSERT INTO module_events VALUES(179,4,'2:15 a.m.',95,unistr('Four _taggee_ ( _Plot 7_ ) sneak out of the entertainers'' quarters and\u000ahead for Dowager-Duchess Clothilde''s rooms. They may be\u000aencountered anywhere you wish over the next 5-10 minutes as\u000athey attempt to locate their quarry. They are well-trained and\u000aextremely wary, and will avoid encounters when possible.\u000aAt about the same time, Graf Josef von Angendorf has made\u000ahis transformation into the notorious jewel thief, the Wraith. A\u000ablack-clad figure slips out of the window of Graf Josef''s guest\u000aroom and climbs around the outside of the castle towards the\u000adowager-duchess''s chambers.\u000aIf the _taggee_ recover the ruby, they kill the dowager-duchess as\u000aan act of retribution and stealthily leave the castle, stealing a boat\u000aand heading downstream.\u000aIf the Wraith steals the ruby before the _taggee_, they climb out\u000aof the window in pursuit of the thief. If the Characters become\u000ainvolved, this can lead to a dangerous but very entertaining\u000arunning battle on the castle''s walls and rooftops.\u000aRegardless of who steals the gem, Glimbrin will be waiting\u000afor them on the roof, and observes the escape. Begrudgingly,\u000aGlimbrin recognises he cannot hope to stop either party, so seeks\u000aout any of the Characters who have been sympathetic to him in\u000athe past. He explains the gem is stolen, and encourages them to\u000agive chase.\u000aIf the Characters manage to recover the stolen gem, Glimbrin\u000awill, in turn, attempt to steal it from them, or offer any number of\u000asmall trinkets - and even explosive devices if he was successful\u000ain his attempts during _A Night at the Opera_ - in exchange. If\u000apressed, and Glimbrin sees no way to recover the gem, he will\u000amake an impassioned speech about how the gem is the secret to\u000adefending his homelands from utter destruction. Of course, this\u000ais a lie.'),'[]');
INSERT INTO module_events VALUES(180,4,'Festag Morning',96,unistr('Assuming the castle isn''t in lockdown because of the daemonic\u000aattack, servants begin to stir around 5:00 a.m. Some head for the\u000akitchens to prepare the wedding breakfast; others head for the\u000arooms of their aristocratic charges, ready to wash and dress them\u000afor the great day.\u000aIn short order, screams of horror and cries of outrage are heard\u000afrom various parts of the castle as the results of the night''s events\u000aare discovered. This is an opportunity for you to involve the\u000aCharacters in any plot that has escaped their notice so far.\u000a**The Runaways**\u000aIf the bride and her paramour have managed to leave the castle,\u000aGravin Maria-Ulrike will send the Characters after them. _''This is_\u000a_a very delicate situation,''_ she explains. _''They must be recovered before_\u000a_word gets out. I don''t care what you have to do, whom you have to_\u000a_bribe, or how much - just make sure they are both back before the end_\u000a_of the day. I''ll do what I can to slow things down here - I''ll spread_\u000a_the word that she''s sick - but the wedding must go ahead. And don''t_\u000a_hurt the young man; it''s not his fault, really. Bring them both directly_\u000a_to me, and make sure no one else sees you.''_\u000aThe errant pair made their way to the river, intending to steal\u000aa small boat from the moorings downstream of the castle. They\u000aplanned to go downstream to Altdorf, where Joachim has a\u000apriestess of Shallya ready to marry them - although she does\u000anot know who Nastassia is, and the bride will be using a false\u000aname. From there, Joachim will collect his belongings from his\u000alodgings, having already taken leave of his master to begin life as\u000aa journeyman. He plans to set out for Marienburg with his new\u000abride, there to seek his fortune.\u000aYou can decide how far the pair''s plan has advanced. By dawn,\u000athey may be partway to Altdorf, but the adventurers will be able\u000ato catch them up in a few hours. Joachim is not a skilled sailor,\u000aand is unfamiliar with the stolen boat.\u000aAlternatively, the pair may have been delayed at the moorings as\u000aJoachim tried to find a suitable vessel to steal. They may have been\u000aspotted by a boatman or other guard, and since the custom of the\u000ariver is to string up boat thieves without trial, the adventurers\u000amay arrive just in time to save their lives. No one, after all, is\u000agoing to believe a young slip of a girl - dressed in men''s clothing,\u000ano less - when she is caught trying to steal a boat and tries to get\u000aout of trouble by claiming to be the young bride from the castle!\u000aIt would be quite the tragedy should the Characters arrive too\u000alate in such circumstances.\u000a**The Heir**\u000aEven if Manfred''s escape was contained and his existence\u000aremains a secret, the von Saponatheims - under some pressure\u000afrom their soon-to-be in-laws - have decided that he should be\u000asent away in secret, and housed under a false name in some place\u000afar, far away. Gravin Maria-Ulrike has arranged for her personal\u000aphysician to drug the heir to Schloss Grauenberg with a powerful\u000a# The Assassin\u000asedative, and orders the Characters to conduct him to the Great\u000aHospice of Shallya at Frederheim (just north of Altdorf), or\u000asome similar institution elsewhere in the Empire.\u000aThe journey can be as simple or as complicated as you wish.\u000aManfred''s constitution is unusually strong, and the drug may not\u000akeep him fully subdued. Some rivals of the von Saponatheims - or\u000aworse, an agent working for Baron von Dammenblatz or perhaps\u000athe Toppenheimers - might get hold of the rumour that the true\u000aheir to Saponatheim is being moved in secret, and complicate the\u000aadventurers'' lives still further. Even if all goes well, any long journey\u000ain the Empire is fraught with perils great and small, especially\u000awhen one is conveying an unwilling human cargo.\u000a**The Assassin**\u000aGravin Maria-Ulrike is in no doubt that von Dammenblatz was\u000abehind the attempt to frame her for murder in the night. If the\u000aassassin has not yet been captured, the Characters are sent to\u000afinish the job. _''Kill the Dammenblatz fool only if you have to,''_ she\u000aorders. _''Such creatures are far more valuable alive. If I can make the_\u000a_cretin name the Dammenblatz''s in court, I can turn the tables and put_\u000a_this wretched business to rest once and for all.''_\u000aEasy enough for a noblewoman to say, of course. Tracking and\u000acapturing a skilled assassin - especially one as talented as\u000aDominique Herveaux, if she still lives - is not simple, even\u000afor a seasoned group of adventurers. If they can succeed in their\u000amission, though, they will win the gravin''s undying gratitude\u000a- and her determination to keep them, and their dangerous\u000aknowledge, close to her for the rest of their lives.\u000a**The Cultists**\u000aThe followers of Slaanesh include the young and foolish scions\u000aof some prominent families (you can choose which according\u000ato the needs of your campaign), and Gravin Maria-Ulrike is\u000adetermined to detain and identify them all - without allowing\u000aword to reach the Witch Hunters (specifically the ever vigilant\u000aMatthias Hubkind, page 34, who may still be on her trail since\u000aNuln). Those from allied houses will be gently but firmly shown\u000athe error of their ways, and their misdeeds covered up; those from\u000arival houses will be turned into useful assets, providing social and\u000apolitical leverage against their families.\u000aA secondary objective - to the gravin, at least - will be to\u000aidentify other branches of the cult that seduced the young\u000anobles, and ensure two things: first, that its members are\u000apunished for compromising members of the nobility; and\u000asecond, that they are left in no condition to name the young\u000aaristocrats and embarrass them or their families in the future.\u000aA group of mercenaries, with no formal ties to any noble house,\u000amake a conveniently deniable instrument for such a task. This\u000acould even make an interesting side adventure if your Players\u000afancy playing different Characters for a while.\u000aIf either Kavenner or Rechtshandler were involved with the\u000asummoning, the gravin is swift and brutal in her pronouncement:\u000ashe wants them seized, burned, and buried. She then instructs\u000aher servants to erase any trace of evidence connecting her, or her\u000acousin the Countess, to either of them.\u000a**The Gem**\u000aIf Dowager-Duchess Clothilde of Telland survived the night, she\u000awill want her ruby back; if not, there will be widespread interest in\u000atracing both the gem and the venerable lady''s murderers. While\u000aGravin Maria-Ulrike has no great personal stake in the wellbeing of the Countess or the whereabouts of the gem, there is\u000aprestige to be gained for her house if she - or rather, her agents\u000a- can resolve the situation.\u000a_taggee_ are heading down the Reik to Marienburg, intending\u000aThe\u000ato take ship for Ind as soon as possible - unless the Wraith or\u000aGlimbrin stole the gem first, in which case they are hot on the\u000aculprit''s trail. Bringing a noble to trial for theft will be a tricky\u000abusiness, but if the Characters can lay convincing proof before\u000athe gravin, she will take the matter in hand. However, rather\u000athan having Graf Josef von Angendorf arrested, she will try to\u000aturn him into an unwilling accomplice, to be used under the\u000athreat of blackmail whenever the gravin needs to acquire an\u000aitem under less than legal circumstances. If the Characters are\u000ainstead trying to catch Glimbrin, they''ll have their work cut out\u000afor them, as this is the Gnome''s last caper before raiding his\u000astash of stolen goods, then heading back to the Mirror Moors\u000aand his home in Glimdwarrow.\u000a**CONCLUDING THE ADVENTURE Experience Point Awards**\u000aAs well as the usual awards for good roleplaying and bright ideas,\u000aXP should be awarded for the following:\u000a10-30 points for securing Nastassia for her wedding, or helping\u000aher escape with Joachim\u000a10-30 points for preventing the completion of the Chaos ritual\u000ain the cellar\u000a10 points for stopping the Slaanesh Daemons if the ritual is\u000aconcluded\u000a20 points for preventing the theft of Dowager-Duchess\u000aClothilde''s ruby\u000a20 points for dealing with the Nehekharan Wraith\u000a20 points for thwarting the Dammenblatz agent\u000a10 points for re-capturing Manfred\u000a10 points for stopping Albrecht''s thugs before they kill von Gient\u000aThere are many other opportunities for extra XP, including\u000aexcorting Manfred to a new home, finding the eloping couple,\u000aor hunting down and capturing the Dammenblatz agent. The\u000aappropriate awards for these are left in your hands depending\u000aupon how difficult you make it for the Characters.\u000a# Following the Campaign\u000a**What Next ? Following the Campaign**\u000aThe following day, the wedding will take place - or not.\u000aEverything depends on the events of the night.\u000aIf the bride and groom are still in the castle and the existence\u000aof Manfred von Saponatheim has been successfully covered up,\u000athe wedding takes place as planned. Observers may comment\u000aon Nastassia''s downcast demeanour, but this is not unusual\u000ain loveless noble marriages. Her father, on the other hand, is\u000ajubilant, as are the groom and his family. Another day of feasting\u000aand celebration follows, which can be played out in detail as you\u000aprefer. However, if the cursed sword is delivered to Baron KarlHeinz, the Wraith within materialises once more and causes a\u000acommotion that could easily destroy the newly built alliance -\u000aunless the Characters step in.\u000aIf all is not well, guests will depart on the morning of Festag,\u000astarting with the von Liebwitz contingent. The failure of the\u000awedding is an embarrassment to both houses, and a fiction is\u000aagreed upon to head off scandal and cover it up. Manfred is\u000apacked off to a distant hospice under a false name, accompanied\u000aby a generous donation to the Sisters of Shallya. Unless she\u000ahas escaped with her paramour, Nastassia is confined to her\u000arooms with a fictional illness until her parents can arrange\u000aanother match. To secure the cover-up, servants are bribed or\u000athreatened into silence, and noble guests tacitly agree, in the\u000away of the great and good, never to speak of the night -\u000aat least, for as long as they have nothing to gain by raking\u000aup scandal against the von Saponatheims at the next Black\u000aPowder Week in Nuln!\u000aGravin Maria-Ulrike''s next stop is Ubersreik, where another\u000apiece of political business awaits. Accompanied by the\u000aCharacters, she either a) travels upriver to Bögenhafen, where\u000ashe engages a caravan of carts and coaches to travel by road\u000aalong the fringes of the Reikwald; or b) travels downriver by\u000abarge to the River Blut, where she heads upstream to the River\u000aTahme, then eventually reaches the Vorbergland Canals. The\u000ajourney can be played out in detail, or you can skip ahead to the\u000aparty''s arrival in Ubersreik.\u000a**A Stand-Alone Adventure**\u000aIf the adventurers are not following the campaign, the plots\u000alisted above under _Festag Morning_ offer ways to continue this\u000aadventure. The adventurers could find themselves headed to\u000aAltdorf in pursuit of the fleeing lovers, Marienburg to investigate\u000aAlbrech the Fish, Frederheim with Manfred, Glimdwarrow to\u000acapture Glimdrin, the Lands of the Dead with the antique\u000asword and Inta-Dapesht in tow, or even Ind, to steal the Rose\u000aTiger once again! Or, if they wish to endear themselves further\u000ato Gravin Maria-Ulrike, the Characters might track down the\u000aassassin and provide her with a weapon to use against her rival,\u000athe Baron von Dammenblatz.\u000a**The Host**\u000aGraf Wilhelm has\u000abeen in control his\u000aentire life, so he\u000ahates that he\u000aneeds this wedding\u000afor the coin it will\u000asecure. He also hates\u000athat his little girl\u000awill be marrying\u000aa sniveling little\u000aWissenlander!\u000aBut, it was\u000aorganised by his father,\u000aSo, he frowns through all\u000athe proceedings, drinking\u000aheavily from the stock of\u000aAmbossteins. That makes\u000aall the foreigners in his\u000acourt almost tolerable.'),'[]');
INSERT INTO module_events VALUES(181,5,'7:00 p.m.',97,unistr('Unfortunately, since the removal of House Jungfreud from\u000aUbersreik, the Bruners have gone a little wild, and dark rumours\u000anow circulate concerning their most prominent members, with\u000asome even suggesting there may be Chaos taint in the family\u000a(for more on this, see **A Guide to Ubersreik** in the **WFRP Starter Set** ).\u000aSo, Baron Rickard Aschaffenberg is trying hard to distance\u000ahimself from any scandal and put his family back in the running.\u000aIn turn, the enormously rich Lord Heinrich von Bruner is trying\u000ato rebuild his House''s reputation, and resents the Aschaffenbergs''\u000alack of support. It''s only made worse when Baron Rickard''s\u000anephew Maximilian misses no opportunity for a joke at House\u000aBruner''s expense. In this highly-charged political environment,\u000atempers are at breaking point.\u000a**Events**\u000aSet out below is roughly what will happen during the evening,\u000asubject to the influence of the PCs, and to whatever tweaks,\u000achanges, and additional events you decide to throw in. The more,\u000athe merrier!'),'[]');
INSERT INTO module_events VALUES(182,5,'7:00 p.m.',98,unistr('Lord Erich''s masquerade starts at 7:00 p.m. If the Characters\u000aare in his employ, they will be tasked to help him prepare for\u000athe guests, and to look out for plotters seeking to damage his\u000agood name.\u000aThe gravin arrives at the party first with her staff. With her is\u000aMercinellin ''Seedling'' Thorncobble XIII, who has been hired\u000aby the gravin to perform card tricks and engage the guests in\u000aidle gambling and games (use the **Pub Games** on page 91),\u000awhilst gathering information - the Halfling and her refined\u000aways fit well with the surroundings. If the Characters are with\u000athe gravin, she charges them to watch out for useful scandal and\u000afor the meddling of her rivals, and instructs them to co-ordinate\u000awith Seedling.\u000aSoon after, Captain Pfeffer and Captain Blucher arrive\u000atogether. Hot on their heels comes Burgomeister Ernst Maler.\u000aBorgun Foambeard follows, invited largely because Lord Erich\u000awanted the Dwarf to supply the party with his quality beers.\u000aFoambeard heads straight for the dining room to ensure his\u000astock is handled correctly by the servants and the two Dwarfs\u000ahe sent to act as barmen. Baron Heinrich von Falkenhayn and\u000ahis staff arrive soon after.\u000aThe Watch captain and garrison commander are dressed for a\u000aparty in the blue and yellow colours of Ubersreik, but refuse to\u000awear masks; they are both noble, and have attended their share\u000aof these soirees, but they are not natural politicians, and neither\u000alooks comfortable. Maler wears a trout-head mask as a tribute to\u000athe town''s dependence on the river, which he is happy to explain,\u000aat length, to anyone, repeatedly. Borgun wears a helmet out of\u000arespect for his host, but finds the idea of a costume ridiculous.\u000aFalkenhayn wears a mask with the face of a falcon, in reference to\u000ahis family crest. Lord Erich, the host, is costumed as a woodcutter,\u000aa play on his family name, and welcomes everyone with an easy\u000asmile accompanying his stiff Reiklander hand-shakes and a single\u000akiss to the left cheek.\u000aLastly, General Jendrick von Dabernick arrives in full military\u000aregalia, wearing a twin-tailed comet mask. He is guarded by a\u000aKnights Panther who says nothing and keeps ''his'' helmet down.\u000aThe knight is actually Lady Emmanuelle Nacht, a representative\u000aof the Emperor, and currently the true power in Ubersreik ( _Plot_\u000a_1_\u000a). The general will be plagued for most of the evening by nobles\u000awho believe he has the ear of the Emperor. He hasn''t, but is happy\u000ato be thought of as important, and loudly boasts of his many\u000aimportant deeds.'),'[]');
INSERT INTO module_events VALUES(183,5,'7:15 p.m.',99,unistr('Lord Heinrich von Bruner is announced. He is attending with\u000aLady Galina of House Hohengolfrid, a noted philanthropist\u000awith strong connections to the cult of Sigmar, and certainly not\u000asomeone to associate with dark cultists ( _Plot 7_ ). The fact Heinrich\u000ahas donated a significant amount of gold to Lady Galina''s latest\u000arelief project in the Widow''s Vale is, of course, never mentioned.\u000aHeinrich is dressed in blue and black, his family''s colours, and\u000ahis mask is a full-face boar''s head, taken from the family''s coat\u000aof arms. Lady Galina wears yellow and pink with a stylised\u000amasquerade mask.\u000aBaron Rickard Aschaffenberg arrives a minute later. Rickard is\u000adressed in a black and gold tunic, which is cunningly sewn to look\u000alike chain mail, and has a golden fox-fur about his shoulders and\u000aa mask fashioned like the visor of a helmet. If the Characters are\u000aworking for him, they will already be briefed to watch out for the\u000aschemes of the other Noble Houses, and to do everything in their\u000apower to protect the good Aschaffenberg name.\u000aHeinrich and Rickard avoid each other until Lord Maximilian\u000aAschaffenberg is announced some five minutes later. Maximilian\u000ais Rickard''s nephew and has long hated the Bruners, and not\u000ajust because Bruner Palace is significantly larger Aschaffenberg\u000aManor. He is dressed in black and blue Bruner colours, with a\u000afake tentacle of stuffed and painted cloth protruding from one\u000ashoulder and a brightly coloured mutant mask. Angry words are\u000aimmediately exchanged as Lord Heinrich takes exception to this\u000aoutrage. If the Characters are hired by the Aschaffenbergs, their\u000acause will suffer unless Maximilian can be persuaded to leave,\u000aand possibly return in a more suitable costume. Not only are the\u000aBruners enormously rich and influential, and it is just unseemly\u000ato air problems in such a fashion.'),'[]');
INSERT INTO module_events VALUES(184,5,'7:30 p.m.',100,unistr('Lord Siegfried von Saponatheim is announced as he arrives\u000aalongside his staff. He wears a stag mask with magnificent\u000aantlers, and tells anyone who will listen how he shot the stag\u000ahimself. If Siegfried is employing the Characters, he tasks them\u000ato undermine his rivals in any way they can.'),'[]');
INSERT INTO module_events VALUES(185,5,'7:45 p.m.',101,unistr('As Siegfried is greeted by Erich, a Dwarf emerges from the\u000akitchen and speaks urgently with Borgun Foambeard. A\u000asuccessful **Hard (−20) Perception** Test allows a PC to overhear\u000athat a cart bringing more ale had a run-in with some kind of ratheaded Mutant, but the Dwarfs drove it away and it disappeared\u000ainto the shadows.\u000aBorgun speaks briefly with Captains Blucher and Pfeffer,\u000aafter which Captain Pfeffer exchanges a word with one of her\u000aWatchmen outside the mansion, sending him to the Watch\u000aBarracks with a message to tighten security in the town.'),'[]');
INSERT INTO module_events VALUES(186,5,'7:45 p.m.',102,unistr('Lord Florian Pfeifaucher and Christoph Engel arrive together, a\u000alittle drunk and laughing uproariously. Florian is dressed in leaves\u000aand claims to be a ''fertility spirit'', using his costume as an excuse\u000ato pester attractive female guests. Engel wears a robe, hat, and\u000athick grey scarfs, and could hardly look more like a Grey Wizard\u000aif he tried.\u000aWhile talking to Baron Rickard, Lord Siegfried tries to slip\u000aa powerful emetic into his drink. Any Characters in the room\u000awill spot him by winning an **Opposed Perception/Sleight of Hand** Test.\u000aIf nothing is done, within ten minutes Baron Rickard will burp\u000aloudly, groan, then be violently sick, vomiting over anyone in\u000aconversation with him. He then collapses, pale, shivering, and\u000avery ill. A couple of servants will carry him back to Aschaffenberg\u000aManor, and everyone will assume that he drank too much - a\u000adisgrace so early in the evening. If the Characters expose Lord\u000aSiegfried''s actions, he will be ejected from the ball in disgrace.'),'[]');
INSERT INTO module_events VALUES(187,5,'8:00 p.m.',103,unistr('Father Gunther Emming of the High Temple of Sigmar is\u000aannounced, accompanied by petite Sister Celestine Hoch of\u000athe Temple of Shallya. She has come in place of high priestess\u000aMarianne Altenblum, who is busy tending a sick family. The\u000apriest of Sigmar is dressed in his robes and has no mask: in his\u000aview, disguise is deception and deception is a tool of Chaos.\u000aCelestine is dressed as the goddess herself, in flowing white robes.\u000aChristoph Engel and Florian Pfeifraucher whisper conspiratorially\u000afor a moment, then collapse against each other in a paroxysm of\u000asuppressed laughter. With almost theatrical nonchalance they\u000aturn away to look at a painting on the wall - and suddenly\u000aboth Emming and Celestine cry out in dismay. Somehow, they\u000aare wearing each other''s clothes. A crowd gathers round the\u000aembarrassed pair, laughing and pointing until they can make their\u000away to the powder room to change back into their proper clothing.\u000aEngel was very subtle about his spellcasting: someone who was\u000awatching him and Pfeifraucher closely will see the spell being cast\u000aon a successful **Very Hard (−30) Intuition** Test.\u000aThe watchman sent out by Captain Pfeffer at 7:30 returns to the\u000amansion and resumes his post.'),'[]');
INSERT INTO module_events VALUES(188,5,'8:15 p.m.',104,unistr('Doctor Otto Krupp arrives. He wears a long black cloak, a\u000abroad-brimmed hat, and the mask he used while treating an\u000aoutbreak of plague several years ago. The mask has a long beak\u000afor a nose, which plague doctors fill with herbs to ward off\u000a''unhealthful vapours''.\u000aIf Maximilian Aschaffenberg is still at the party, he starts to throw\u000ainsults at Heinrich von Bruner, claiming the Bruners are tainted\u000aand fallen. Heinrich doesn''t hold his temper well, and eventually\u000alashes out. If the Characters do nothing, the two fight, their staff\u000ajoining in, until all are separated by Lord Erich''s guards. Lord\u000aMaximilian is sent home, and the Aschaffenberg family is deeply\u000aembarrassed. If the Characters stop the brawl and persuade\u000aMaximilian to apologise, he is allowed to stay.\u000aWhile Lord Erich is distracted by the brawl, Lord Siegfried\u000avon Saponatheim tries to slip a dose of his emetic powder into\u000ahis drink. Anyone who is watching Lord Siegfried will notice\u000athis with a successful **Opposed Perception/Sleight of Hand**\u000aTest. If Lord Erich drinks from the poisoned cup, he will be\u000aviolently sick within ten minutes - quite possibly onto one of\u000ahis other guests.'),'[]');
INSERT INTO module_events VALUES(189,5,'8:30 p.m.',105,unistr('The Baron de Grenouille arrives, arrayed in silk and cloth-ofgold as an armoured Bretonnian knight - complete with a small\u000amodel horse around his waist. His costume is greeted by muffled\u000agasps and a few chuckles.\u000aMore barely restrained chuckles greet the arrival of Father\u000aHeinrich Gutenberg of the Temple of Verena a minute later. The\u000atall priest of Verena has made the devout but bizarre decision\u000ato dress as Verena herself, in classical robes with a helmet, a\u000ablindfold, and a pair of scales. A stuffed owl perches unsteadily on\u000aone shoulder, and his hairy chest contrasts starkly with his lowcut gown. He seemingly sees nothing peculiar about his choice of\u000acostume, reacting to any off-colour jokes with polite puzzlement\u000aand a gentle smile.\u000aFather Gunther Emming, the priest of Sigmar, tries to draw\u000aGravin Maria-Ulrike into a theological discussion to test her\u000afaith - and therefore, her family''s suitability to rule Ubersreik.\u000aAlthough she is more than a match for his interrogation, she\u000awill signal the Characters - if they are working for her - to\u000aextricate her from the conversation without causing offence, as\u000ashe finds the man instantly tedious.\u000aAt this point, heads turn at an offended outcry from the reception\u000aroom. There, Florian Pfeifraucher is ''charming'' the young priestess\u000aof Shallya, Sister Celestine Hoch. He drunkenly claims to ''love\u000athe poor'' as the diminutive woman attempts to push him away.\u000aIf the Characters do not intervene, Florian will be thrown out by\u000aLord Erich''s guards, which will likely embarrass the gravin, who\u000athe Pfiefrachers support, even though she has no connection to\u000ahim at all.\u000a# Heinrich, Heinrich, or Heinrich?'),'[]');
INSERT INTO module_events VALUES(190,5,'8:45 p.m.',106,unistr('Lorith Silverleaf is announced. There are gasps at her alien beauty\u000aand the magnificence of her elaborate dress and intricate mask.\u000aAs attention is diverted to the Elf, Christoph Engel animates the\u000afox-fur stole of a lady guest in the gallery (or perhaps on Baron\u000aRickart if he is still at the party). A large man screams as it drops\u000ato the floor, thrashing wildly but unable to move since it lacks a\u000askeleton below the neck. Any successful attack will kill it: a failed\u000aattack still kills it but the attacker suffers 1 Wound in the process\u000aas the fox somehow managed to bite the attacker.'),'[]');
INSERT INTO module_events VALUES(191,5,'9:00 p.m.',107,unistr('Visible to anyone in the yard on a successful **Opposed Perception/Stealth** Test, a Gutter Runner emerges from\u000athe well at the back of the mansion. If not stopped, it creeps\u000ato a stack of barrels (recently brought by the Dwarfs), pulls a\u000acloth bag from inside its clothing, and pours some greenish,\u000aslightly luminous powder into each barrel. It then sneaks\u000aback down the well; if the PCs give chase it will collapse\u000athe tunnel through which it entered, making pursuit\u000aimpossible. Anyone who drinks from a contaminated\u000abarrel will begin to show mutations about half an hour\u000alater ( _Plot 6_ ).\u000aIf he is still at the ball, Florian Pfeifraucher begins to show\u000aunwelcome attention toward Gravin Maria-Ulrike. Her servants\u000a- and any Characters who care to become involved - try to\u000afend the drunken young noble off, with varying degrees of\u000asuccess. Another guest - a minor noble whose name no one\u000acan remember - helps the gravin to her feet, but an **Opposed Perception/Sleight of Hand** allows onlookers to see the noble\u000ajab the gravin with a fine needle protruding from\u000athe ring. The ''noble'' is an assassin hired by the von\u000aDammenblatz family. Gravin Maria-Ulrike has just\u000abeen dosed with Black Lotus ( **WFRP**,\u000ap. 306). The\u000aCharacters must act quickly if they wish to save her life.\u000aIf Florian has already been ejected from the ball, the assassin\u000awill choose another moment to strike, when the gravin and her\u000aattendants are distracted by some other event. Whenever the\u000aassassination attempt occurs, if it is unsuccessful, Baron Eberhadt\u000avon Dammenblatz is informed of the situation through his allies at\u000athe party, and makes ready to confront the gravin personally.'),'[]');
INSERT INTO module_events VALUES(192,5,'9:15 p.m.',108,unistr('Netta Volkmann and Doktor Krupp steal away from the ball,\u000aheading upstairs in search of an unoccupied bedroom. Thorncobble\u000ahas learned of their affair, and points out the retreating doctor\u000aand his paramour to the gravin and the Characters, assuming\u000athey are working together.\u000aAs they slip away, Father Gunther and Father Heinrich get into a\u000aheated debate concerning a recent incident where a witch hunter\u000awas refused access to the library at the Temple of Shallya. Voices\u000aare raised and the two priests look ready to come to blows. If\u000athe Characters defuse the situation, Lady Nacht notices, and\u000awhichever noble House employs them benefits. If the Characters\u000ado nothing, Lord Erich''s guards resolve the issue.'),'[]');
INSERT INTO module_events VALUES(193,5,'9:30 p.m.',109,unistr('A late-arriving guest dressed as a wild, bearded Sigmarite\u000aflagellant turns out to be a real flagellant. He stares at the\u000acostumes for a moment, and then attacks with a howl of fury. The\u000aflagellant is unarmoured but has a short, multi-thonged whip that\u000acounts as a hand weapon. If the Characters take no action, guards\u000aand servants move to restrain the flagellant in short order. If the\u000aCharacters can restrain the wild Sigmarite without wounding\u000ahim, Lady Nacht notices and notes it for future. Observant'),'[]');
INSERT INTO module_events VALUES(194,5,'9:45 p.m.',110,unistr('He rants and raves about how the gravin constantly escapes his\u000ajustice, and that surely Sigmar Himself has set her as a test. The\u000agravin takes faux-pity on the man, gives him a handful of alms,\u000aand has him quickly removed from the party as Hubkind hollers\u000aon about witches and cultists in their midst. The gravin then\u000aquietly instructs the Characters, if they are working for her, to\u000amake sure the man doesn''t return.'),'[]');
INSERT INTO module_events VALUES(195,5,'9:45 p.m.',111,unistr('If Florian Pfeifraucher is still at the party, there is a scuffle in the\u000areception room and heads turn to see him twitching on the floor.\u000aLorith Silverleaf stands over him, calmly adjusting her clothing.\u000aShe explains that Florian became ''too familiar'' and ''needed to\u000abe taught a lesson''. Florian is shaken but not injured, though\u000ahe drunkenly claims that he was only being friendly and the elf\u000awoman tried to kill him.\u000aIf this story reaches the ears of Lord Erich, Florian is ejected\u000afrom the ball. If the Characters act immediately and persuade\u000aFlorian to apologise to Lorith and leave, they will prevent any\u000aembarrassment to the gravin.'),'[]');
INSERT INTO module_events VALUES(196,5,'10:00 p.m.',112,unistr('Acting upon a secret signal from Lady Nacht, Christoph Engel\u000aanimates the stuffed boar in the lobby, which attacks the nearest\u000aguest until it is destroyed. It uses the profile of a living Boar\u000a( **WFRP**, p. 314). Nacht wishes to see how the various groups at\u000athe masquerade deal with adversity. The Boar is actually an illusion,\u000aand all Wounds it inflicts will disappear after a few minutes.\u000aAs soon as the Boar is destroyed, the company''s attention is drawn\u000aby raised voices from the vestibule. The footman posted at the door\u000ais trying to restrain an ill-dressed young woman, who clutches a\u000aragged child to her bosom. She struggles with the servant and\u000aone of the watchmen repeatedly calls out for Lord Erich to come\u000aand acknowledge his son. This incident was arranged by Gravin\u000aMaria-Ulrike to embarrass her host: the young woman was a von\u000aHolzenauer servant, seduced by the young noble and dismissed\u000awhen her pregnancy became known. This is not uncommon among\u000athe nobility of all nations and all ages: however, in the Reikland a\u000anoble father is expected to make secret provisions for the welfare\u000aof any illegitimate children and their mothers - dependent, of\u000acourse, on their keeping quiet. But by simply casting this woman\u000aoff, Lord Erich has breached an unwritten code.\u000aLord Erich instructs his servants to get rid of the woman and\u000aher child as quickly and quietly as possible, while Gravin MariaUlrike will insist that she be given a fair hearing. A battle of wits\u000aand social standing will follow between the two nobles and their\u000arespective servants, masked by the appearance of charity and\u000apolite concern, but as savage beneath the surface as any pit fight.'),'[]');
INSERT INTO module_events VALUES(197,5,'10:15 p.m.',113,unistr('A Skaven Gutter Runner scales the wall nearest the kitchen and\u000aclimbs to the roof, blocking the chimney with a wad of rags.\u000aMinutes later, black smoke billows out of the kitchen, driving the\u000acooks coughing and spluttering into the yard. Once the kitchen is\u000aclear of people, the Skaven sneaks in and mixes Warpstone into\u000aall the spices being used to prepare the food, mull the wine, and\u000amix the punch. Then it escapes over the wall. Unless the Skaven is\u000astopped, or the contaminated spices are kept aside, mutations will\u000astart to break out within half an hour amongst any who consume\u000athe tainted goods. If spotted, the Skaven will flee, heading for the\u000acity walls. It will not return to its master for fear of being followed.\u000aIf the gravin is not serving the interests of House Saponatheim,\u000aunder cover of the disturbance, Lord Siegfried von Saponatheim\u000atries to approach the gravin and dose her wine-glass with some of\u000ahis emetic powder. As before, the Characters can spot this with a\u000asuccessful **Opposed Perception/Sleight of Hand** Test.'),'[]');
INSERT INTO module_events VALUES(198,5,'10:30 p.m.',114,'','[]');
INSERT INTO module_events VALUES(199,5,'10:30 p.m.',115,unistr('Lord Siegfried von Saponatheim uses more of his emetic powder\u000ato dose the food at the buffet table. This can be spotted by any\u000anearby Character with the same an **Opposed Perception/Sleight of Hand** Test as before. Anyone who consumes the tainted food\u000awill become violently ill within ten minutes (unless mutations\u000ahave already started breaking out) and the ball will come to an\u000aabrupt end. Should this happen, Lord Erich will have failed in\u000ahis attempts to impress the townsfolk and the von Holzenauer\u000acause ends in embarrassment. If the Characters expose Lord\u000aSiegfried, he is thrown out in disgrace and the von Saponatheim\u000acause is also finished.\u000aWhile Lord Siegfried is carrying out his plan, another one is\u000aunfolding in the reception room. Lord Erich''s agents somehow\u000amanaged to lay their hands on Manfred von Saponatheim, the\u000atrue legal heir to the Duchy of Saponathiem (see ''Nastassia''s\u000aWedding'' _, Plot 6_, page 58). Depending on how much time has\u000aelapsed between the wedding and the ball, and whether or not\u000athe Characters were charged with seeing Manfred safely to\u000aFrederheim, von Holzenauer''s agents either freed him from the\u000ahospice or intercepted the party conveying him there. Cleaned\u000aup, dressed in von Saponatheim colours, and given a light dose\u000aof some calming drugs, Manfred struts urgently from noble to\u000anoble, telling everyone that he is the von Saponatheim heir, his\u000afamily is cheating him, and his sister Nastassia is a fraud. Some\u000aof the guests whisper about the stunning resemblance between\u000athe man and Graf Wilhelm von Saponatheim, lending his\u000aargument credence. While this is certainly embarrassing for\u000athe von Saponatheim cause (and possibly for Gravin MariaUlrike as well), this incident is also charged with pathos as\u000athe earnest but unsuited Manfred desperately pleads his case\u000ato one guest after another, and begs them to help him regain\u000ahis birthright.'),'[]');
INSERT INTO module_events VALUES(200,5,'10:45 p.m.',116,unistr('Sick of anti-Bretonnian jokes from various young nobles, the\u000aBaron de Grenouille challenges one of them to a duel. The two\u000ago out into the garden and fight with swords as a cheering crowd\u000alooks on. The duc refuses to take off his costume, which makes\u000athe duel rather an odd sight.\u000aIf the Characters do not intervene, the duc wounds the young\u000anoble lightly in one arm. Honour is satisfied and the ball resumes.\u000aIf the Characters try to stop the duel, the noble onlookers object\u000avociferously, calling them spoilsports and urging them not to\u000ainterfere in a matter of honour.'),'[]');
INSERT INTO module_events VALUES(201,5,'11:00 p.m.',117,unistr('While Baron Rickard Aschaffenberg is in conversation\u000awith Father Gunther, one of his rivals (Lord Siegfried von\u000aSaponatheim or Lord Erich von Holzenauer, depending upon\u000awho remains at the party) joins them and tries to twist Baron\u000aRickard''s words so that he will embarrass himself in front of the\u000apriest of Sigmar.\u000aThe Characters can join the conversation on one side or the\u000aother, using appropriate Skills. Depending on the outcome of the\u000aconversation, either the Aschaffenbergs or the family of the other\u000anoble will be embarrassed.'),'[]');
INSERT INTO module_events VALUES(202,5,'11:15 p.m.',118,unistr('Lord Erich stands close by his main remaining rival, deep in\u000aconversation. On a successful **Perception** Test, the Characters see\u000ahim slip something into his rival''s clothing. The other does not\u000anotice, but if the Characters intervene - or if the noble pulls out\u000ahis or her handkerchief, causing the object to fall to the ground\u000a- it is found to be a note wrapped around a playing card.\u000aThe playing card bears an unspeakably disgusting image that\u000awill be easily identified by any Witch Hunter as a reference to\u000aSlaanesh, the Chaos God of Depravity. The note reads as follows:\u000a**Handout**\u000aLord Erich is trying to frame one or more of his rivals as members\u000aof a secret Chaos cult. The resulting scandal will lead to witch\u000ahunters investigating both families, leaving the von Holzenauers\u000aas perfect candidates for the lordship of Ubersreik.\u000aIf the Characters challenge Lord Erich and expose his guilt, the\u000avon Holzenauers will be investigated instead, and their claim to\u000aUbersreik will be finished.'),'[]');
INSERT INTO module_events VALUES(203,5,'11:30 p.m.',119,unistr('A Skaven Gutter Runner murders a young noble in the garden\u000a(Florian Pfeifraucher or Baron Heinrich von Falkenhayn are\u000aboth good candidates, or another noble of your choice) and hides\u000athe body under a bush. The Skaven then sneaks into the house\u000adressed in the victim''s ill-fitting costume, with a hood over its\u000ahead. It then tries to dump a pouch of powdered Warpstone\u000ainto the punch bowl. An Opposed **Perception/Stealth** Test is\u000arequired to notice anything unusual about this partygoer; most\u000aof the other guests pay no attention, being somewhat drunk and\u000ainvolved in their own business. Unless the Skaven is stopped or\u000athe spiked punch is thrown away, mutations will start to break\u000awithin half an hour.\u000aCharacters searching the garden will be able to find the body of\u000athe murdered guest on a successful **Perception** Test.'),'[]');
INSERT INTO module_events VALUES(204,5,'11:45 p.m.',120,unistr('If the Gutter Runner is stopped inside the mansion, it throws\u000aa smoke bomb to cover its escape. If it is cornered and cannot\u000aescape, it will fight to the death.'),'[]');
INSERT INTO module_events VALUES(205,5,'11:45 p.m.',121,unistr('The sounds of a fight are heard from upstairs. Volker Volkmann,\u000aNetta''s husband, has surprised her and Doktor Krupp. His hands\u000aare locked about the physician''s throat as she stands by screaming\u000afor him to stop.\u000aIf the Characters intervene and resolve the situation without\u000abloodshed, Lady Nacht notes this, and the noble House\u000aemploying them will benefit.'),'[]');
INSERT INTO module_events VALUES(206,5,'Midnight',122,unistr('If the PCs have not yet found the body on the garden (see 11:30\u000aabove), there is a shout from outside as another guest does so. If\u000athe party has not yet been disrupted by an outbreak of mutations,\u000aan assistant cook staggers in from the kitchen, clutching his\u000athroat with a hand that grows furrier and more wickedly clawed\u000abefore the company''s eyes. Guests flee in terror and dismay: no\u000aone will ever forget this ball or its dreadful aftermath.\u000aIf questioned, the servant will admit to sampling some ale from\u000aa new barrel about ten minutes ago. Depending on how cruel\u000ayou are feeling, the barrel may not yet have been put out for the\u000aguests, and mutations are restricted to a handful of kitchen staff\u000a- or it may have been sitting on the bar in the dining room for\u000athe last five minutes, exposing everyone who drank from it to the\u000aWarpstone it contains.\u000aNo matter the case, the breakout of mutation ends the masquerade\u000ain panicked embarrassment as witch hunters, the Cult of Sigmar,\u000aand the Watch are summoned to investigate what happened.\u000aIf the gravin remains alive, and Baron Eberhardt von Dammenblatz,\u000adrunken and enraged, confronts her and the Characters as they\u000aleave the party. He is armed with a pistol, and demands immediate\u000asatisfaction over the death of his father. He demands the gravin\u000aduel him, though she steadfastly refuses. This confrontation draws\u000aa crowd of other nobles who all denounce Dammenblatz, though\u000a**CONCLUDING THE ADVENTURE So , Who Wins ?**\u000aThere is a high chance the ball ends in confusion, amid a Skaven\u000aattack and an outbreak of mutation. All thoughts of the lordship\u000aof Ubersreik are set aside as the townsfolk and the visiting\u000anobles fight the crisis as best they can. After the dust has settled,\u000ait is unlikely Lady Nacht recommends any of the gathered noble\u000aHouses to take Ubersreik''s title. However, if the Characters did\u000avery well, Nacht will notice this, and will hire the party herself\u000ain future. If one of the nobles fairs particularly well during the\u000acourse of the ball, you may feel Nacht conveys this to Altdorf.\u000aUnfortunately, the Emperor has other problems, and will not act\u000aon any communiqués sent his way. For more on what''s happening\u000awith the Emperor, refer to **The Enemy Within Campaign** .\u000a**Experience Point Awards**\u000aAs well as the usual awards for good roleplaying and bright ideas,\u000aXP should be awarded for the following:\u000a10-20 points per incident for advancing the interests of the\u000aCharacters'' noble House\u000a10-20 points per incident for thwarting an attempt to embarrass\u000athe Characters'' noble House\u000a10-20 points per incident for embarrassing a rival family\u000a10 points each for ''killing'' the ''fur stole'' and the ''stuffed boar''\u000a20 points for subduing Mattais Hubkind (+10 if he is not\u000awounded)\u000a30 points for thwarting each Skaven plot\u000a30 points for killing a Skaven.\u000a**What Next ?**\u000aThe end of the ball leaves two matters to be resolved: the lordship of\u000aUbersreik and what to do about the Skaven. Even a family whose\u000acause is lost will be able to put themselves back in contention - if\u000athey can locate and wipe out this threat beneath the city.\u000aGravin Maria-Ulrike is in a strong position, as she likely has a\u000agroup of adventurers already in her employ. She will send the\u000aCharacters to deal with the ''foul Beastmen'' right away as her rivals\u000ascramble to hire skilled rat catchers, sewer jacks, mercenaries, and\u000aother professionals from the town. If the PCs are on good terms\u000awith Captain Erwin Blucher of the local State Army garrison\u000aand Captain Andrea Pfeffer of the Watch, they may be able to\u000acount on a handful of Watchmen as extra muscle.\u000aTracking the Skaven is challenging but not impossible. The\u000acollapsed tunnel from the well leads into the sewers, and\u000atracks might also be picked up from the points where the\u000aDwarfs defended their beer cart ( _7:30 p.m._ ), where a Skaven\u000aclimbed the wall to block the kitchen chimney ( _10:15 p.m._ ), or\u000awhere a Skaven ambushed a guest in the garden ( _11:30 p.m._ ).\u000a# Following the Campaign\u000aThe trail leads to a small underground lair containing enough\u000aSkaven to present a reasonable challenge - 1 per Character\u000awill do - and a fearsome Rat Ogre ( **WFRP**, page 337) with\u000awhatever optional Traits and Skills you feel appropriate to test\u000ayour group. The Grey Seer commanding them, Rasknitt, is longgone (see page 41 of **A Guide to Ubersreik** for more on a group\u000avery interested in tracking that ratman).\u000aThe Skaven lair hides the now abandoned laboratory of Grey\u000aSeer Rasknitt. A pair of pitted and rotten workbenches are loaded\u000awith twisted pipes, glass chambers, and spluttering pots that were\u000aonce used for the Grey Seer''s experiments with warpstone. Any\u000aCharacter with a Channelling Skill senses the wrongness of the\u000aplace, and any with the _Second Sight_ Talent will immediately\u000aknow the place is irrevocably tainted, and will need to be burned.\u000aAny Character dawdling in the area for more than Toughness\u000aBonus Rounds is exposed to a Minor Corrupting Influence; any\u000aCharacter foolish enough to touch the laboratory equipment is\u000aexposed to a Moderate Corrupting Influence for every minute of\u000acontact, or part therof.\u000aAny evidence the Characters recover is confiscated by witch\u000ahunters and the party closely questioned. Their interrogators\u000awill try to extract as much information as possible while\u000asimultaneously convincing the Characters that they encountered\u000anothing more than a group of Beastmen that had somehow\u000afound its way into the town''s sewers.\u000aFortunately, throughout the evening it is likely that Lady\u000aEmmanuelle Nacht - in her disguise - observed the Characters\u000aperforming competently and with initiative. She has made note\u000aof them, and files their names away for future work if required.\u000aLady Nacht is always looking for valuable, yet expendable, assets\u000ato further her goals in Ubersreik.\u000a**Following the Campaign**\u000aAlthough this adventure concludes the **Rough Nights & Hard Days** campaign, you should feel free to devise more adventures\u000aif the Characterss remain in service with Gravin Maria-Ulrike.\u000aShe may lend their services to her aunt, Countess Emmanuelle of\u000aNuln, for all manner of sensitive missions, or she may decide to\u000ahave them aid her attempts to win Ubersreik, either for her own\u000afamily or for the von Saponatheims, and that could involve all\u000amanner of politics and skullduggery.\u000aAlternatively, if the Characters have impressed Lady Nacht,\u000atheir fortunates could change completely. Unknown to many,\u000ashe currently rules Ubersreik in the Emperor''s stead, and she\u000aneeds capable outsiders who she can trust to handle difficult\u000asituations. She could reach out to the Characters with a new\u000aoffer of employment and adventure. A good starting point for\u000athis is **Ubersreik Adventures: Heart of Glass**, which has the\u000aCharacters employed by Nacht to solve a politically sensitive\u000amurder. Nacht is also keen to track down the ''Beastman menace''\u000athat had somehow infiltrated the sewers, and the Characters may\u000abe a natural choice to pursue such a matter.\u000a**NON-PLAYER CHARACTERS**\u000aThe Ambossteins aside, three main factions are competing\u000aagainst each other at the ball. In addition, there are a few\u000auncommitted nobles present, and many of the\u000atown''s leading burghers.\u000aof the Emperor in Ubersreik,\u000aand currently the true power\u000ain the fortress-town.\u000aOver 6-foot tall, she\u000ais in disguise as a\u000aKnight Panther\u000aguarding General\u000avon Dabernick to\u000abetter monitor the\u000alocal politics first\u000ahand. She is keen\u000ato see if she can\u000afind a resolution\u000afor the town''s\u000arulership that\u000awill gather broad\u000asupport.\u000aNacht is not given\u000aany statistics in this adventure\u000aas she will not interact with it\u000adirectly, but may be a part of\u000athe continuing adventures\u000aafter _Lord of Ubersreik_ is\u000aconcluded, especially if\u000ashe should spot a capable\u000a# Gravin Maria-Ulrike\u000a**House Ambosstein House Saponathiem Gravin Maria-Ulrike**\u000aUse the statistics on pages 16-18 for the gravin and her staff. The\u000astatistics for Seedling the Halfling can be found on page 21. She\u000awears a white mask decorated with a single red heart over her\u000aright eye, and is on her very best behaviour.\u000a**House Holzenhauer Lord Erich von Holzenauer**\u000aLord Erich recently distinguished himself as a pistolier in the\u000aGrey Mountains facing Greenskins, leaving him very popular\u000awith the local Ubersreik''s garrison. This also makes him\u000asomewhat less popular with the Altdorf State Army currently\u000astationed in Ubersreik, who seem him as a potential rallying\u000afigure of opposition.\u000aHe is a sincere and relatively softly spoken man in his late 30s,\u000awho is oblivious to how dashing and attractive he is to many in\u000athe room. His late wife died giving birth to his only daughter,\u000a-\u000aTheodora now a ferociously intelligent woman who currently\u000astudies in the Imperial Engineer''s School in Altdorf - and he\u000anever remarried. This only makes him a more romantic figure in\u000athe eyes of his many suitors.\u000a**Lord Siegfried von Saponatheim**\u000aLord Siegfried von Saponatheim is the young cousin of Graf\u000aWilhelm von Saponatheim (see page 64). He has never held\u000alands of his own, but has a reputation for understanding business.\u000aIn recent years, the von Saponatheims have become very active\u000apolitically in an attempt to acquire more lands and wealth.\u000aSiegfried is a tall, dark-haired man with a seemingly endless\u000asupply of hunting stories. If anyone mentions Bögenhafen, he\u000awill dismissively mention that he never goes there.\u000aIf the Saponatheims did not do well from _Nastassia''s Wedding_, it''s\u000apossible Graf Wilhelm will attend the Ubersreik party personally\u000ato support his cousin''s political manoeuvers. He will, of course,\u000aturn a blind eye to Siegfried''s liberal use of emetic powder ...'),'[]');
INSERT INTO module_npcs VALUES(114,1,'Unknown NPC (Page 19)','','{"M": "4", "WS": "51", "BS": "35", "S": "43", "T": "62", "I": "44", "Ag": "46", "Dex": "28", "Int": "26", "WP": "44", "Fel": "28", "W": "20"}','');
INSERT INTO module_npcs VALUES(115,1,'Eliza the Servant',unistr('**Eliza the Servant**\u000a''Eliza the servant'' is actually an assassin hired by Baron von\u000aDammenblatz to kill Gravin Maria-Ulrike''s judicial champion.\u000aShe plays the simpering, buxom maid perfectly, quite willing to\u000aput up with any indignity to draw closer to her target.\u000aIf her cover is blown, she will swear in her native Bretonnian, her\u000aperfect Reikspiel a memory, before beating a hasty retreat.\u000a**The ''M orrians '' and their Pursuer The ''Morrians''**\u000aGunni, Bart, and Hans-Frederick are posing as Morrians\u000atransporting a body for burial. They are bedecked in paraphernalia\u000athey stole from a temple of Morr. They speak only in somewhat\u000atheatrical, monotonous tones to maintain their ruse. When not\u000aposing as Morrians, all three men have high-pitched voices with\u000astrong Nulner accents, their tone lifting at the end of every sentence.'),'{"M": "4", "WS": "28", "BS": "32", "S": "40", "T": "39", "I": "37", "Ag": "40", "Dex": "31", "Int": "28", "WP": "25", "Fel": "43", "W": "12"}','');
INSERT INTO module_npcs VALUES(116,1,'Unknown NPC (Page 19)','# The Body','{"M": "4", "WS": "34", "BS": "31", "S": "43", "T": "45", "I": "44", "Ag": "38", "Dex": "36", "Int": "28", "WP": "45", "Fel": "28", "W": "16"}','');
INSERT INTO module_npcs VALUES(117,1,'The Body',unistr('**The Body**\u000aJosef Aufwiegler is the ''body'' the ''Morrians'' carry in their coffin.\u000aAufwiegler is an agitator wanted for inciting riots in Nuln.\u000aAlthough he paid the smugglers to transport him to safety, he\u000adidn''t expect to be drugged. Or put in a coffin. Or be surrounded\u000aby skull-faced Morrians when he woke up! When he does\u000aawaken, confused and addled by the drugs, Josef panics.'),'{"M": "4", "WS": "47", "BS": "48", "S": "59", "T": "50", "I": "36", "Ag": "46", "Dex": "31", "Int": "32", "WP": "46", "Fel": "27", "W": "17"}','wfrp-4e-rough-nights-and-hard-days/images/page_77_img_0.jpeg');
INSERT INTO module_npcs VALUES(118,1,'The Bounty Hunter',unistr('**The Bounty Hunter**\u000aUrsula was raised far to the east on the Kislev Verge, overlooking\u000athe frozen Western Oblast, and has no time for fools. She has\u000aworked as Bounty Hunter for over a decade, and takes grim\u000apride in her work. She has a deep Ostlander accent, meaning\u000ashe pauses before words when stressing them, and is frequently\u000amistaken for a Kislevite.\u000a**The Illicit Lovers and their Pursuers ''Johann Schmidt'' and ''Frau Schmidt''**\u000aThe ''Schmidts'' are ''schmitten'' with each other. For Baron\u000aFreidrich, it''s the ninth time he has been in love with an\u000aunavailable woman, so he knows it''s real. For Fraulein Lastkhan,\u000ashe''s in love for the first time, and it''s a love like no one has ever\u000aloved before. It''s clear to any who pay attention that Freidrich''s\u000afine manners, noble clothing, and cultured accent are not a\u000anatural fit with the name ''Johann Schmidt'', or with the clearly\u000alower-class ''Frau Schmidt''.\u000a# Thomas Prahmhandler and his Thugs'),'{"M": "4", "WS": "45", "BS": "40", "S": "31", "T": "28", "I": "38", "Ag": "37", "Dex": "25", "Int": "46", "WP": "33", "Fel": "73", "W": "10"}','wfrp-4e-rough-nights-and-hard-days/images/page_34_img_0.jpeg');
INSERT INTO module_npcs VALUES(119,1,'Unknown NPC (Page 21)','','{"M": "4", "WS": "46", "BS": "38", "S": "27", "T": "25", "I": "43", "Ag": "27", "Dex": "38", "Int": "46", "WP": "33", "Fel": "52", "W": "9"}','');
INSERT INTO module_npcs VALUES(120,1,'Thomas Prahmhandler and his Thugs',unistr('**Thomas Prahmhandler and his Thugs**\u000aThomas is a powerful man quite used to control, whether with'),'{"M": "4", "WS": "31", "BS": "33", "S": "31", "T": "31", "I": "41", "Ag": "36", "Dex": "32", "Int": "46", "WP": "36", "Fel": "40", "W": "12"}','wfrp-4e-rough-nights-and-hard-days/images/page_20_img_1.png');
INSERT INTO module_npcs VALUES(121,1,'The Cultists Members of the Ordo Ultima',unistr('**The Cultists Members of the Ordo Ultima**\u000aThe Cultists of the _Ordo Ultima_ are far from their home territory of\u000aNuln. So, they nurse drinks, trying their best not to look suspicious\u000aas they watch for Rechtshandler, occasionally muttering made-up\u000aprayers to Verena to cement their cover as travelling scholars. Each\u000acultist has a letter O enclosed within a letter U tattooed on the left\u000abreast, and all talk with urbane Nulner accents.'),'{"M": "4", "WS": "50", "BS": "33", "S": "53", "T": "43", "I": "42", "Ag": "41", "Dex": "29", "Int": "27", "WP": "43", "Fel": "28", "W": "17"}','wfrp-4e-rough-nights-and-hard-days/images/page_20_img_2.png');
INSERT INTO module_npcs VALUES(122,1,'Unknown NPC (Page 21)','# Coachmen and Boatmen','{"M": "4", "WS": "37", "BS": "38", "S": "39", "T": "42", "I": "42", "Ag": "46", "Dex": "35", "Int": "50", "WP": "44", "Fel": "50", "W": "15"}','');
INSERT INTO module_npcs VALUES(123,1,'Other Customers Coachmen and Boatmen',unistr('**Other Customers Coachmen and Boatmen**\u000aThere are a number of coachmen and boatmen, all Human, staying\u000aat the Three Feathers. Most drink themselves to insobriety before\u000a**Glimbrin and Seedling**\u000aGlimbrin, a Gnome from Clan Trethaway, is touring the Empire,\u000alooking to lift useful things to bring home to the burrows of\u000aGlimdwarrow. So far, he hasn''t found much of interest, but he\u000ahas had a lot of fun stealing anything not tied down along the\u000away, and is always on the lookout for his next big score.\u000aGlimdrin features in four of the adventures in the **Rough Nights & Hard Days** campaign, so be sure to give the Characters an\u000aopportunity to encounter him. He will soon become a familiar\u000aface, so it''s recommended you familiarise yourself with his\u000aCharacter Profile. **Note:** his _Suffuse with Ulgu_ Talent, as well as all\u000athe other rules for Gnomes, is detailed in **Appendix 1: Gnomes**\u000aon page 86.'),'{"M": "4", "WS": "34", "BS": "31", "S": "39", "T": "51", "I": "25", "Ag": "32", "Dex": "43", "Int": "45", "WP": "41", "Fel": "43", "W": "17"}','wfrp-4e-rough-nights-and-hard-days/images/page_96_img_1.jpeg');
INSERT INTO module_npcs VALUES(124,1,'Unknown NPC (Page 22)',unistr('# Inn Trouble\u000aSeedling is a Halfling from the distinguished Thorncobble clan\u000aof Altdorf. She''s currently on the run from her responsibilities,\u000aand is looking to earn a little coin with gambling and gossip.\u000aLike most Thorncobbles, she has impeccable diction, and an\u000aupper-class accent that surprises those used to meeting more\u000aearthy Halflings.'),'{"M": "4", "WS": "32", "BS": "37", "S": "52", "T": "54", "I": "51", "Ag": "47", "Dex": "32", "Int": "33", "WP": "28", "Fel": "35", "W": "17"}','');
INSERT INTO module_npcs VALUES(125,1,'The Staff of the Three Feathers The Landlord and his Staff',unistr('**The Staff of the Three Feathers The Landlord and his Staff**\u000aHans Orf, the landlord of the Three Feathers, has a variety of\u000astaff working for him, including barmen, potmen, serving girls,\u000acleaners, ostlers, and Ol'' Bess, the smith.\u000aDo not feel limited by this list. If you wish to add more staff,'),'{"M": "4", "WS": "25", "BS": "37", "S": "14", "T": "34", "I": "37", "Ag": "28", "Dex": "45", "Int": "35", "WP": "39", "Fel": "46", "W": "9"}','');
INSERT INTO module_npcs VALUES(126,1,'Unknown NPC (Page 23)','','{"M": "4", "WS": "35", "BS": "35", "S": "53", "T": "45", "I": "31", "Ag": "32", "Dex": "48", "Int": "28", "WP": "39", "Fel": "28", "W": "16"}','');
INSERT INTO module_npcs VALUES(127,1,'Other Staff',unistr('**Other Staff**\u000aShould you need profiles for any other member of Otto von\u000aDammenblatz''s staff, use the equivalent statistics from the gravins\u000aparty on pages 16-18 .\u000a**The Local Businessmen Racketeers**\u000aA group of racketeers in Alfonzo Kappan''s employ are planning\u000aan explosive escape for their boss. For all they lack intelligence,\u000athey make up for it with enthusiasm and ignorance.'),'{"M": "4", "WS": "40", "BS": "-", "S": "25", "T": "35", "I": "35", "Ag": "35", "Dex": "-", "Int": "5", "WP": "45", "Fel": "-", "W": "10"}','');
INSERT INTO module_npcs VALUES(128,1,'The Cultists Cultists of the Ordo Ultima',unistr('**The Cultists Cultists of the Ordo Ultima**\u000aStatistics for the secretive Cultists of the _Ordo Ultima_ can be\u000afound on page 20.\u000a# Matthias Hubkind\u000a**The Witch Hunter and His Victim Matthias Hubkind**\u000aThe most promising orphan raised by the flagellant Order of the\u000aThree Brothers in a generation, Hubkind came to Altdorf 40\u000ayears ago to train as a Witch Hunter. He now has three decades\u000aof experience burning the enemies of Sigmar, and he tirelessly\u000apursues this holy duty. He is suspicious of everyone and rarely\u000aspeaks, except to sonorously pronounce judgement on heretics.\u000aThough deep into his 50s, Matthais''s body is still strong, and\u000ahis will is even stronger. His back is a lattice of scars won from\u000adecades of purifying his soul with blessed pain.\u000a**The Ghost**\u000aThe enraged Ghost has no recollection of who it was in life. Nor\u000adoes it know why it screams with hatred for Matthias Hubkind.\u000aBut it does scream, its torment is unbearable, and it will not stop\u000auntil it has had its revenge.\u000aThe Ghost appears as a billowing cloud of indistinct green and\u000aash white robes topped with a distended skull twisted with hatred\u000aand pain. Tarnished bells hang from rusted manacles about its\u000awrists, each of which resound far too deeply given their relatively\u000asmall size.'),'{"M": "4", "WS": "45", "BS": "37", "S": "50", "T": "54", "I": "32", "Ag": "34", "Dex": "28", "Int": "25", "WP": "43", "Fel": "31", "W": "19"}','wfrp-4e-rough-nights-and-hard-days/images/page_33_img_1.jpeg');
INSERT INTO module_npcs VALUES(129,1,'The Bounty Hunter Ursula Kopfgeld',unistr('**The Bounty Hunter Ursula Kopfgeld**\u000aUrsula Kopfgeld''s full Character Profile can be found on page 19.\u000a**The Opportunistic Thief Glimbrin Oddsocks**\u000aGlimbrin Oddsock''s mischievous statistics can be found on page\u000a21.'),'{"M": "4", "WS": "40", "BS": "-", "S": "30", "T": "32", "I": "35", "Ag": "43", "Dex": "18", "Int": "14", "WP": "45", "Fel": "-", "W": "13"}','');
INSERT INTO module_npcs VALUES(130,1,'Unknown NPC (Page 35)',unistr('# The Magistrates\u000a**The Court Dignitaries The Magistrates**\u000aJovial Magistrate Hannes Richter is in his 60s and dyes his hair\u000ain a failed attempt to appear younger. Magistrate Hanna Anwalt\u000ais near blind, relying on Assistant Magistrate Gerhard Urteil to\u000anavigate. Urteil is theoretically a powerful man, but in actuality is\u000alittle more than Anwalt''s eyes, ears, and general dogsbody.'),'{"M": "4", "WS": "55", "BS": "51", "S": "43", "T": "46", "I": "38", "Ag": "27", "Dex": "27", "Int": "35", "WP": "58", "Fel": "37", "W": "29"}','');
INSERT INTO module_npcs VALUES(131,1,'The Priestess of Verena',unistr('**The Priestess of Verena**\u000aQuiet Mother Steinmetz was blessed by Verena at the tender age\u000aof seven, and has been learning law, justice, and swordplay since\u000athen. Now in her 20s, she is a rising star in her cult.'),'{"M": "4", "WS": "35", "BS": "38", "S": "30", "T": "26", "I": "47", "Ag": "24", "Dex": "34", "Int": "55", "WP": "45", "Fel": "48", "W": "11"}','');
INSERT INTO module_npcs VALUES(132,1,'The Followers of Khorne Watchmen',unistr('**The Followers of Khorne Watchmen**\u000aThe End Times are coming, and these watchmen fully embrace\u000ait, knowing all else is folly. Blood for the Blood God. Skulls for\u000athe Throne of Khorne.'),'{"M": "4", "WS": "55", "BS": "35", "S": "41", "T": "43", "I": "56", "Ag": "39", "Dex": "35", "Int": "72", "WP": "63", "Fel": "56", "W": "18"}','');
INSERT INTO module_npcs VALUES(133,1,'Daemons of Khorne',unistr('**Daemons of Khorne**\u000aBloodletters kill anything in their path, caring only that blood\u000aflows. To make this encounter more challenging or climatic, add\u000aMutations or the _Elite_, _Fast_, _Hardy_, or _Tough_ Creature Traits.'),'{"M": "4", "WS": "55", "BS": "45", "S": "35", "T": "35", "I": "30", "Ag": "30", "Dex": "30", "Int": "25", "WP": "55", "Fel": "25", "W": "17"}','wfrp-4e-rough-nights-and-hard-days/images/page_35_img_1.png');
INSERT INTO module_npcs VALUES(134,1,'Unknown NPC (Page 36)',unistr('# Following the Campaign\u000a# - - A NIGHT AT THE OPERA\u000aTo celebrate her victory in the trial, Gravin Maria-Ulrike von\u000aLiebwitz of Ambosstein is invited to the opera by her illustrious\u000aaunt, Grand Countess Emmanuelle von Liebwitz of Nuln.\u000aUnfortunately for our Heroes and their employer, the defeated\u000aBaron Otto von Dammenblatz thirsts for revenge, and a number\u000aof other parties are also up to no good at the opening night of\u000a_Otenno_ .\u000a**LOCATION**\u000aNuln is a city famed for its culture, and the Staatsoper theatre,\u000asituated in the wealthy Altestadt district, is one of the jewels in its\u000acrown. It is located on the great Commercial Way that separates\u000athe aristocratic Schlossfels district from the mercantile Kaufmann\u000aDistrict. Lavishly decorated inside and out, it is a temple to art\u000aand culture, and draws folk from across the Old World to witness\u000aits extraordinary productions first-hand.\u000a**GETTING THERE**\u000aThe city-state of Nuln stands proud at the confluence of the rivers\u000aReik and Aver. Well-maintained roads spiderweb outwards from\u000aNuln in all directions, and are always heavy with traffic. Once\u000athe Imperial Capital, Nuln is a city now famous for extravagant\u000aparties, high culture, and advanced industry. Because of this, it is\u000aa natural destination for those looking for trade, employment, or\u000aopportunities of a more mercenary kind.\u000a**Following the Campaign**\u000aIf you intend to play through the **Rough Nights &Hard Days**\u000acampaign, the adventurers accompany Gravin Maria-Ulrike von\u000aLiebwitz back to Nuln in triumph after her acquittal of all charges\u000aat the trial in Kemperbad. The journey is a straightforward one,\u000afollowing the Reik directly upstream, and shouldn''t take more\u000athan a few days with favourable weather.'),'{"M": "4", "WS": "55", "BS": "35", "S": "45", "T": "35", "I": "60", "Ag": "40", "Dex": "30", "Int": "25", "WP": "75", "Fel": "15", "W": "17"}','');
INSERT INTO module_npcs VALUES(135,1,'Brecht Kavenner, Lawyer',unistr('**Brecht Kavenner, Lawyer**\u000aNasal-voiced Kavenner is the Countess''s personal lawyer. Known\u000aas a stern, dedicated man who is utterly devoted to his wife,\u000achildren, and the Cult of Verena, he uses this good reputation to\u000adisguise his second life as one of the most successful and depraved\u000acultists of the _Ordo Ultima_ . Tasked three years ago to corrupt the\u000aCountess to the service of the Prince of Pleasure, he has found\u000aher inexplicably intractable. This confuses and annoys him in\u000aequal measure, which he invariably takes out on his inferiors.'),'{"M": "4", "WS": "48", "BS": "31", "S": "31", "T": "38", "I": "67", "Ag": "51", "Dex": "57", "Int": "59", "WP": "68", "Fel": "80", "W": "15"}','wfrp-4e-rough-nights-and-hard-days/images/page_42_img_0.jpeg');
INSERT INTO module_npcs VALUES(136,1,'Royal Servants and Guards',unistr('**Royal Servants and Guards**\u000aThe Countess goes nowhere without her many servants, attendants,\u000aand guards. Contrary to popular rumour, they are not all bronzed\u000agods and goddesses, chosen because they amuse the Countess''s\u000ataste. However, most _are_ drawn from the the lesser Noble Houses\u000aof Nuln as commoners do not normally attend royalty.\u000aUnlike many of the Elector Counts, the Countess chooses not to\u000asurround herself with guards drawn from the Knightly Orders,'),'{"M": "4", "WS": "32", "BS": "35", "S": "32", "T": "48", "I": "53", "Ag": "26", "Dex": "23", "Int": "69", "WP": "55", "Fel": "58", "W": "20"}','');
INSERT INTO module_npcs VALUES(137,1,'Unknown NPC (Page 49)','# Servants, Musicians, Performers, and Stagehands','{"M": "4", "WS": "29", "BS": "31", "S": "34", "T": "37", "I": "49", "Ag": "40", "Dex": "33", "Int": "47", "WP": "30", "Fel": "45", "W": "12"}','');
INSERT INTO module_npcs VALUES(138,1,'Opera House Staff Servants, Musicians, Performers, and Stagehands',unistr('**Opera House Staff Servants, Musicians, Performers, and Stagehands**\u000aThe Staatsoper theatre employs staff of all kinds to service and\u000aentertain Nuln''s cultured elite. Use the following samples should\u000astatistics for these be needed.'),'{"M": "4", "WS": "59", "BS": "55", "S": "47", "T": "43", "I": "43", "Ag": "47", "Dex": "30", "Int": "28", "WP": "68", "Fel": "38", "W": "22"}','');
INSERT INTO module_npcs VALUES(139,1,'Unknown NPC (Page 50)','','{"M": "4", "WS": "34", "BS": "35", "S": "41", "T": "34", "I": "32", "Ag": "40", "Dex": "33", "Int": "34", "WP": "29", "Fel": "49", "W": "12"}','');
INSERT INTO module_npcs VALUES(140,1,'The Dammenblatz Agents',unistr('**The Dammenblatz Agents**\u000aBaron Otto von Dammenblatz has ordered his two spies\u000ain Nuln - Brocks and Reiner - to finally put an end to his\u000aLiebwitz problem. Both have gritty, street accents, and neither are\u000aespecially good at their jobs. If Dominique is still alive, she is sent\u000ato lead them, which she immediately resents and hates, given she\u000aprefers to work alone. She cuts her hair short for the assignment\u000aand dyes it red, and adopts a broad Stirlander accent that could\u000anot sound more ''farmer'' if she tried. Use the Character Profile on'),'{"M": "4", "WS": "35", "BS": "31", "S": "52", "T": "46", "I": "31", "Ag": "40", "Dex": "34", "Int": "25", "WP": "27", "Fel": "27", "W": "15"}','');
INSERT INTO module_npcs VALUES(141,1,'Unknown NPC (Page 50)',unistr('# Professor Erwin Pakker and his students\u000a**The Gunnery School The Outraged Actor and ''F riends '' Professor Erwin Pakker and his students**\u000aProfessor Pakker is old, bearded, and almost deaf, though\u000ahe pretends to hear just fine. He blusters and huffs as he\u000alectures those around him - he rarely simply ''speaks'' - and\u000afrequently stares into open space, seemingly oblivious to world.\u000aHis students, by comparison, are boisterous, opinionated, and\u000afrequently drunk, a situation the professor does absolutely\u000anothing to resolve.\u000a**Edvard and Edwina Lowenhertz**\u000aEdvard Lowenhertz has a rich voice that oozes stagey melodrama,\u000aeven when discussing the weather. His daughter, Edwina, is in\u000aawe of her father, and has proactively encouraged him for years\u000ato take his revenge against those who criticised him. After all, it\u000abreaks her heart when her father reads and rereads those early\u000areviews; that''s when tears flow and hopelessness rules. To ensure\u000ashe isn''t recognised in the theatre - for she attends shows there\u000afrequently - Edwina wears a false moustache that is unlikely\u000ato fool anyone.'),'{"M": "4", "WS": "33", "BS": "36", "S": "36", "T": "34", "I": "29", "Ag": "30", "Dex": "39", "Int": "27", "WP": "27", "Fel": "35", "W": "11"}','');
INSERT INTO module_npcs VALUES(142,1,'Unknown NPC (Page 51)',unistr('# Detlef Sierck\u000a**Detlef Sierck**\u000aSierck is a genius, a fact even he can''t deny. Actor, playwright,\u000aand poet without compare, even his greatest critics don''t doubt\u000ahis brilliance. Up close and away from the stage make-up, it''s\u000aclear Detlef has lived the good life for a year or two too long:\u000ahe has a soft gut that he wraps in a corset when on-stage, and is\u000aprobably older than the 36 years he claims, perhaps much older.\u000aHe wears his moustaches unfashionably long - to better hide\u000ahis browning teeth - and he looks haunted when left alone.\u000aHowever, when he turns on the charm, the dashing leading man\u000ahe has perfected after many years of extraordinary performances\u000acomes to life, and few are left unimpressed.\u000a**Oldenhaller '' s Enemies The Valantina, the Schatzenheimer, and the Huydermans**\u000aThree rival, criminal gangs - the Valentinas, the Schatzenheimers,\u000aand the Huydermans - have each sent an assassin to the\u000aStaatsoper Theatre, and each intends to be the one to kill the\u000atarget: Albrecht Oldenhaller. However, Oldenhaller has some\u000aunlikely protectors in the form of the Nurgle-worshipping Cult\u000aof the Hallowed Larva, so the assassins have much more than\u000atheir gang rivals to worry about.\u000aUse the same statistics for all three assassins with the modifications\u000amarked below.'),'{"M": "4", "WS": "34", "BS": "31", "S": "32", "T": "33", "I": "57", "Ag": "49", "Dex": "36", "Int": "57", "WP": "32", "Fel": "46", "W": "12"}','');
INSERT INTO module_npcs VALUES(143,1,'Unknown NPC (Page 52)',unistr('# New Lore of Nurgle Spell: Reveal the Inner Beauty\u000a**The Cult of the Hallowed Larva**\u000aMartyn Ruchen has a feverish glint in his eye as he rubs his\u000awarty hands with glee. A gem holy to Nurgle, the Choas god\u000aof Disease and Despair, will soon be in his hands, and he can\u000abarely contain his excitement. All he needs to do is capture\u000aAlbrecht Oldenhaller!\u000aRuchen has led the local cell of the Cult of the Hallowed Larva\u000afor three months - he recently watched on, tears of joy in his\u000aeyes, as the previous priestess was claimed by the Plague Lord\u000aas she died of a multitude of beautiful, blossoming diseases -\u000aand he is keen to do at least as well as his predecessor.\u000aIf engaged in conversation, Martyn will mumble apologies in\u000ahis wheezy voice and quickly retreat to his cultist friends, all of\u000awhom are dressed as grubby merchants. Martyn smells vaguely\u000aof rotten, sweaty ham.'),'{"M": "5", "WS": "44", "BS": "36", "S": "34", "T": "37", "I": "42", "Ag": "47", "Dex": "31", "Int": "37", "WP": "33", "Fel": "41", "W": "15"}','');
INSERT INTO module_npcs VALUES(144,1,'The Thief Glimbrin Oddsocks',unistr('**The Thief Glimbrin Oddsocks**\u000aSince arriving in Nuln, Glimbrin has been enthralled by the city''s\u000aextensive use of blackpowder weapons, and has decided to secure\u000asome of the best examples for when he returns to Glimdwarrow.\u000aThe statistics for the wily Gnome thief can be found on page 21.'),'{"M": "4", "WS": "38", "BS": "32", "S": "34", "T": "49", "I": "33", "Ag": "28", "Dex": "30", "Int": "29", "WP": "36", "Fel": "26", "W": "18"}','');
INSERT INTO module_npcs VALUES(145,1,'Unknown NPC (Page 53)',unistr('# Matthias Hubkind\u000a**The Witch Hunter Matthias Hubkind**\u000aThe Character Profile for the ever-vigilant Matthias can be found\u000aon page 34. His accomplices, spies, enforcers, and thugs use the\u000afollowing general statistics.'),'{"M": "4", "WS": "43", "BS": "37", "S": "32", "T": "57", "I": "43", "Ag": "33", "Dex": "33", "Int": "43", "WP": "57", "Fel": "43", "W": "28"}','');
INSERT INTO module_npcs VALUES(146,1,'Extras and Onlookers The Watch',unistr('**Extras and Onlookers The Watch**\u000aThe Watch and guards of various types are found throughout the\u000atheatre, and patrolling outside. The Countess is in attendance, so\u000athey are all keen to impress.\u000a**Watch Sergeants**\u000aMost of the Watch patrols are led by sergeants, as their superiors\u000aare determined that nothing will go wrong given the Countess\u000aherself is under their protection.\u000aHowever, most of these representatives of the Watch are selfimportant, preening, and all-too-often involved in criminal\u000aactivity themselves.'),'{"M": "4", "WS": "33", "BS": "26", "S": "43", "T": "31", "I": "27", "Ag": "32", "Dex": "31", "Int": "25", "WP": "36", "Fel": "30", "W": "16"}','');
INSERT INTO module_npcs VALUES(147,1,'Operagoers',unistr('**Operagoers**\u000aThe theatre is choked with operagoers of all types, most of whom\u000aare wealthy burghers from Nuln. They all rub shoulders with each\u000aother as they drink, gossip, try to catch the Countess''s eye, then\u000amake their way to their seats.\u000aAdd any appropriate Traits, Skills, or Talents if you feel some\u000aunique Characters are required.'),'{"M": "4", "WS": "51", "BS": "51", "S": "43", "T": "41", "I": "36", "Ag": "30", "Dex": "34", "Int": "38", "WP": "58", "Fel": "40", "W": "17"}','');
INSERT INTO module_npcs VALUES(148,1,'Young Nobles',unistr('**Young Nobles**\u000aThere is turmoil building across the Empire (see the **Enemy Within** campaign for more on this), so many of the local nobles,\u000aespecially the Toppenheimers and Pfiefrauchers, are spoiling for\u000aa fight.'),'{"M": "4", "WS": "28", "BS": "25", "S": "28", "T": "31", "I": "33", "Ag": "32", "Dex": "37", "Int": "43", "WP": "30", "Fel": "39", "W": "11"}','wfrp-4e-rough-nights-and-hard-days/images/page_66_img_0.jpeg');
INSERT INTO module_npcs VALUES(149,1,'Unknown NPC (Page 54)',unistr('# Following the Campaign\u000a# - - NASTASSIA''S WEDDING\u000aA society wedding at the castle of a House Saponathiem offers a\u000awelcome break after the stresses of the trial, but the happy event,\u000aas our Heroes will find out, turns out to be anything but restful.\u000a**LOCATION**\u000aSchloss Grauenberg is the seat of House Saponatheim, an\u000aancient and storied bloodline that can trace its roots back to the\u000aTime of Sigmar. The venerable castle is situated in the heart of\u000athe Reikland, and has frequently stood as a near impenetrable\u000adefensive bastion during times of war. It stands on a rock above\u000athe River Bögen, some 40 miles downstream of the influential\u000atrading town of Bögenhafen.\u000aThe von Saponatheims may be an ancient family, but they have\u000afallen on hard times, and are looking outwards to expand their\u000ainfluence once again.\u000a**GETTING THERE Following the Campaign**\u000aIn the **Rough Nights and Hard Days** campaign, the wedding\u000abetween Baron Karl-Heinz von Liebwitz of Ambosstein and\u000aBaroness Nastassia von Saponatheim was arranged in simpler\u000atimes, long before the soup-based death of Baron Otto von\u000aDammenblatz and the trial of Gravin Maria-Ulrike. The two\u000awere betrothed as children, and the first arrangements for the\u000awedding were put in place then, many years ago. A small thing\u000alike a law-suit and a judicial combat would never be permitted\u000ato disrupt such important matters, although it is acknowledged\u000athat the timing of the trial is rather unfortunate. However, with\u000athe legal matters resolved, one way or another, Gravin MariaUlrike and her retinue - including the Characters - are able to\u000aattend. the wedding without fear of a summons from the courts\u000aof Kemperbad.'),'{"M": "4", "WS": "31", "BS": "31", "S": "33", "T": "41", "I": "36", "Ag": "30", "Dex": "34", "Int": "38", "WP": "28", "Fel": "30", "W": "17"}','');
INSERT INTO module_npcs VALUES(150,1,'The Gravin '' s Party',unistr('**The Gravin '' s Party**\u000aUse the statistics on page 17 for the gravin party-members\u000aattending the wedding. If statistics are required for young Baron\u000aKarl-Heinz von Liebwitz of Ambosstein, use those of a Young\u000aNoble from page 53.\u000a# The Cornered Noblewoman and the low-born Paramour\u000a**The Dammenblatz Agent**\u000aUse the Dammenblatz Agents statistics on page 49 unless\u000aDominique is somehow still alive. If so, use her instead (see\u000apage 18). This time, with her curly brown-haired wig and her\u000aconvincing Reiklander accent, she is determinedto bring this\u000asorry chapter to an end.\u000a**The Young Lovers The Cornered Noblewoman and the Low-born Paramour**\u000aNastassia is everything her father is not: short, sweet, and quite\u000awilling to run away from her duties for love. Joachim Bitterfeld\u000ahas captured her heart completely, and she is determined to\u000amarry her brave man. Although the practicalities of hiding her\u000afrightfully upper-class accent, and of life without servants, has yet\u000ato cross her mind, Joachim is practical; indeed, he has done most\u000aof the planning to effect Nastassia''s escape.\u000a**The Outraged Spirit Nehekharan Wraith**\u000aInta-Dapesht''s soul is tied to the blade he carried in life. So, now\u000ahis rest is disturbed, he will kill any who stop his sword being\u000areturned to its rightful resting place.'),'{"M": "4", "WS": "57", "BS": "51", "S": "31", "T": "50", "I": "55", "Ag": "38", "Dex": "52", "Int": "61", "WP": "46", "Fel": "49", "W": "17"}','');
INSERT INTO module_npcs VALUES(151,1,'Unknown NPC (Page 66)',unistr('# Albrecht the Fish’s Thugs\u000a**The Unpaid Debt Albrecht the Fish''s Thugs**\u000aGeert and Jan are two of Albrecht the Fish''s most capable and\u000apresentable thugs. But, no matter how much they try to fit\u000ain, they can''t even manage to get that right. Their demeanour,\u000amanner, and their sing-song Marienburger accents make them\u000aconspicuous. They are unmistakable to any that pay attention.\u000aUse the statistics supplied for the thugs Mho, Larz, and ''Curls''\u000a**The Deviants and Decadents Slaanesh Cultists**\u000aThese foolish, young nobles are lost to the pursuit of endless\u000aindulgence in forbidden pleasures, and seek nothing more than\u000ato slake their dark thirst on the wine-dark blood of their peers.\u000aThis isn''t the first time they''ve summoned Daemonettes. And,\u000ashould they get their way, it will not be the last.'),'{"M": "4", "WS": "35", "BS": "30", "S": "44", "T": "46", "I": "28", "Ag": "32", "Dex": "43", "Int": "32", "WP": "27", "Fel": "48", "W": "14"}','');
INSERT INTO module_npcs VALUES(152,1,'The Hidden Heir Manfred von Saponatheim',unistr('**The Hidden Heir Manfred von Saponatheim**\u000aManfred is House Saponatheim''s secret shame. Locked away\u000afar from prying eyes for almost three decades, the true heir to\u000athe duchy of Saponatheim is about to have his revenge. Largely\u000aincapable of speech, Manfred communicates through sad grunts\u000aand moans. Should he ever cut his wild hair and trim his matted\u000abeard, most would be astounded by just how much Manfred'),'{"M": "4", "WS": "26", "BS": "32", "S": "34", "T": "29", "I": "33", "Ag": "28", "Dex": "30", "Int": "36", "WP": "36", "Fel": "43", "W": "10"}','');
INSERT INTO module_npcs VALUES(153,1,'Unknown NPC (Page 67)',unistr('# The Dowager-Duchess of Telland\u000a**The Stolen Jewel The Dowager-duchess of Telland**\u000aThe dowager-duchess is on the prowl for her fourth husband\u000aafter her third had an unfortunate barging accident in the canals\u000aof Telland. She''s loud, flirtatious, and keen to display her giant\u000agem to any who are interested in gazing at her ample bosom.'),'{"M": "4", "WS": "35", "BS": "34", "S": "48", "T": "45", "I": "22", "Ag": "31", "Dex": "26", "Int": "15", "WP": "25", "Fel": "18", "W": "18"}','');
INSERT INTO module_npcs VALUES(154,1,'Taggee Agents',unistr('**Taggee Agents**\u000aRaja Shrimant Rao of Ind has sent his best _taggee_ agents to secure\u000ahis rose ruby. Two are trained to fight with Tiger Claws, which\u000aappear like knuckledusters with four projecting blades. Tiger\u000aClaws use the same statistics as a Dagger but need the Melee\u000a(Brawling) Skill, and uses the following additional rules: on a\u000asuccessful Melee (Brawling) Test, you can make any resulting\u000awound appear as if it were caused by a big cat or similar animal.'),'{"M": "4", "WS": "34", "BS": "32", "S": "29", "T": "27", "I": "45", "Ag": "34", "Dex": "45", "Int": "36", "WP": "31", "Fel": "53", "W": "11"}','wfrp-4e-rough-nights-and-hard-days/images/page_67_img_0.jpeg');
INSERT INTO module_npcs VALUES(155,1,'The Wraith',unistr('**The Wraith**\u000aAs Graf Josef, the Wraith plays the role of a charming but dimwitted young noble, with no interests outside the latest fashion\u000aand gossip. As the Wraith, Graf Josef is witty, charming, and\u000aalways ready with a quip should the chance arise.'),'{"M": "5", "WS": "56", "BS": "54", "S": "38", "T": "43", "I": "45", "Ag": "49", "Dex": "38", "Int": "43", "WP": "57", "Fel": "41", "W": "16"}','');
INSERT INTO module_npcs VALUES(156,1,'The Gnome Thief',unistr('**The Gnome Thief**\u000aGlimbrin Oddsocks has padded up his clothes and come to the\u000awedding in disguise as a well-to-do Halfling, and has assumed\u000athe refined accent of the illustrious Thorncobble clan to pull off\u000ahis ruse, but it''s hardly convincing to anyone who knows Gnomes\u000aexist.\u000aThe wily Gnome''s statistics can be found on page 21.\u000a# Following the Campaign\u000a# - - LORD OF UBERSREIK\u000aUbersreik has no ruling family after the Emperor controversially\u000aremoved House Jungfreud from power. Thus, the great and the\u000agood flock to the fortress town, all hoping to become the next\u000alord or lady of Ubersreik. One noble decides to host a society ball\u000ato promote his House above the others, but it quickly becomes\u000aa battlefield - politically and otherwise - and our Heroes are\u000acaught in the middle of it.\u000a**LOCATION**\u000aLord Erich von Holzenauer, one of the nobles who wants to be\u000athe new lord of Ubersreik, has rented a mansion in Morgenseite,\u000aUbersreik''s most exclusive district. There he plans a lavish\u000amasquerade ball, and intends to use the occasion to gain the upper\u000ahand over his political opponents. Fortunately for von Holzenauer,\u000athe estate is already furnished - its owner fled in somewhat of a\u000arush when Ubersreik was recently invaded by the Emperor''s forces.\u000a**GETTING THERE Following the Campaign**\u000aIn the **Rough Nights & Hard Days** campaign, Gravin MariaUlrike is one of the nobles with an interest in the lordship of\u000aUbersreik. If the wedding between her brother Karl-Heinz and\u000aGravin Nastassia von Saponatheim went ahead (see _Nastassia''s_\u000a_Wedding_ ), Gravin Maria-Ulrike arrives to add her family''s\u000asupport to Lord Siegfried von Saponatheim; if not, she is there\u000aon behalf of her brother, Karl-Heinz.\u000aGravin Maria-Ulrike and her retinue - including the Characters\u000a- either arrive by road from Bögenhafen in a caravan of coaches\u000aand carts, or arrive by barge via the Hagercryb Canal. After\u000aentering Ubersreik, they travel to Morgenseite - a wealthy district\u000aon the south-east of the town known locally as the Hill - where\u000athe gravin has rented a modest mansion as a base of operations.'),'{"M": "5", "WS": "51", "BS": "51", "S": "60", "T": "32", "I": "61", "Ag": "74", "Dex": "89", "Int": "61", "WP": "62", "Fel": "83", "W": "15"}','wfrp-4e-rough-nights-and-hard-days/images/page_67_img_2.jpeg');
INSERT INTO module_npcs VALUES(157,1,'Unknown NPC (Page 81)',unistr('# Baron Heinrich von Falkenhayn\u000a**House Aschaffenberg Other Nobles Baron Rickard Aschaffenberg and Lord Maximillian Aschaffenberg**\u000aBaron Rickard Aschaffenberg is an enormous man in his 30s, though\u000ahis lifetime of war and good eating leave him looking much older.\u000aHis long dark-ginger beard hides a spreading belly, and a surprising\u000aamount of muscle. His voice booms whenever he talks, and it seems\u000ahe loves to talk. Rickard stands in stark contrast to his much shorter,\u000amischievous nephew, Lord Maximilian Aschaffenberg. Maximilian\u000ahas no interest in the political side of the ball, and instead insults and\u000ahumiliates the Bruners at every opportunity.\u000a**Lord Bruner and Lady Hohengolfrid**\u000aEnormously rich Lord Heinrich von Bruner is at the ball at the\u000aorder of his mother, Lady Kisaya Bruiner: she is not pleased with\u000acurrent rumours circulating Ubersreik concerning the piety of her\u000afamily. So, he is putting his best face forward with damage control\u000ain mind, which is why he is in attendance with the almost saintly\u000aLady Galina Hohengolfrid, a woman with an extraordinarily\u000agood reputation in Ubersreik, for all that most of it is based in\u000alies. Lord Heinrich intends to show that his family as a whole\u000ais loyal to the Empire, and that rumours concerning taint in his\u000ahousehold are false. If possible, he also wants to embarrass the\u000aAschaffenbergs, whom he believes are his most likely rivals for\u000acontrol of Ubersreik.'),'{"M": "4", "WS": "53", "BS": "39", "S": "35", "T": "32", "I": "48", "Ag": "36", "Dex": "50", "Int": "36", "WP": "27", "Fel": "57", "W": "11"}','');
INSERT INTO module_npcs VALUES(158,1,'Unknown NPC (Page 82)',unistr('# Bruner and Hohengolfrid\u000a**Baron Heinrich von Falkenhayn**\u000aHeinrich hails from the market town of Stimmingen in the\u000aduchy of Falkenhayn to the south. He''s in his early 40s and has\u000aa careful eye for the evening''s proceedings, which he will report\u000aback to his father, Graf Wolfgang von Falkenhayn. Heinrich has\u000aa cutting wit and a dry sense of humour.'),'{"M": "4", "WS": "34", "BS": "31", "S": "29", "T": "26", "I": "36", "Ag": "37", "Dex": "42", "Int": "37", "WP": "21", "Fel": "39", "W": "8"}','');
INSERT INTO module_npcs VALUES(159,1,'Jean-Luc de Cadent, Baron de Grenouille',unistr('**Jean-Luc de Cadent, Baron de Grenouille**\u000aBaron Jean-Luc''s costume is the most elaborate at the ball. He is\u000aarrayed in cloth-of-gold and silk and dressed as a Bretonnian Knight,\u000acomplete with a papier-mâché horse. He has trouble negotiating\u000adoors, but this doesn''t bother him at all as he smiles and waves. His\u000atrue purpose is to report back to the Duc de Parravon about the\u000acompeting factions in Ubersreik. Reikspiel is a second language for\u000ahim, so he speaks with an outrageous Bretonnian accent.'),'{"M": "4", "WS": "44", "BS": "35", "S": "32", "T": "37", "I": "67", "Ag": "33", "Dex": "48", "Int": "48", "WP": "38", "Fel": "41", "W": "12"}','');
INSERT INTO module_npcs VALUES(160,1,'Lord Florian Pfiefraucher',unistr('**Lord Florian Pfiefraucher**\u000aFlorian has been sent by his uncle, Graf Bruno Pfiefraucher,\u000ato represent his illustrious family. He is instructed to make any\u000aalliances that will advance Pfeifraucher interests and those of\u000atheir friends the von Liebwitzes.\u000aUnfortunately for his Graf Bruno, and anyone associated with\u000athe Pfiefrauchers, Florian has no interest in politics, and simply\u000awishes to have as much of a good time as possible, preferably with\u000afree-flowing alcohol, good food, and better company. And if he\u000acan''t secure that, bad company will do.'),'{"M": "4", "WS": "69", "BS": "24", "S": "36", "T": "34", "I": "54", "Ag": "68", "Dex": "44", "Int": "32", "WP": "61", "Fel": "53", "W": "12"}','');
INSERT INTO module_npcs VALUES(161,1,'Unknown NPC (Page 83)',unistr('# Bruner and Hohengolfrid\u000a**Leading Townsfolk The Brewer**\u000aBorgan Foambeard is a local brewer of some repute. He is broadshouldered and dour, spending most of his time monitoring his\u000astaff as they organise drinks in the Dining Room. He has little\u000ainterest in ''maning business'', and has no desire to be part of a\u000amasquerade, but Hozenauer is paying good gold for his beer, so\u000ahe''ll frown through it as best he can manage.'),'{"M": "4", "WS": "47", "BS": "32", "S": "33", "T": "32", "I": "45", "Ag": "37", "Dex": "46", "Int": "31", "WP": "24", "Fel": "32", "W": "11"}','');
INSERT INTO module_npcs VALUES(162,1,'The Physicians'' Guildmaster',unistr('**The Physicians'' Guildmaster**\u000aDoktor Otto Krupp has no real interest in politics. He is\u000aattending the party largely to tout his services and have a good\u000atime with his mistress. If any Character is ill or wounded, Krupp\u000aquickly latches on to them in the hope of making coin.'),'{"M": "4", "WS": "44", "BS": "37", "S": "51", "T": "55", "I": "33", "Ag": "25", "Dex": "64", "Int": "39", "WP": "64", "Fel": "32", "W": "21"}','');
INSERT INTO module_npcs VALUES(163,1,'The Burgomeister',unistr('**The Burgomeister**\u000aUnder the Jungfreuds, Ernst Maler''s position was administrative\u000aonly, but when Ubersreik was seized from the Jungfreuds by the\u000aState Army of Altdorf, suddenly ''Burgomeister'' meant something.\u000aMaler now has massive ambitions: he wants Ubersreik to be a\u000afree town, ruled by his town council, not another noble. So, whilst\u000aMaler is polite and deferential on the surface, every action he\u000atakes is premediated in order to further his goals and weaken his\u000aopponents in any way he can. Everything Maler does is in the\u000apursuit of his goal to be the next Lord of Ubersreik.'),'{"M": "4", "WS": "33", "BS": "23", "S": "27", "T": "36", "I": "52", "Ag": "45", "Dex": "57", "Int": "59", "WP": "56", "Fel": "48", "W": "13"}','');
INSERT INTO module_npcs VALUES(164,1,'Unknown NPC (Page 84)',unistr('# Sigmar, Verena, and Shallya\u000a**The High Elf Envoy**\u000aLorith Silverleaf is attending the party out of curiosity, regarding\u000athe social drama much as a scientist observes a new specimen.\u000aWhile she is undoubtedly arrogant and finds the other species illformed, she will discourse if approached, finding humour in the\u000amost unexpected matters. She speaks softly and has expressive'),'{"M": "4", "WS": "31", "BS": "29", "S": "27", "T": "31", "I": "56", "Ag": "43", "Dex": "46", "Int": "57", "WP": "49", "Fel": "58", "W": "12"}','');
INSERT INTO module_npcs VALUES(165,1,'The Grey Wizard',unistr('**The Grey Wizard**\u000aFew know or understand Christoph Engel, the town''s only native\u000awizard. Engel keeps his own counsel, and presents a different face,\u000aand accent, to every person he meets. He deals with shadows,\u000aillusions, and politics, and is employed by Lady Nacht to test the\u000alocals. He is not provided with Characteristics as he will not engage\u000adirectly with anyone, preferring to slip away and cast his spells\u000a(which can do whatever you feel works best for the scenario) at\u000ahis leisure when none are watching or able to detect his influence.\u000a**Cult Leaders Sigmar, Verena, and Shallya**\u000aThe party has representatives of three of the town''s major\u000acults: Father Gunther Emming, High Priest of Sigmar;\u000aFather Heinrich Gutenberg, High Priest of Verena; and Sister\u000aCelestine Hoch of Shallya. Each is interested in how the city''s\u000apolitics are unfolding.'),'{"M": "4", "WS": "71", "BS": "63", "S": "29", "T": "46", "I": "74", "Ag": "59", "Dex": "43", "Int": "63", "WP": "55", "Fel": "44", "W": "14"}','wfrp-4e-rough-nights-and-hard-days/images/page_84_img_0.png');
INSERT INTO module_npcs VALUES(166,1,'Unknown NPC (Page 85)','# Two Captains','{"M": "4", "WS": "32", "BS": "31", "S": "33", "T": "45", "I": "52", "Ag": "34", "Dex": "36", "Int": "59", "WP": "53", "Fel": "50", "W": "16"}','');
INSERT INTO module_npcs VALUES(167,1,'The State Army The General',unistr('**The State Army The General**\u000aThe young General Jendrik von Debernick is a pompous, puffchested man full of his own self-importance. He will do very\u000alittle at the party besides trying to look impressive, smile at pretty\u000apeople, and give the general impression that, currently, Altdorf\u000aand the Emperor control Ubersreik. He will soon grow bored of\u000aanyone engaging him in conversations concerning politics, and\u000ashow his dissatisfaction by walking away.\u000a**The Two Captains**\u000aPudgy Captain Erwin Blucher of the Magnus Tower and redheaded Captain Andrea Pfeffer of the Ubersreik Watch do\u000anot like each other much. But they find each other''s company\u000ainfinitely preferable to the political battlefield they find\u000athemselves navigating.\u000aUnless otherwise engaged, Andrea will withdraw relatively early\u000ato talk to her men guarding the mansion outside. Blucher will\u000athen turn to beer for his amusement.'),'{"M": "4", "WS": "31", "BS": "34", "S": "32", "T": "32", "I": "50", "Ag": "33", "Dex": "51", "Int": "54", "WP": "53", "Fel": "51", "W": "17"}','');
INSERT INTO module_npcs VALUES(168,1,'Unknown NPC (Page 86)',unistr('# Opinions\u000a# - - APPENDIX 1: GNOMES\u000a**Rough Nights & Hard Days** adds Gnomes from the Mirror\u000aMoors to the pool of possible Player Character options in **WFRP** .\u000a**GNOMES**\u000aAs far as most of the Empire is concerned, Gnomes are a myth,\u000afound only in over-blown Bretonnian romances or Altdorf\u000apfennig-dreadfuls where they frequently appear as magical\u000atricksters. However, there is truth behind the stories, for Gnomes\u000aare not only real, but they live in the Empire.\u000aGnomes - or _Gnommi_ as they call themselves in their native\u000atongue of _Ghassally_ - have a handful of settlements within\u000athe Empire''s borders, but do not mix with the broader Human\u000aBecause of this, Gnomes seeking unquestioned passage through\u000athe Empire often shave any facial hair and wear bulky clothes or\u000apadding to hide their far thinner frames. Whilst this would never\u000afool a Halfling, it is usually enough to convince others.\u000aShort, wiry, with bulbous noses, and large, rounded ears, Gnomes\u000ahave thick hair, dextrous fingers, and gruff voices that can be\u000asurprisingly deep for such diminutive folk. They are a close-knit,\u000aclannish people, putting family and personal loyalty ahead of\u000amost other concerns with a stubborn tenacity that can surprise\u000aeven the most intractable Dwarf. Much as the legends suggest,\u000aGnomes are inherently magical, and share a close relationship\u000awith _Ulgu_, the magical wind of shadows, illusions, and deceit.\u000aGlimdwarrow is the largest Gnome settlement within the Empire,\u000athough rumours claim others lie beneath the Grey Mountains\u000ain Reikland, the Middle Mountains in Middenland, and the\u000aKölsa Hills of Talabecland. Glimdwarrow itself lies hidden below\u000athe Mirror Moors to the south of Middenland, its burrows and\u000ahalls cloaked by powerful illusions and vigilantly guarded by the\u000aDwarrow Guard, an elite unit of warrior-wizards. Glimdwarrow\u000aonce boasted a bustling population of many thousands, but a\u000acentury ago the Greenskin hordes of Grom the Paunch swept\u000athrough the Mirror Moors and massacred almost all the Gnomes\u000ahiding there. Today, Glimdwarrow''s crumbling chambers are\u000alargely empty, and only eight Gnome clans survive. Ruled by\u000atroubled Merawidda Frayne, the Ashen Queen, the leaders of the\u000aremaining clans openly hate each other, each blaming the others\u000afor the horrors Grom''s Greenskins unleashed.\u000a**Opinions On Dwarfs...**\u000a_''Great Mother Tegen thinks she''s stubborn, always talking about ''ow it_\u000a_were Clan Landweth that caused all our problems, and ''ow she won''t_\u000a_be persuaded otherwise. But, as Mabyn is me witness, she ain''t got_\u000a_nothing on they Dwarfs. I''ve seen mountains more moveable when it_\u000a_comes to matters of gold.''_\u000a- Aelyn Thorne, Glimdwarrow Trader\u000a**On Wood Elves...**\u000a_''I ain''t ever met them, and I doubts I ever will. Probably no better_\u000a_than them other hoity-toity Elves from across the water.''_\u000a- Morkam ''Kneebone'', Mirror Moor Farmer'),'{"M": "4", "WS": "69", "BS": "32", "S": "51", "T": "34", "I": "58", "Ag": "32", "Dex": "30", "Int": "54", "WP": "56", "Fel": "47", "W": "19"}','');
